import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Controles do ambiente de execução ACP para habilitar o despacho, selecionar backends, restringir os agentes de destino permitidos e selecionar o comportamento de projeção de turnos em streaming.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Agentes permitidos do ACP`},help:{"v1-f2mw0d-3a":`Lista de IDs de agentes de destino ACP permitidos nas sessões do ambiente de execução ACP. Uma lista vazia significa que não há restrição adicional por lista de permissões.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend do ACP`},help:{"v1-1s1l6bz-2v":`ID do backend padrão do ambiente de execução ACP (por exemplo: acpx). Deve corresponder a um backend de plugin de ambiente de execução ACP registrado.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Agente padrão do ACP`},help:{"v1-7donnu-2c":`ID do agente de destino ACP usado como alternativa quando as inicializações do ACP não especificam um destino explícito.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Despacho do ACP habilitado`},help:{"v1-1ug9t9m-3w":`Controle independente de despacho para turnos de sessão ACP (padrão: true). Defina como false para manter os comandos ACP disponíveis enquanto bloqueia a execução de turnos ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP habilitado`},help:{"v1-1uonl1v-2a":`Controle global do recurso ACP. Mantenha desabilitado, a menos que o ambiente de execução ACP e a política estejam configurados.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Backends alternativos do ACP`},help:{"v1-1wvdifq-5m":`Lista ordenada de IDs de backends alternativos do ACP que serão tentados quando o backend principal falhar com UNAVAILABLE (por exemplo: limite de requisições atingido / cota esgotada). Cada entrada deve corresponder a um backend de plugin de runtime do ACP registrado.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Comando de instalação do runtime do ACP`},help:{"v1-1jjuv9m-39":"Comando opcional de instalação/configuração para o operador, exibido por `/acp install` e `/acp doctor` quando a integração com o backend do ACP não está configurada."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Streaming do ACP`},help:{"v1-1bka5p-2v":`Controles de projeção de streaming do ACP para tamanho dos blocos, visibilidade dos metadados e comportamento de entrega sem duplicações.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Modo de entrega de streaming do ACP`},help:{"v1-19gdmx1-3s":`Estilo de entrega do ACP: live transmite a saída projetada de forma incremental; final_only armazena toda a saída projetada do ACP em buffer até os eventos de encerramento do turno.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Supressão de repetições no streaming do ACP`},help:{"v1-manh32-3d":`Quando definido como true (padrão), suprime linhas repetidas de projeção de status/ferramentas do ACP em um turno, mantendo os eventos brutos do ACP inalterados.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Visibilidade de tags no streaming do ACP`},help:{"v1-1ybhx22-34":`Substituições de visibilidade por sessionUpdate para a projeção do ACP (por exemplo, usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agentes`},help:{"v1-2rc4v8-55":`Raiz da configuração de runtime dos agentes. As seções no mesmo nível da raiz controlam a infraestrutura e os padrões compartilhados entre agentes; agents.defaults controla o comportamento do ciclo do agente; as entradas de agentes podem substituir ambos quando houver suporte.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Padrões do Agente`},help:{"v1-1af7k5b-5a":`Configurações padrão compartilhadas, herdadas pelos agentes, a menos que sejam substituídas por entrada em agents.entries. Use os padrões para garantir um comportamento básico consistente e reduzir configurações duplicadas por agente.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Destino da herança de autenticação`},help:{"v1-2d16wl-2x":`Proprietário do armazenamento de credenciais herdado para compatibilidade com a atualização, até que as credenciais sejam realocadas por agente.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Proprietário da herança de autenticação`},help:{"v1-1a1s7nm-4s":`Agente cujo armazenamento de credenciais legado permanece como fonte da herança após a desativação do marcador de padrão. Gravado automaticamente durante a atualização quando o proprietário anterior não era main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Máximo de caracteres de inicialização`},help:{"v1-drlo3i-37":`Máximo de caracteres de cada arquivo de inicialização do espaço de trabalho inserido no prompt do sistema antes do truncamento (padrão: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Máximo total de caracteres de inicialização`},help:{"v1-1evwsjb-2c":`Máximo total de caracteres em todos os arquivos de inicialização do espaço de trabalho inseridos (padrão: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compactação`},help:{"v1-1qxdwz8-5p":`Comportamento de compactação quando o contexto se aproxima dos limites de tokens, incluindo a estratégia e o comportamento de persistência da memória antes da compactação. Use quando sessões de longa duração precisarem de continuidade estável com janelas de contexto restritas.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Compactação automática integrada`},help:{"v1-1et7vwu-5l":`Ativa a compactação automática proativa integrada (padrão: true). Defina como false para interromper a compactação integrada acionada por limiares, preservando a recuperação de estouro do OpenClaw, a compactação prévia e o comando manual /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Política de identificadores na compactação`},help:{"v1-hby01l-4l":`Política de preservação de identificadores para resumos de compactação: "strict" adiciona ao início as orientações integradas de retenção de identificadores opacos (padrão), enquanto "off" desativa esse prefixo.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Tokens recentes preservados na compactação`},help:{"v1-tgysub-5h":`Quantidade mínima de tokens preservados da janela de conversa mais recente durante a compactação. Use valores mais altos para proteger a continuidade do contexto imediato e valores mais baixos para manter mais histórico antigo.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Limiar de tamanho da transcrição ativa para compactação`},help:{"v1-u715n1-90":`Limiar em bytes que aciona a compactação local prévia normal quando a janela de transcrição vista pelo modelo (desde a última compactação ou redefinição) atinge esse tamanho (bytes ou strings como "20mb"). Defina como 0 ou deixe sem definição para desativar. Também limita as transcrições nativas de execução do app-server do Codex; conversas nativas acima do limite são reiniciadas do zero.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Persistência de memória antes da compactação`},help:{"v1-18q0ve9-55":`Configurações de persistência de memória antes da compactação, que fazem o agente gravar na memória antes de uma compactação intensa. Mantenha ativadas em sessões longas para que o contexto relevante seja persistido antes de cortes agressivos.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Persistência de memória antes da compactação ativada`},help:{"v1-9xllgp-5o":`Ativa a persistência de memória antes da compactação, antes que o ambiente de execução realize uma redução mais intensa do histórico ao se aproximar dos limites de tokens. Mantenha ativada, a menos que você queira desativar os efeitos sobre a memória em ambientes com recursos limitados.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Limiar de tamanho da transcrição para persistência de memória antes da compactação`},help:{"v1-1rzov1e-93":`Força a persistência de memória antes da compactação quando a janela de transcrição visível para o modelo atinge este limiar (em bytes ou strings como "2mb"). Após a compactação, isso inclui o trecho final retido e os turnos subsequentes, em vez do histórico descartado. Use esta opção para evitar travamentos em sessões longas, mesmo quando os contadores de tokens estiverem desatualizados; defina como 0 para desativar.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Substituição de modelo para persistência de memória antes da compactação`},help:{"v1-1r3ctyu-7w":`Substituição opcional de provedor/modelo usada apenas nos turnos de persistência de memória antes da compactação. Defina um modelo local, como ollama/qwen3:8b, quando a extração de memória durável deva evitar o modelo pago da sessão ativa. A substituição é exata e não herda a cadeia de modelos alternativos do modelo ativo.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Limiar flexível de persistência de memória antes da compactação`},help:{"v1-1dqo2l1-5c":`Distância até a compactação (em tokens) que aciona a persistência de memória antes da compactação. Use limiares mais antecipados para uma persistência mais segura ou limiares mais próximos da compactação para reduzir a frequência de persistência.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Verificação prévia de compactação durante o turno`},help:{"v1-am6gbh-6x":`Verificação prévia opcional nos ciclos de ferramentas do OpenClaw integrado que detecta pressão sobre o contexto após a inclusão de um resultado de ferramenta e antes da próxima chamada ao modelo. Quando ativada, o OpenClaw reutiliza a recuperação da verificação prévia existente para truncar resultados de ferramentas ou compactar antes de tentar novamente.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Verificação prévia de compactação durante o turno ativada`},help:{"v1-engbwe-5u":`Ative verificações estruturadas de pressão sobre o contexto durante o turno nos ciclos de ferramentas do OpenClaw integrado. Padrão: false. Mantenha desativado, a menos que sessões longas com uso intenso de ferramentas excedam o limite de contexto antes que a compactação normal ao final do turno possa ser executada.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Modo de compactação`},help:{"v1-1unahwc-76":`Modo da estratégia de compactação: "safeguard" (o padrão efetivo quando não definido) aplica proteções para preservar o contexto recente, enquanto "default" usa a sumarização básica sem essas proteções. Defina "default" somente se a sumarização com proteções causar problemas para seu provedor.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Substituição do modelo de compactação`},help:{"v1-cfeys9-6q":`Provedor/modelo opcional ou alias simples configurado, usado apenas para a sumarização de compactação. Aliases simples são resolvidos antes do envio; um ID literal de modelo configurado tem prioridade se houver conflito com um alias. Deixe sem definir para continuar usando o modelo principal do agente.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Notificar usuário sobre compactação`},help:{"v1-lvymm8-bv":`Quando ativado, envia avisos breves de manutenção de contexto ao usuário: quando a compactação começa e termina (por exemplo, '🧹 Compactando contexto...' e '🧹 Compactação concluída') e quando se esgotam as tentativas de persistir a memória antes da compactação, fazendo com que a resposta continue em um estado degradado (por exemplo, '⚠️ A manutenção da memória falhou temporariamente; continuando sua resposta.'). Desativado por padrão para manter a manutenção de contexto silenciosa e não intrusiva.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Seções de contexto após a compactação`},help:{"v1-1n0ln2u-5f":`Nomes das seções H2/H3 de AGENTS.md a serem reinseridas após a compactação mediante ativação explícita. Deixe sem definir ou defina [] para desativar a reinserção. Defina explicitamente ["Session Startup", "Red Lines"] para ativar o par padrão legado.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Sincronização do índice após a compactação`},help:{"v1-ekpjeq-6l":`Controla o modo de reindexação da memória da sessão após a compactação: "off", "async" ou "await" (padrão: "async"). Use "await" para garantir dados mais atualizados, "async" para reduzir a latência da compactação e "off" apenas quando a sincronização da memória da sessão for realizada por outro mecanismo.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Provedor de compactação`},help:{"v1-kiwk91-86":`ID de um plugin de provedor de compactação registrado usado para gerar resumos. Quando definido e o provedor está registrado, seu método summarize() é chamado em vez do pipeline integrado summarizeInStages. Em caso de falha do provedor, recorre à implementação integrada. Deixe sem definir para usar a geração de resumos integrada padrão.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Controle de qualidade da compactação`},help:{"v1-u9ognp-4k":`Configurações de novas tentativas de auditoria de qualidade para resumos de compactação no modo de proteção. Esse modo habilita o recurso por padrão; defina enabled: false para pular as auditorias e a regeneração dos resumos.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Proteção de qualidade da compactação habilitada`},help:{"v1-1xk2vt3-36":`Habilita auditorias de qualidade dos resumos e novas tentativas de regeneração para a compactação no modo de proteção. Padrão: true no modo de proteção.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Máximo de novas tentativas da proteção de qualidade da compactação`},help:{"v1-n7l46y-3y":`Número máximo de novas tentativas de regeneração após a reprovação de um resumo na auditoria de qualidade do modo de proteção. Use valores baixos para limitar a latência adicional e o custo de tokens.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Preservação de turnos recentes na compactação`},help:{"v1-y34ihi-5k":`Número de turnos mais recentes do usuário/assistente mantidos na íntegra, sem serem resumidos pelo modo de proteção (padrão: 3). Aumente esse valor para preservar o contexto exato do diálogo recente ou diminua-o para maximizar a economia com a compactação.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Nível de raciocínio da compactação`},help:{"v1-1vafgaw-g1":`Nível de raciocínio usado apenas para resumos de compactação integrados do OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" ou "inherit". Por padrão, usa a preferência de compactação do provedor ou, na ausência dela, "low"; o Ollama local nativo prefere "off". Defina "inherit" para reutilizar o nível da sessão. Configurações explícitas substituem os padrões do provedor, e o nível selecionado é limitado ao que o modelo e o ambiente de execução de compactação efetivamente suportam. A compactação nativa do Codex app-server ignora essa configuração porque sua solicitação de compactação não permite substituir o nível de raciocínio por operação, e o OpenClaw registra um aviso.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Tempo limite de compactação (segundos)`},help:{"v1-2bhn29-7m":`Janela de segurança em segundos para cada solicitação ao modelo de compactação integrado (padrão: 180). A compactação em várias etapas renova a janela no início de cada solicitação sequencial, portanto a compactação completa pode levar mais tempo; a compactação gerenciada por um plugin recebe uma única janela para toda a operação.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Injeção de contexto`},help:{"v1-u18x0-7u":`Controla a injeção de arquivos de inicialização do espaço de trabalho no ambiente de execução incorporado: "always" usa a injeção normal (padrão), "continuation-skip" ignora turnos de continuação elegíveis após um turno registrado de inicialização completa e "never" desativa a injeção. Não controla a preparação de prompts baseada em CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Limites padrão de contexto`},help:{"v1-1coeez8-5d":`Limites padrão específicos de orçamento de contexto por agente para trechos selecionados de alto volume e blocos de prompt injetados. Use esta opção para ajustar os limites de tamanho de leitura e injeção sem reabrir caminhos de chamada sem limites.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Máximo padrão de caracteres de memory_get`},help:{"v1-1qb40qv-4v":`Número máximo padrão de caracteres retornados por memory_get antes da adição dos metadados de truncamento e do aviso de continuação. Aumente para se aproximar dos trechos maiores anteriores, mas mantenha um limite.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Máximo padrão de caracteres após a compactação`},help:{"v1-64qo8g-5r":`Número máximo padrão de caracteres de AGENTS.md mantidos na injeção de atualização do contexto após a compactação. Reduza esse valor para diminuir o custo da recuperação após a compactação ou aumente-o para agentes que dependem de orientações de inicialização mais longas.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Diretório de trabalho`},help:{"v1-1y8wlxn-6a":`Diretório de trabalho para execuções de resposta do agente, separado da inicialização do espaço de trabalho e dos arquivos de memória. O cwd específico do agente e o cwd definido na criação da sessão têm precedência. Aceita ~ e caminhos relativos; um cwd distinto exige uma execução fora da sandbox.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Modelo de decisão`},help:{"v1-7nd7ze-64":`Provedor/modelo opcional para escolhas tipadas, pontuações e probabilidades booleanas. Se não for definido ou estiver vazio, desativa as chamadas de decisão. Plugins compatíveis enviam evidências da tarefa em quantidade limitada a esse provedor; os modelos de chat e de utilidades permanecem inalterados.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw integrado`},help:{"v1-1keek32-3k":`Controles de reforço de segurança do executor integrado do OpenClaw que determinam como as configurações locais do agente no espaço de trabalho são consideradas confiáveis e aplicadas nas sessões do OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Contingência por política cibernética`},help:{"v1-xvv6wl-2r":`Escalonamento automático para o Daybreak em caso de recusas por política cibernética da OpenAI que permitem reexecução segura no ambiente de execução integrado.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Intervalo de espera da contingência por política cibernética`},help:{"v1-16smtrl-25":`Por quanto tempo um destino de escalonamento indisponível é ignorado na sessão atual.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Modo de contingência por política cibernética`},help:{"v1-rzsd2b-2h":`Ative o escalonamento automático ("auto", padrão) ou mantenha as recusas do provedor como definitivas ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Modelo de contingência por política cibernética`},help:{"v1-1aaj8nn-1t":`Provedor/modelo de destino usado para escalonamento automático por política cibernética.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Contrato de execução do OpenClaw integrado`},help:{"v1-1fch2ig-66":`Contrato de execução do OpenClaw integrado: "default" mantém o comportamento padrão do executor, enquanto "strict-agentic" habilita o acompanhamento estruturado de planos e a recuperação não visível de turnos para execuções compatíveis da família GPT-5 do OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Política de configurações de projeto do OpenClaw integrado`},help:{"v1-fdyy04-65":'Como o OpenClaw incorporado lida com o arquivo `.openclaw/settings.json` local do espaço de trabalho: "sanitize" (padrão) remove shellPath/shellCommandPrefix, "ignore" desativa totalmente as configurações do projeto e "trusted" aplica as configurações do projeto sem alterações.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Opções experimentais do agente`},help:{"v1-cvv5cl-2w":`Opções experimentais padrão dos agentes. Mantenha-as desativadas, a menos que esteja testando intencionalmente um recurso em versão prévia.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Ativar modo enxuto de modelo local (experimental)`},help:{"v1-gj06u6-7b":`Configuração avançada para solução de problemas que restringe ferramentas opcionais como browser, automations e message. Desativada por padrão; os ambientes de execução locais compatíveis usam a busca automática de ferramentas sem essa restrição. As permissões explícitas de ferramentas e as ferramentas de entrega obrigatórias são preservadas.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Modo rápido padrão do agente`},help:{"v1-zv4y98-2z":`Política padrão de modo rápido para o ciclo do agente ("auto", true ou false). As entradas individuais de agentes substituem essa política.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Agente de heartbeat`},help:{"v1-1jynxej-3w":`Agente responsável pelas execuções de heartbeat em segundo plano quando não há configuração de heartbeat por agente. Deixe sem definir para preservar o roteamento padrão configurado.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Política de entrega direta de heartbeat`},help:{"v1-nhyxa9-41":`Controla se a entrega de heartbeat pode ser direcionada a conversas diretas/privadas: "allow" (padrão) permite a entrega de mensagens privadas e "block" impede envios a destinos diretos.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Tempo limite do heartbeat (segundos)`},help:{"v1-1se21py-5f":`Tempo máximo em segundos permitido para um turno de heartbeat do agente antes de ser interrompido. Deixe sem definir para usar agents.defaults.timeoutSeconds, se estiver definido; caso contrário, será usado o intervalo do heartbeat, limitado a 600 segundos.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Atraso humano máximo (ms)`},help:{"v1-vnmvli-1m":`Atraso máximo em ms para humanDelay personalizado (padrão: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Atraso humano mínimo (ms)`},help:{"v1-5nrtr5-1l":`Atraso mínimo em ms para humanDelay personalizado (padrão: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Modo de atraso humano`},help:{"v1-k7hyg3-1n":`Estilo de atraso para respostas em blocos ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Dimensão máxima da imagem (px)`},help:{"v1-vju8x-2u":`Comprimento máximo do lado da imagem em pixels ao sanitizar dados de imagem em transcrições ou resultados de ferramentas (padrão: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Modelos de imagem alternativos`},help:{"v1-1kgx5i9-1b":`Modelos de imagem alternativos em ordem de prioridade (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Modelo de imagem`},help:{"v1-dstqyh-2c":`Modelo de imagem opcional (provider/model) usado quando o modelo principal não aceita imagens como entrada.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Qualidade da imagem`},help:{"v1-1uyxc5s-6u":`Preferência de compressão de mídia da ferramenta de imagens: "auto" se adapta aos limites do provedor/modelo e à quantidade de imagens, "efficient" economiza tokens e bytes, "balanced" mantém o equilíbrio atual e "high" preserva mais detalhes em capturas de tela e imagens de documentos.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Modelos alternativos para geração de imagens`},help:{"v1-oljfk4-1m":`Modelos alternativos para geração de imagens, em ordem de prioridade (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modelo de geração de imagens`},help:{"v1-g4yw0h-2o":`Modelo opcional de geração de imagens (provider/model) usado pelo recurso compartilhado de geração de imagens.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Tempo limite de geração de imagens (ms)`},help:{"v1-9yesfj-31":`Tempo limite padrão das solicitações ao provedor, em milissegundos, para chamadas de image_generate. O valor de timeoutMs definido por chamada substitui este valor.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Modelos alternativos para geração de música`},help:{"v1-wyg9xe-1m":`Modelos alternativos para geração de música, em ordem de prioridade (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modelo de geração de música`},help:{"v1-xs1e2h-2o":`Modelo opcional de geração de música (provider/model) usado pelo recurso compartilhado de geração de música.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Modelos alternativos para geração de vídeos`},help:{"v1-wpbf1e-1m":`Modelos alternativos de geração de vídeo em ordem de prioridade (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modelo de geração de vídeo`},help:{"v1-hfmlbl-2o":`Modelo opcional de geração de vídeo (provider/model) usado pelo recurso compartilhado de geração de vídeo.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Tempo limite de geração de vídeo (ms)`},help:{"v1-1bqj80s-4i":`Tempo limite padrão das solicitações ao provedor, em milissegundos, para chamadas de video_generate. O timeoutMs de cada chamada tem precedência sobre este valor, que, por sua vez, tem precedência sobre os padrões definidos pelo provedor.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Modelos alternativos`},help:{"v1-t4djq2-24":`Modelos alternativos em ordem de prioridade (provider/model). Usados quando o modelo principal falha.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Modelo Principal`},help:{"v1-1i8a1v4-v":`Modelo principal (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Política de modelos`},help:{"v1-z0txb7-2e":`Política explícita para substituições de modelo. Omita-a ou deixe allow vazio para permitir qualquer modelo.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Modelos permitidos`},help:{"v1-1fqace-3x":`Referências de modelo permitidas para substituição. Aceita aliases, referências completas "provider/model" e curingas de provedor, como "openai/*". Vazio permite qualquer modelo.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modelos`},help:{"v1-13cvq23-4i":`Catálogo de modelos configurados e configurações por modelo. As entradas fornecem aliases, parâmetros, metadados de execução e substituições do Code Mode; elas não restringem as substituições de modelo.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Ambiente de execução do modelo do agente padrão`},help:{"v1-6km9kx-41":`Política opcional de ambiente de execução por modelo para o agente padrão. Use esta opção para exceções de execução específicas de cada modelo, em vez de definir um ambiente de execução para todo o agente.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID do ambiente de execução do modelo do agente padrão`},help:{"v1-1co96w7-4a":`ID do ambiente de execução do modelo do agente padrão: "openclaw", "auto", um ID de harness de plugin registrado, como "codex", ou um alias de backend de CLI compatível, como "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Modo de código`},help:{"v1-rsdl5o-6x":`Modo de código do OpenClaw para este provedor/modelo específico: Ativado força sua ativação, Desativado o desabilita e Padrão herda tools.codeMode.enabled. As configurações de ativação específicas do agente têm precedência. Isso não altera o ambiente de execução selecionado nem o modo de código nativo do Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Escopo da seleção de modelo`},help:{"v1-sj8owq-bl":`Escopo para comandos de chat e atualizações do modelo de sessão do Gateway sem um escopo explícito: "session" (padrão) altera apenas a sessão atual, "agent" também atualiza o modelo principal desse agente e "global" também atualiza o modelo alternativo compartilhado em agents.defaults.model. Sinalizadores de escopo explícitos têm precedência; alterações nos padrões configurados exigem permissão de proprietário ou administrador. Os seletores de callback do Telegram e a TUI local integrada continuam restritos à sessão.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Tamanho máximo do PDF (MB)`},help:{"v1-1uig1dr-1u":`Tamanho máximo do arquivo PDF em megabytes para a ferramenta de PDF (padrão: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Máximo de páginas do PDF`},help:{"v1-11na7hp-1y":`Número máximo de páginas de PDF a processar pela ferramenta de PDF (padrão: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Modelos alternativos para PDF`},help:{"v1-89ebd8-19":`Modelos alternativos para PDF em ordem de prioridade (provedor/modelo).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Modelo para PDF`},help:{"v1-2ktkxt-2y":`Modelo opcional para PDF (provedor/modelo) usado pela ferramenta de análise de PDF. Por padrão, usa imageModel e, na ausência dele, o modelo da sessão.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Raiz do repositório`},help:{"v1-j3sh74-2h":`Raiz opcional do repositório exibida na linha de informações de execução do prompt do sistema (substitui a detecção automática).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Intervalo de portas de origem CDP do navegador no sandbox`},help:{"v1-1jkowdc-2b":`Lista opcional de permissões CIDR para tráfego CDP de entrada na borda do contêiner (por exemplo, 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Rede do navegador no sandbox`},help:{"v1-8m74ud-5w":`Rede Docker para contêineres do navegador no sandbox (padrão: openclaw-sandbox-browser). Use a rede padrão dedicada ou uma rede bridge personalizada; "none" não é compatível porque o controle do navegador exige portas CDP publicadas.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Permitir ingresso em namespace de contêiner no Docker do sandbox`},help:{"v1-qm39de-4c":`Exceção de emergência PERIGOSA que permite o modo de rede Docker container:<id> no sandbox. Isso ingressa no namespace de outro contêiner e enfraquece o isolamento do sandbox.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPUs do Docker no sandbox`},help:{"v1-jj0yhw-4k":`Valor opcional de repasse de GPU do Docker passado para --gpus, por exemplo "all" ou "device=GPU-uuid". Requer um ambiente de execução compatível no host, como NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Destino do armazenamento de sessões legado`},help:{"v1-1xkej6i-2g":`Proprietário usado para compatibilidade na atualização de registros descontinuados de main-agent e armazenamentos de sessões legados fixos.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Proprietário do armazenamento de sessões legado`},help:{"v1-ommm7e-5w":`Agente proprietário dos registros descontinuados de main-agent ou dos registros sem escopo em um armazenamento de sessões legado fixo após a descontinuação do marcador padrão. Gravado automaticamente durante a atualização quando o proprietário anterior não era main nem o único agente.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Lista padrão opcional de habilidades permitidas, herdada pelos agentes que omitem agents.entries.*.skills. Omita para permitir habilidades sem restrições, defina [] para que os agentes que herdam essa configuração não tenham habilidades e lembre-se de que uma configuração explícita de agents.entries.*.skills substitui esse padrão, em vez de ser mesclada com ele.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Ignorar a criação de arquivos de inicialização do espaço de trabalho`},help:{"v1-kbstgw-5v":`Ignora a criação automática de arquivos de inicialização do espaço de trabalho, não a injeção de arquivos existentes. Para o ambiente de execução incorporado, defina agents.defaults.contextInjection como "never" para desativar a injeção, a menos que essa configuração seja substituída por agente.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Arquivos opcionais de inicialização ignorados`},help:{"v1-1j2z4yj-4c":`Arquivos opcionais de inicialização que não devem ser criados nos espaços de trabalho dos agentes. Valores válidos: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md é aceito, mas não tem efeito).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Contexto de inicialização`},help:{"v1-1ugsihy-5o":`Preâmbulo da primeira interação gerenciado pelo ambiente de execução para "/new" e "/reset" sem argumentos. Use esta opção para controlar se os arquivos recentes de memória diária são pré-carregados no primeiro prompt, em vez de pedir ao modelo que decida o que ler.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Aplicar contexto de inicialização em`},help:{"v1-wav4a5-36":`Escolhe quais comandos de reinicialização sem argumentos recebem o contexto de inicialização: inclua "new", "reset" ou ambos (padrão: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Dias de memória diária no contexto de inicialização`},help:{"v1-4i5xcm-3p":`Número de arquivos de memória datados a carregar, contando retroativamente a partir de hoje no fuso horário configurado para o usuário (padrão: 2, para hoje + ontem).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Ativar contexto de inicialização`},help:{"v1-1d5vz2u-4i":`Ativa o preâmbulo de contexto de inicialização para reinicializações de sessão sem argumentos (padrão: true). Desative esta opção para voltar ao comportamento baseado apenas no prompt, sem memória diária carregada pelo ambiente de execução.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Máximo de bytes por arquivo no contexto de inicialização`},help:{"v1-11cbian-41":`Máximo de bytes permitido por arquivo de memória diária ao montar o contexto de inicialização (padrão: 16384). Arquivos que excedem esse limite de leitura segura são ignorados.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Máximo de caracteres por arquivo no contexto de inicialização`},help:{"v1-10z53s-2u":`Máximo de caracteres mantidos de cada arquivo de memória diária carregado no preâmbulo de inicialização (padrão: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Máximo total de caracteres do contexto de inicialização`},help:{"v1-sf676u-54":`Número máximo de caracteres mantidos no conjunto de arquivos de memória diária carregados no preâmbulo de inicialização (padrão: 2800). Os arquivos adicionais são truncados no preâmbulo quando esse limite é atingido.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Modo de delegação a subagentes`},help:{"v1-pqewbk-5o":`Intensidade da delegação a subagentes controlada apenas por prompt. O padrão é "prefer" na sessão principal de cada agente e "suggest" nas demais; "prefer" instrui enfaticamente o agente a delegar tarefas não triviais via sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Destino do agente do sistema`},help:{"v1-1wwimo9-34":`Configurações de destino para inferência em segundo plano do agente do sistema OpenClaw e do Custodian, além de determinadas leituras do operador sem escopo definido.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Proprietário do agente do sistema`},help:{"v1-15rvt92-8c":`Agente cujo modelo e credenciais são usados nas consultas em segundo plano do agente do sistema e do Custodian. Também é usado quando models.list, models.authStatus, skills.status, doctor.memory.status ou um comando infer da CLI que resolve o modelo ou o estado de autenticação pertencente ao agente omite agentId ou --agent; o agentId explícito na solicitação sempre tem prioridade.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Intervalo de digitação (segundos)`},help:{"v1-1y701ox-42":`Controla o intervalo, em segundos, das atualizações que mantêm ativo o indicador de digitação para todos os agentes. Aumente esse valor para reduzir a frequência de atualização em todos os canais compatíveis com indicadores de digitação.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Modo de digitação`},help:{"v1-m2hvpw-3m":`Controla quando o indicador de digitação dos agentes é ativado: "never", "instant", "thinking" ou "message". O typingMode de cada agente substitui esse padrão.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Modelo utilitário`},help:{"v1-1wg7h1a-7s":`Modelo opcional de menor custo (provider/model ou alias) para tarefas internas curtas, como geração de títulos e narração do progresso. Quando não definido, usa o modelo pequeno declarado pelo provedor principal, se disponível (caso contrário, o modelo principal); defina como uma string vazia para desativar o roteamento para o modelo utilitário.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Modelos de voz alternativos`},help:{"v1-faazv4-1b":`Modelos de voz alternativos em ordem de prioridade (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Modelo de voz`},help:{"v1-1yeh3h4-2t":`Modelo de voz opcional (provider/model) usado pelos recursos de fala, transcrição e voz em tempo real.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Tempo limite de voz (ms)`},help:{"v1-1sbergs-32":`Tempo limite padrão das solicitações ao provedor, em milissegundos, para operações do modelo de voz quando o componente que faz a chamada oferece suporte a tempos limite.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Espaço de Trabalho`},help:{"v1-1lssx8l-5w":`Espaço de trabalho padrão do agente para arquivos de inicialização e memória. Também é usado como diretório de trabalho quando agents.defaults.cwd não está definido. Defina isso explicitamente ao executar por meio de wrappers para que a resolução de caminhos permaneça determinística.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Lista de agentes`},help:{"v1-yurood-5l":`Lista explícita de agentes configurados com IDs e substituições opcionais para modelo, ferramentas, identidade e espaço de trabalho. Mantenha os IDs estáveis ao longo do tempo para que os vínculos, as aprovações e o roteamento de sessões permaneçam determinísticos.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Ambiente de execução legado do agente`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID do ambiente de execução legado do agente`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Máximo de caracteres de inicialização do agente`},help:{"v1-rsf1es-4j":`Substituição por agente do máximo de caracteres de cada arquivo de inicialização do espaço de trabalho injetado no prompt de sistema deste agente. Omita para herdar agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Máximo total de caracteres de inicialização do agente`},help:{"v1-1bal68p-4y":`Substituição por agente do máximo total de caracteres de todos os arquivos de inicialização do espaço de trabalho injetados no prompt de sistema deste agente. Omita para herdar agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Injeção de contexto do agente`},help:{"v1-1j68ys8-50":`Configuração específica por agente para a injeção de arquivos de inicialização do espaço de trabalho no ambiente de execução integrado. Omita para herdar agents.defaults.contextInjection. Não controla a preparação de prompts baseada em CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Limites de contexto do agente`},help:{"v1-f1qxq8-3c":`Substituições opcionais por agente dos parâmetros de orçamento de contexto focado. Os campos omitidos herdam agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Máximo de caracteres de memory_get do agente`},help:{"v1-12hlmsv-1v":`Substituição por agente do limite máximo padrão de caracteres de memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Máximo de caracteres do agente após a compactação`},help:{"v1-15s0npd-1w":`Substituição por agente do limite de caracteres para trechos de AGENTS.md após a compactação.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Diretório de trabalho do agente`},help:{"v1-mv43ak-6a":`Diretório de trabalho para as execuções de resposta deste agente. Substitui agents.defaults.cwd, mas não o cwd definido ao iniciar a sessão; os arquivos de inicialização e memória permanecem no espaço de trabalho. Aceita ~ e caminhos relativos; um cwd diferente exige uma execução fora do sandbox.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Modelo de decisão do agente`},help:{"v1-1mih8bf-3j":`Modelo de decisão por agente. Se não for definido, herda agents.defaults.decisionModel; uma string vazia desativa as chamadas de decisão para este agente.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw integrado do agente`},help:{"v1-uoomza-4b":`Substituições opcionais por agente para o OpenClaw integrado. Use esta opção para habilitar um comportamento de execução mais rigoroso do GPT-5 para agentes específicos sem alterar o padrão global.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Contrato de execução do OpenClaw integrado do agente`},help:{"v1-1d1jaoi-7k":`Substituição opcional por agente do contrato de execução do OpenClaw integrado. Defina "strict-agentic" para habilitar o acompanhamento estruturado de planos e a recuperação não visível de turnos para esse agente em execuções compatíveis da família GPT-5 da OpenAI/OpenAI Codex, ou "default" para herdar o comportamento padrão do executor.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Opções experimentais do agente`},help:{"v1-1r06jov-2a":`Opções experimentais por agente. Os campos omitidos herdam agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Modo enxuto de modelo local do agente`},help:{"v1-5o3tgx-58":`Configuração de solução de problemas por agente para o modo enxuto de modelo local. Ative-a somente quando restringir ferramentas opcionais resolver uma falha comprovada do modelo, sem reduzir as ferramentas de todos os agentes.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Padrão do modo rápido do agente`},help:{"v1-1ujydjc-3o":`Padrão opcional por agente para o modo rápido ("auto", true ou false). Aplica-se quando nenhuma substituição do modo rápido está definida para a mensagem ou sessão.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Política de entrega direta de sinais de atividade`},help:{"v1-11gl9l0-41":`Substituição por agente da política de entrega direta/por mensagem direta de sinais de atividade; use "block" para agentes que devem enviar alertas de atividade apenas a destinos que não sejam mensagens diretas.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Tempo limite do sinal de atividade (segundos)`},help:{"v1-kdetv4-6s":`Tempo máximo por agente, em segundos, permitido para um turno de sinal de atividade do agente antes de ser interrompido. Deixe sem definir para herdar o tempo limite consolidado dos sinais de atividade; na ausência dele, usa agents.defaults.timeoutSeconds, quando definido, ou o intervalo dos sinais de atividade, limitado a 600 segundos.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Avatar da Identidade`},help:{"v1-pzp9gr-1t":`Avatar do agente (caminho relativo ao espaço de trabalho, URL http(s) ou URI de dados).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Política de modelos do agente`},help:{"v1-17d5je8-2r":`Política de substituição de modelo por agente. Uma lista explícita de permissões substitui a política padrão para este agente.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Modelos permitidos para o agente`},help:{"v1-v1ueke-5b":`Referências de modelos permitidas para substituição neste agente. Aceita aliases, referências completas "provider/model" e prefixos com curingas no final, como "provider/*" ou "provider/namespace/*"; se estiver vazia, permite qualquer modelo.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Substituições de modelos do agente`},help:{"v1-nld1vq-1v":`Substituições do catálogo de modelos por agente, indexadas por IDs completos de provedor/modelo.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Ambiente de execução do modelo do agente`},help:{"v1-7b59y-3s":`Política opcional de ambiente de execução por modelo para este agente. Use esta opção para exceções de modelo específicas do agente, em vez de definir um ambiente de execução para todo o agente.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID do ambiente de execução do modelo do agente`},help:{"v1-1ckfc39-46":`ID do ambiente de execução do modelo por agente: "openclaw", "auto", um ID de harness de plugin registrado, como "codex", ou um alias de backend de CLI compatível, como "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Modo de código`},help:{"v1-91zu7f-7m":`Modo de código do OpenClaw para este agente e este provedor/modelo exato: Ativado força a ativação, Desativado desabilita o recurso, e Padrão herda a configuração de ativação do agente, depois a substituição compartilhada do modelo e, por fim, tools.codeMode.enabled. Isso não altera o ambiente de execução selecionado nem o modo de código nativo do Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Padrão de raciocínio do agente`},help:{"v1-13ly0xf-3m":`Visibilidade padrão opcional do raciocínio por agente (on|off|stream). Aplica-se quando nenhuma substituição de raciocínio por mensagem ou sessão está definida.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Ambiente de execução do agente`},help:{"v1-avjgkf-3l":`Descritor opcional do ambiente de execução para este agente. Use embedded para a execução padrão do OpenClaw ou acp para os padrões de harness ACP externo.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Ambiente de execução ACP do agente`},help:{"v1-91zvdk-3i":`Configurações padrão do ambiente de execução ACP para este agente quando runtime.type=acp. As substituições de ACP no nível do vínculo continuam tendo precedência por conversa.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agente do executor ACP para este agente`},help:{"v1-1pm98vp-37":`ID opcional do agente do executor ACP a ser usado para este agente OpenClaw (por exemplo, codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Backend ACP do agente`},help:{"v1-1u3cdsg-2n":`Substituição opcional do backend ACP para as sessões ACP deste agente (usa o valor global de acp.backend como alternativa).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Diretório de trabalho ACP do agente`},help:{"v1-d9p9rf-1t":`Diretório de trabalho padrão opcional para as sessões ACP deste agente.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Modo ACP do agente`},help:{"v1-yatuk4-21":`Modo padrão opcional de sessão ACP para este agente (persistent ou oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Tipo de ambiente de execução do agente`},help:{"v1-139fbk6-2r":`Tipo de ambiente de execução para este agente: "embedded" (ambiente de execução padrão do OpenClaw) ou "acp" (configurações padrão do executor ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Intervalo de origem CDP do navegador no ambiente isolado do agente`},help:{"v1-1q1qyso-1d":`Substituição por agente da lista de permissões de CIDR de origem do CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Rede do navegador no ambiente isolado do agente`},help:{"v1-13bdfww-4c":`Substituição por agente da rede Docker do navegador em sandbox. Use uma rede bridge; "none" não é compatível porque o controle do navegador requer portas CDP publicadas.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Permitir ingresso no namespace de contêiner no Docker da sandbox do agente`},help:{"v1-1xtnseb-2i":`Substituição PERIGOSA por agente para ingresso em namespaces de contêiner no modo de rede Docker da sandbox.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPUs do Docker da sandbox do agente`},help:{"v1-1kek1n2-1t":`Substituição por agente do acesso direto às GPUs no Docker para contêineres da sandbox.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filtro de Skills do agente`},help:{"v1-igchue-6v":`Lista opcional de Skills permitidas para este agente. Se omitida, o agente herda agents.defaults.skills quando definido; caso contrário, as Skills permanecem sem restrições. Defina [] para não permitir nenhuma Skill. Uma lista explícita substitui integralmente os padrões herdados, em vez de ser combinada com eles.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Limites de Skills do agente`},help:{"v1-1sv10v9-4y":`Substituições opcionais por agente para os limites do subsistema de Skills. Use esta opção quando um agente precisar de um limite diferente para o prompt de Skills sem introduzir um segundo caminho genérico de limites de contexto.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Máximo de caracteres do prompt de Skills do agente`},help:{"v1-dys63y-52":`Substituição por agente do limite de caracteres do prompt de Skills. Isso estende o caminho existente skills.limits.maxSkillsPromptChars, em vez de encaminhar o mesmo limite por contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Modo de delegação de subagentes`},help:{"v1-1rkgh6p-4s":`Substituição por agente da intensidade de delegação a subagentes. Omita para usar "prefer" na sessão principal deste agente e "suggest" nas demais; um valor explícito de "prefer" ou "suggest" sempre prevalece.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Nível de raciocínio padrão do agente`},help:{"v1-173q7vy-43":`Nível de raciocínio padrão opcional por agente. Substitui agents.defaults.thinkingDefault para este agente quando nenhuma substituição por mensagem ou sessão estiver definida.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Adições à lista de ferramentas permitidas do agente`},help:{"v1-1550ui9-46":`Lista adicional de ferramentas permitidas por agente, além das políticas globais e de perfil. Mantenha-a restrita para evitar a ampliação acidental de privilégios em agentes especializados.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Política de ferramentas do agente por provedor`},help:{"v1-mthxv9-4t":`Substituições por agente da política de ferramentas específica de cada provedor para controle de capacidades no escopo do canal. Use quando um único agente precisar de restrições mais rigorosas em um provedor do que nos demais.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Modo de código do agente`},help:{"v1-118t8u5-65":`Opções do modo de código por agente. Um valor explícito de enabled substitui os padrões de ativação globais e do modelo compartilhado; uma substituição de codeMode do modelo específica do agente tem precedência. As demais opções são mescladas com tools.codeMode, substituindo os valores correspondentes sem alterar a ativação.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Tempo limite de execução do agente (segundos)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Substituição da identidade do GitHub CLI do agente`},help:{"v1-mjwdh4-38":`Substituição completa da identidade gerenciada do GitHub CLI e do autor Git para este agente. Omita para herdar a identidade do sistema.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`E-mail do autor Git do agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nome do autor Git do agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Tipo de credencial do GitHub do agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Versão do perfil do GitHub do agente`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Lista de ações de mensagem permitidas do agente`},help:{"v1-1g5gov3-67":`Lista de ações de mensagem permitidas por agente para a ferramenta de mensagens. Defina uma lista mínima, como ["send"], para agentes em ambientes isolados públicos, de modo que ações de leitura, edição, exclusão, reação e outras ações de mensagem específicas do provedor permaneçam ocultas e bloqueadas.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Mensagens entre contextos do agente (entre provedores)`},help:{"v1-pehesn-49":`Substituição por agente da configuração de envio entre provedores. Herda a configuração global (padrão: true). Defina como false para bloquear mensagens entre provedores para este agente.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Mensagens do agente entre contextos (mesmo provedor)`},help:{"v1-s9u09h-4t":`Controle por agente do envio de mensagens para outras conversas no mesmo provedor. Defina esta configuração e allowAcrossProviders como false para agentes públicos restritos à conversa atual.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Perfil de ferramentas do agente`},help:{"v1-1du76ix-57":`Substituição por agente da seleção do perfil de ferramentas quando um agente precisa de um conjunto básico de recursos diferente. Use com moderação para que as diferenças de política entre agentes permaneçam intencionais e passíveis de revisão.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Enxame do agente`},help:{"v1-420ljs-2c":`Substituição da configuração de enxame por agente. Os valores são mesclados com a configuração tools.swarm de nível superior, tendo precedência sobre ela.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Modo de digitação do agente`},help:{"v1-oxir52-2e":`Substitui a política padrão de início de digitação para um agente sem alterar os demais.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Modelo utilitário do agente`},help:{"v1-1v9oskz-2z":`Substituição opcional do modelo utilitário por agente para tarefas internas curtas. Substitui agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Geração de titularidade dos agentes`},help:{"v1-m2hp61-8g":`Marcador persistente de geração de titularidade em ambientes com vários agentes. "explicit" significa que canais de ambiente, sinais periódicos de atividade, consultas ao agente do sistema, Talk, cron e operações diretas da CLI devem identificar um responsável específico para cada interface ou bloquear a operação por segurança. O OpenClaw registra esse marcador automaticamente ao criar ou migrar uma frota; omita-o para um único agente.`}},approvals:{label:{"v1-1m405m7-9":`Aprovações`},help:{"v1-4y3in-5w":`Controles de roteamento de aprovações para encaminhar solicitações de aprovação de exec e plugins a destinos de chat fora da sessão de origem. Mantenha-os desativados, a menos que os operadores precisem de visibilidade explícita das aprovações fora da sessão.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Encaminhamento de aprovações de exec`},help:{"v1-1r2mozk-5v":`Agrupa o comportamento de encaminhamento de aprovações de exec, incluindo ativação, modo de roteamento, filtros e destinos explícitos. Configure aqui quando as solicitações de aprovação precisarem chegar aos canais operacionais, em vez de apenas à conversa de origem.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filtro de agentes para aprovações`},help:{"v1-xbuhd3-5i":'Lista opcional de IDs de agentes permitidos cujas aprovações podem ser encaminhadas, por exemplo, `["primary", "ops-agent"]`. Use-a para limitar o alcance do encaminhamento e evitar notificações nos canais sobre agentes não relacionados.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Encaminhar aprovações de exec`},help:{"v1-1t0whe8-5s":`Ativa o encaminhamento de solicitações de aprovação de exec aos destinos de entrega configurados (padrão: false). Mantenha desativado em configurações de baixo risco e ative somente quando as pessoas responsáveis pelas aprovações precisarem de solicitações visíveis nos canais.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Modo de encaminhamento de aprovações`},help:{"v1-1dedfo4-69":`Controla para onde as solicitações de aprovação são enviadas: "session" usa o chat de origem, "targets" usa os destinos configurados e "both" envia pelos dois caminhos. Use "session" como padrão e amplie somente quando o fluxo de trabalho operacional exigir redundância.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filtro de sessões para aprovações`},help:{"v1-smeg8e-5u":'Filtros opcionais de chave de sessão que correspondem a substrings ou padrões de expressão regular, por exemplo `["discord:", "^agent:ops:"]`. Use padrões restritos para que apenas os contextos de aprovação pretendidos sejam encaminhados para destinos compartilhados.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Destinos de encaminhamento de aprovações`},help:{"v1-17ah848-5u":`Destinos de entrega explícitos usados quando o modo de encaminhamento inclui destinos, cada um com detalhes de canal e destino. Mantenha as listas de destinos de acordo com o princípio do menor privilégio e valide cada destino antes de habilitar o encaminhamento amplo.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID da conta de destino das aprovações`},help:{"v1-16zopng-5e":`Seletor de conta opcional para configurações de canal com várias contas, quando as aprovações precisam ser roteadas por um contexto de conta específico. Use apenas quando o canal de destino tiver várias identidades configuradas.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Canal de destino das aprovações`},help:{"v1-ji1igl-59":`ID do canal/provedor usado para entregar aprovações encaminhadas, como discord, slack ou um ID de canal de plugin. Use apenas IDs de canal válidos para que as aprovações não falhem silenciosamente devido a rotas desconhecidas.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID da conversa de destino das aprovações`},help:{"v1-1axynw7-59":`Conversa/tópico de destino opcional para canais que permitem entregar aprovações encaminhadas em conversas. Use para manter o tráfego de aprovações restrito a conversas operacionais, em vez de canais principais.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destino de entrega das aprovações`},help:{"v1-1ijng7e-5n":`Identificador de destino no canal de destino (ID do canal, ID do usuário ou raiz da conversa, dependendo do provedor). Verifique a semântica de cada provedor, pois o formato do destino varia entre as integrações de canais.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Encaminhamento de aprovações de plugins`},help:{"v1-1m6pzxv-6b":`Agrupa o comportamento de encaminhamento de aprovações de plugins, incluindo ativação, modo de roteamento, filtros e destinos explícitos. Independente do encaminhamento de aprovações de execução. Configure aqui quando as solicitações de aprovação de plugins precisarem chegar aos canais operacionais.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filtro de agentes para aprovações de plugins`},help:{"v1-jb1bra-4b":'Lista opcional de IDs de agentes autorizados a ter suas aprovações de plugins encaminhadas, por exemplo, `["primary", "ops-agent"]`. Use-a para limitar o alcance do encaminhamento.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Encaminhar aprovações de plugins`},help:{"v1-1ntctaf-3v":`Ativa o encaminhamento de solicitações de aprovação de plugins para os destinos de entrega configurados (padrão: false). Independente de approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Modo de encaminhamento de aprovações de plugins`},help:{"v1-1h62vy4-3z":`Controla para onde as solicitações de aprovação de plugins são enviadas: "session" usa o chat de origem, "targets" usa os destinos configurados e "both" envia para ambos.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filtro de sessões para aprovações de plugins`},help:{"v1-1eppxmt-57":'Filtros opcionais de chaves de sessão que correspondem a substrings ou padrões de expressão regular, por exemplo, `["discord:", "^agent:ops:"]`. Use padrões restritos para que apenas os contextos de aprovação pretendidos sejam encaminhados.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Destinos de encaminhamento de aprovações de plugins`},help:{"v1-o92qze-3k":`Destinos de entrega explícitos usados quando o modo de encaminhamento de aprovações de plugins inclui destinos, cada um com detalhes de canal e destino.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID da conta de destino para aprovações de plugins`},help:{"v1-1wf3lqn-3j":`Seletor de conta opcional para configurações de canais com várias contas, quando as aprovações de plugins precisam ser encaminhadas pelo contexto de uma conta específica.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Canal de destino para aprovações de plugins`},help:{"v1-1mzhzi9-34":`ID do canal/provedor usado para entregar aprovações de plugins encaminhadas, como discord, slack ou um ID de canal de plugin.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID da conversa de destino para aprovações de plugins`},help:{"v1-1scaw9c-2v":`Conversa/tópico de destino opcional para canais que permitem a entrega de aprovações de plugins encaminhadas em conversas.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Destino para aprovações de plugins`},help:{"v1-sh5te1-31":`Identificador de destino no canal de destino (ID do canal, ID do usuário ou mensagem inicial da conversa, dependendo do provedor).`}},attachments:{label:{"v1-8925gh-b":`Anexos`},help:{"v1-1xvgkss-40":`Comportamento de retenção de nível superior compartilhado entre provedores e ferramentas que armazenam mídia de forma persistente. Use ttlHours quando a mídia temporária em geral precisar de limpeza com prazo definido.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL de retenção de anexos (horas)`},help:{"v1-1g90day-9e":`Janela opcional de retenção em horas para mídias persistidas tratadas pela varredura geral baseada em mtime. Deixe sem definir para desativar essa varredura ou defina valores como 24 (1 dia) ou 168 (7 dias) para remover periodicamente mídias preparadas mais antigas. As mídias de saída gerenciadas (anexos gerados pelo chat) são excluídas e seguem sua própria política de retenção, que considera o SQLite e as transcrições.`}},audio:{label:{"v1-11wczsp-5":`Áudio`}},auth:{label:{"v1-5xz433-4":`Autenticação`},help:{"v1-1eu3aud-5c":`Raiz dos perfis de autenticação usada para credenciais de provedores com múltiplos perfis e ordenação de failover baseada em tempo de espera. Mantenha os perfis mínimos e explícitos para que o comportamento de failover automático permaneça auditável.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Ordem dos perfis de autenticação`},help:{"v1-1x6kknp-1w":`IDs ordenados dos perfis de autenticação por provedor (usados para failover automático).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Perfis de autenticação`},help:{"v1-kzoqcn-1j":`Perfis de autenticação nomeados (provedor + modo + e-mail opcional).`}},bindings:{label:{"v1-1hcih9f-8":`Associações`},help:{"v1-y7hrzb-4i":`Regras de vinculação de nível superior para roteamento e atribuição persistente de conversas ACP. Use type=route para roteamento normal e type=acp para vinculações persistentes ao ambiente de execução ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Substituições da vinculação ACP`},help:{"v1-1t4lisi-44":`Substituições opcionais de ACP por vinculação para bindings[].type=acp. Esta camada substitui os padrões de agents.entries.*.runtime.acp para a conversa correspondente.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend da vinculação ACP`},help:{"v1-rsrbkp-2x":`Substituição do backend ACP para esta vinculação (usa como alternativa o backend ACP do ambiente de execução do agente e, em seguida, o acp.backend global).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Diretório de trabalho da vinculação ACP`},help:{"v1-ngpkj0-1y":`Substituição do diretório de trabalho para sessões ACP criadas a partir desta vinculação.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Rótulo da vinculação ACP`},help:{"v1-azce82-23":`Rótulo de fácil identificação para status e diagnósticos ACP nesta conversa vinculada.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Modo da vinculação ACP`},help:{"v1-cgq8xv-1v":`Substituição do modo de sessão ACP para esta vinculação (persistent ou oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID do agente da vinculação`},help:{"v1-17ra0cl-4m":`ID do agente de destino que recebe tráfego quando a regra de correspondência da vinculação é atendida. Use apenas IDs de agentes válidos e configurados para evitar falhas de roteamento em tempo de execução.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Regra de correspondência da vinculação`},help:{"v1-sc1w2e-51":`Objeto de regra de correspondência que determina quando uma vinculação se aplica, incluindo o canal e restrições opcionais de conta ou interlocutor. Mantenha as regras restritas para evitar que um agente assuma acidentalmente o controle em outros contextos.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID da conta da vinculação`},help:{"v1-1d209g7-56":`Seletor de conta opcional para configurações de canal com várias contas, de modo que a vinculação se aplique apenas a uma identidade. Use quando for necessário restringir a rota a uma conta; caso contrário, deixe sem definir.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Canal da vinculação`},help:{"v1-d22m5-54":"Identificador do canal ou provedor ao qual esta vinculação se aplica, como `telegram`, `discord` ou o ID de um canal de plugin. Use exatamente a chave do canal configurada para garantir que a avaliação da vinculação funcione de forma confiável."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID do servidor da vinculação`},help:{"v1-jzzfj1-4x":`Restrição opcional de ID de guilda/servidor no estilo Discord para avaliação de vínculos em implantações com vários servidores. Use quando os mesmos identificadores de interlocutor puderem aparecer em diferentes guildas.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Correspondência de interlocutor do vínculo`},help:{"v1-gcjxff-4i":`Critério opcional de correspondência de interlocutor para conversas específicas, incluindo o tipo e o ID do interlocutor. Use quando apenas um destino de conversa direta, grupo ou canal deve ser vinculado a um agente.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID do interlocutor do vínculo`},help:{"v1-86fbh7-4b":`Identificador da conversa usado na correspondência de interlocutores, como um ID de chat, canal ou grupo do provedor. Mantenha esse valor exato para evitar falhas silenciosas de correspondência.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Tipo de interlocutor do vínculo`},help:{"v1-uufscp-4x":`Tipo de conversa do interlocutor: "direct", "group", "channel" ou o valor legado "dm" (alias obsoleto de direct). Prefira "direct" em novas configurações e mantenha kind alinhado à semântica do canal.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Funções do vínculo`},help:{"v1-6s891m-4k":`Lista opcional de filtros baseados em funções, usada por provedores que associam funções ao contexto do chat. Use para encaminhar o tráfego de funções privilegiadas ou operacionais a agentes especializados.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID da equipe do vínculo`},help:{"v1-hh9ps2-48":`Restrição opcional de ID de equipe/espaço de trabalho, usada por provedores que organizam chats por equipe. Adicione quando precisar isolar os vínculos ao contexto de um único espaço de trabalho.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sessão do vínculo`},help:{"v1-x325l2-4v":`Substituições opcionais de configuração de sessão da rota para conversas correspondentes a este vínculo. Use quando uma rota específica precisar manter o mesmo agente, mas isolar a continuidade da sessão de outra forma.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Escopo de sessão de mensagens diretas do vínculo`},help:{"v1-10sg3xw-4s":`Substituição opcional do escopo de sessão de mensagens diretas para este vínculo de rota. Por exemplo, mantenha session.dmScope="main" globalmente e use "per-account-channel-peer" para interlocutores diretos selecionados.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Escopo de sessão de grupo do vínculo`},help:{"v1-1ys2u7k-6n":`Substituição opcional do escopo de sessão de grupo/canal para este vínculo de rota. "per-group" mantém as salas correspondentes separadas e monitoradas em segundo plano pela sessão principal do agente, independentemente de dmScope; "main" incorpora o contexto delas à sessão principal e dispensa o monitoramento.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Tipo de vínculo`},help:{"v1-172mhtk-3o":`Tipo de vínculo. Use "route" (ou omita para entradas de rota legadas) para roteamento normal e "acp" para vínculos persistentes de conversas ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Threads de grupos de agentes`},help:{"v1-1tz72sr-6b":`Use threads de grupos de agentes para executar vários agentes configurados em uma mesma conversa recebida, cada um em sua própria sessão. Entradas qualificadas por canal permitem rodadas de acompanhamento limitadas; os arrays legados de pares do WhatsApp mantêm o comportamento de passagem única.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Participantes e opções do grupo de agentes`},help:{"v1-1b63zmt-7d":`Use um ID de par qualificado por canal (por exemplo, "telegram:-100123") para configurar um array de IDs de agentes ou um objeto estrito com agents, mentionGating, maxRounds e maxTurns. As entradas qualificadas têm precedência sobre as chaves legadas de pares do WhatsApp e permitem no máximo 16 agentes.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Participantes do grupo de agentes`},help:{"v1-g5o0ky-43":`IDs dos agentes participantes de agents.entries (máximo: 16). Cada participante usa sua própria sessão para este canal, conta, conversa e thread.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Máximo de rodadas do grupo de agentes`},help:{"v1-i6v4jc-5a":`Máximo de rodadas por mensagem recebida, incluindo a rodada inicial (inteiro: 1–4, padrão: 1). As rodadas seguintes compartilham respostas limitadas dos demais participantes, com identificação de autoria, e param quando todos os participantes optam por passar a vez.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Máximo de turnos do grupo de agentes`},help:{"v1-1kiv8dy-72":`Máximo de turnos dos participantes por mensagem recebida em todas as rodadas (inteiro: 1–32, padrão: agents.length). As vagas são reservadas antes do despacho paralelo; isso limita os turnos dos agentes, não os fragmentos físicos de mensagens nem os envios por ferramentas. Os limites não são retomados após a reinicialização.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Seleção por menção no grupo de agentes`},help:{"v1-uay9zu-5u":`Seleciona apenas os participantes explicitamente @mencionados quando houver alguma correspondência; caso contrário, executa todos os participantes (padrão: true). Nomes isolados ou emojis não selecionam participantes. As listas de permissões dos canais e as regras de admissão continuam se aplicando.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Estratégia do grupo de agentes`},help:{"v1-p4k9hu-4q":`Ordem de execução dos participantes: "parallel" (padrão) executa os agentes simultaneamente, enquanto "sequential" os executa na ordem configurada. Cada rodada é concluída antes do início da próxima.`}},browser:{label:{"v1-13dzmen-7":`Navegador`},help:{"v1-5b74wi-5l":`Controles de execução do navegador para conexão CDP local ou remota, roteamento de perfis e comportamento de capturas de tela e snapshots. Mantenha os padrões, a menos que seu fluxo de automação exija configurações personalizadas de transporte do navegador.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Permitir importação de perfil do sistema`},help:{"v1-1lsvlxw-5w":`Permite que hosts macOS importem cookies de um perfil local do sistema de um navegador da família Chrome para um perfil de navegador gerenciado pelo OpenClaw. Desative esta opção para impedir a importação de cookies de perfis de navegador e a solicitação de consentimento do Keychain do macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Modo de navegador somente para conexão`},help:{"v1-xaw7xm-4s":`Restringe o modo do navegador à conexão com instâncias existentes, sem iniciar processos locais do navegador. Use esta opção quando todas as sessões do navegador forem gerenciadas externamente por um provedor CDP remoto.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP do navegador`},help:{"v1-2n72jb-65":`URL do endpoint CDP/DevTools usada para se conectar a uma instância de navegador gerenciada externamente. Use esta opção para hosts de navegador centralizados, túneis ou conexão com sessões existentes, e mantenha o acesso à URL restrito a caminhos de rede confiáveis.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Perfil padrão do navegador`},help:{"v1-a6xo96-52":`Nome do perfil padrão do navegador selecionado quando os chamadores não escolhem um perfil explicitamente. Use um perfil estável com poucos privilégios como padrão para reduzir o uso acidental de estado entre contextos.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Navegador ativado`},help:{"v1-19qr4oj-56":`Ativa a integração dos recursos de navegador no Gateway para permitir a execução de ferramentas de navegador e fluxos de trabalho baseados em CDP. Desative quando a automação de navegador não for necessária para reduzir a superfície de exposição e o trabalho de inicialização.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Avaliação de scripts no navegador ativada`},help:{"v1-1oa79mq-59":`Ativa auxiliares de avaliação no navegador para avaliar scripts em tempo de execução, quando houver suporte. Mantenha desativado, a menos que seus fluxos de trabalho exijam recursos de avaliação além de capturas de estado e navegação.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Caminho do executável do navegador`},help:{"v1-1plb4ki-6i":`Caminho explícito do executável do navegador quando a descoberta automática não for suficiente no ambiente do host. Use um caminho absoluto estável ou um caminho que comece com ~ para o diretório pessoal do seu sistema operacional, para que o comportamento de inicialização permaneça determinístico entre reinicializações.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Retransmissor da extensão de navegador`},help:{"v1-6ywlwr-4e":`Configurações de compatibilidade da autenticação do retransmissor da extensão do Chrome. Mantenha a janela de compatibilidade legada apenas enquanto extensões pareadas mais antigas ou clientes CDP externos ainda precisarem dela.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Permitir autenticação legada do retransmissor do navegador`},help:{"v1-pj2e90-63":`Aceita temporariamente a autenticação legada do retransmissor via Bearer, Basic e subprotocolo de token. Padrão: true durante uma janela de migração. Defina como false depois que todas as extensões e todos os clientes CDP externos estiverem usando Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Modo sem interface gráfica do navegador`},help:{"v1-1rswq8j-5a":`Força a abertura do navegador no modo sem interface gráfica quando o inicializador local inicia instâncias do navegador. Mantenha esse modo ativado em ambientes de servidor e desative-o apenas quando for necessário depurar com a interface visível.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Modo sem sandbox do navegador`},help:{"v1-slntux-4w":`Desativa as opções de isolamento de sandbox do Chromium em ambientes onde o sandbox falha durante a execução. Mantenha esta opção desativada sempre que possível, pois as proteções de isolamento de processos são reduzidas.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Perfis do navegador`},help:{"v1-1x8lf05-51":`Mapa de conexões de perfis nomeados do navegador, usado para roteamento explícito para portas ou URLs de CDP, com metadados opcionais. Mantenha os nomes dos perfis consistentes e evite definições de endpoints sobrepostas.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Modo de conexão apenas do perfil do navegador`},help:{"v1-2b5zs0-5a":`Configuração por perfil que substitui o modo de conexão apenas, ignorando a inicialização local do navegador e conectando-se somente a um endpoint CDP existente. Útil quando um perfil é gerenciado externamente, mas os outros são iniciados localmente.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Porta CDP do perfil do navegador`},help:{"v1-gx1yiq-49":`Porta CDP local por perfil, usada ao conectar-se a instâncias do navegador por porta em vez de URL. Use portas exclusivas para cada perfil para evitar conflitos de conexão.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL de CDP do perfil do navegador`},help:{"v1-x491r0-64":`URL do endpoint CDP/DevTools por perfil, usada para roteamento explícito do navegador pelo nome do perfil. Use esta opção para hosts CDP remotos, túneis ou perfis de sessões existentes que devem se conectar por meio de um endpoint do Chrome DevTools em execução.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Driver do perfil do navegador`},help:{"v1-17byyx6-5r":`Modo do driver de navegador por perfil. Use "openclaw" (ou o legado "clawd") para perfis baseados em CDP, "existing-session" para conexão via Chrome DevTools MCP ou "extension" para o relay autenticado da extensão do Chrome.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Caminho do executável do perfil de navegador`},help:{"v1-29azyv-4w":`Caminho do executável do navegador por perfil para perfis de navegador gerenciados iniciados localmente. Substitui browser.executablePath e aceita caminhos que começam com ~ para o diretório pessoal do sistema operacional.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Modo sem interface gráfica do perfil de navegador`},help:{"v1-p4jtgv-4u":`Configuração de modo sem interface gráfica por perfil para instâncias de navegador iniciadas localmente. Use quando um perfil precisar permanecer sem interface gráfica sem forçar browser.headless para todos os outros perfis.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Argumentos do Chrome MCP do perfil de navegador`},help:{"v1-rc45ke-5g":`Argumentos adicionais do Chrome DevTools MCP por perfil para conexão no modo existing-session, como --no-usage-statistics. Os argumentos de endpoint definidos aqui substituem a conexão automática integrada ou a seleção de URL do navegador.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Comando do Chrome MCP do perfil de navegador`},help:{"v1-1xpty8o-2h":`Comando do Chrome DevTools MCP por perfil para conexão no modo existing-session. O padrão é npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Diretório de dados do usuário do perfil de navegador`},help:{"v1-5xvgex-9h":`Diretório de dados do usuário do Chromium por perfil para conexão a uma sessão existente via Chrome DevTools MCP. Use esta opção para Brave, Edge, Chromium ou perfis não padrão do Chrome quando o mecanismo integrado de conexão automática selecionar o diretório de dados do navegador errado no host ou nó de navegador selecionado. Caminhos que começam com ~ são expandidos para o diretório pessoal do usuário no sistema operacional.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Padrões de captura de snapshots do navegador`},help:{"v1-v19wdy-4y":`Configuração padrão de captura de snapshots usada quando quem faz a chamada não fornece opções explícitas de snapshot. Ajuste esta configuração para manter um comportamento de captura consistente entre canais e fluxos de automação.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Modo de snapshot do navegador`},help:{"v1-joeyxp-5c":`Modo padrão de extração de snapshots que controla como o conteúdo da página é transformado para uso pelo agente. Escolha o modo que equilibre legibilidade, fidelidade e consumo de tokens para seus fluxos de trabalho.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Política de SSRF do navegador`},help:{"v1-1qbp9im-5e":`Configurações de proteção contra falsificação de requisições do lado do servidor para fluxos de busca via navegador/rede que possam alcançar hosts internos. Mantenha os padrões restritivos em produção e libere apenas destinos explicitamente aprovados.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Nomes de host permitidos no navegador`},help:{"v1-1rng39-2k":`Nomes de host exatos ou endereços IP literais permitidos pelas verificações da política de SSRF do navegador. Mantenha a lista mínima.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Permitir faixa local exclusiva IPv6 no navegador`},help:{"v1-1glx5cy-2c":`Permitir endereços locais exclusivos IPv6 (fc00::/7) em ambientes de proxy confiáveis com IPs fictícios.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Permitir faixa de benchmark RFC 2544 no navegador`},help:{"v1-10ateu3-2i":`Permite IPs da faixa de benchmark RFC 2544 (198.18.0.0/15) em ambientes confiáveis de proxy com IP fictício.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Nomes de host bloqueados no navegador`},help:{"v1-nug0we-6k":`Padrões de nomes de host bloqueados antes da resolução DNS e das regras de permissão, mesmo com o acesso à rede privada ativado. Aceita hosts exatos e "*.example.com" apenas para subdomínios; adicione "example.com" separadamente para bloquear o domínio raiz. Se estiver vazio ou não definido, nenhum bloqueio será adicionado.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Permitir acesso à rede privada no navegador (perigoso)`},help:{"v1-17103pi-4m":`Permite acesso a faixas de endereços de redes privadas pelas ferramentas do navegador. Desativado por padrão quando não definido; ative apenas para destinos de rede privada explicitamente confiáveis.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Limpeza de abas do navegador`},help:{"v1-1ctwaad-4y":`Política de limpeza, sem garantia de execução, para abas do navegador abertas por sessões do agente principal. Mantenha ativada para evitar o acúmulo de abas obsoletas de sandbox ou do navegador gerenciado em gateways que permanecem ativos por longos períodos.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Limpeza de abas do navegador ativada`},help:{"v1-4sv97p-3u":`Ativa a limpeza de abas monitoradas e ociosas do navegador nas sessões do agente principal. Desative apenas quando ferramentas externas controlarem completamente o ciclo de vida das abas.`}},channels:{label:{"v1-1ju93md-8":`Canais`},help:{"v1-12yv6ma-5n":`Configurações dos provedores de canais e padrões compartilhados que controlam políticas de acesso, visibilidade dos sinais de atividade e comportamento por interface. Mantenha os padrões centralizados e substitua-os por provedor apenas quando necessário.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Padrões de canal`},help:{"v1-uz6veb-4p":`Comportamento padrão dos canais aplicado a todos os provedores quando não há configurações específicas por provedor. Use para garantir uma política básica consistente antes de fazer ajustes por provedor.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Proteção padrão contra loops entre bots`},help:{"v1-1lpznyk-4w":`Configurações padrão de proteção contra loops em pares para provedores de canais que oferecem proteção contra loops entre bots. Use substituições específicas por provedor apenas quando um canal precisar de um limite diferente.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Tempo de espera padrão para loops entre bots em segundos`},help:{"v1-1yl5ird-2z":`Tempo de espera em segundos aplicado a um par após exceder o limite de loops. O padrão para canais compatíveis é 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Proteção padrão contra loops entre bots ativada`},help:{"v1-3ruik-4r":`Ativa por padrão a proteção contra loops em pares nos canais compatíveis quando mensagens criadas por bots podem chegar à etapa de despacho. Os provedores ainda podem desativar a proteção quando os bots são ignorados.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Eventos padrão de loops entre bots por janela`},help:{"v1-1u0mdjc-41":`Número máximo de eventos que um par remetente/destinatário pode trocar dentro da janela configurada antes do início da supressão. O padrão para canais compatíveis é 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Janela padrão de loops entre bots em segundos`},help:{"v1-12xpmen-2m":`Duração da janela deslizante em segundos para os limites de loops entre pares. O padrão para canais compatíveis é 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Visibilidade padrão do contexto`},help:{"v1-1hze3g1-5o":`Visibilidade padrão do contexto suplementar para conteúdo obtido de citações, conversas e histórico: "all" (manter todo o contexto), "allowlist" (somente remetentes na lista de permissões) ou "allowlist_quote" (lista de permissões + manter citações explícitas).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Política padrão de grupos`},help:{"v1-ntl9m4-4n":`Política padrão de grupos em todos os canais: "open", "disabled" ou "allowlist". Mantenha "allowlist" para configurações de produção mais seguras, a menos que a participação ampla em grupos seja intencional.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Visibilidade padrão dos sinais de atividade`},help:{"v1-49bw75-4v":`Configurações padrão de visibilidade dos sinais de atividade para mensagens de status emitidas por provedores/canais. Ajuste globalmente para reduzir o excesso de atualizações de funcionamento normal, mantendo os alertas visíveis.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Exibir alertas dos sinais de atividade`},help:{"v1-8dk8zx-4g":`Exibe alertas de degradação ou erro dos sinais de atividade quando definido como true, para que os canais dos operadores indiquem problemas prontamente. Mantenha ativado em produção para que falhas nos canais fiquem visíveis.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Exibir OK dos sinais de atividade`},help:{"v1-17tg3mk-4z":`Exibe registros de status de heartbeat saudável/OK nas saídas de status dos canais quando definido como true. Mantenha como false em ambientes com muito ruído e habilite apenas quando os operadores precisarem de confirmações explícitas de funcionamento normal.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Usar indicador de heartbeat`},help:{"v1-1w12cs2-4m":`Habilita a exibição concisa do heartbeat como indicador, em vez de texto de status detalhado, quando houver suporte. Use o modo de indicador em painéis densos com muitos canais ativos.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Menções implícitas padrão`},help:{"v1-4gtdyv-48":`Política padrão que determina se respostas ao bot, citações do bot e conversas com participação do bot ativam canais de mensagens compatíveis sem uma menção explícita.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Menções implícitas padrão por citação do bot`},help:{"v1-va1u5v-2v":`Trata mensagens citadas do bot como menções implícitas por padrão. O valor padrão é true para manter a compatibilidade com versões anteriores.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Menções implícitas padrão por resposta ao bot`},help:{"v1-lm44c3-39":`Trata respostas às mensagens do próprio bot como menções implícitas por padrão. O valor padrão é true para manter a compatibilidade com versões anteriores.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Menções implícitas padrão por participação na conversa`},help:{"v1-160205h-3o":`Trata novas mensagens em conversas nas quais o bot participou como menções implícitas por padrão. O valor padrão é true para manter a compatibilidade com versões anteriores.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Substituições de modelo por canal`},help:{"v1-1b01spx-2p":`Mapeie provedor -> ID do canal / ID do contato de mensagem direta -> substituição de modelo (os valores são provedor/modelo ou aliases).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Workers na nuvem`},help:{"v1-10carc4-5v":`Perfis opcionais de workers na nuvem para ambientes remotos descartáveis. Quando esta seção é omitida ou não tem perfis, a criação de workers na nuvem permanece indisponível e o comportamento existente do status do Gateway/nó não muda.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Área de trabalho do worker na nuvem (Labs)`},help:{"v1-vllayc-3n":`Ativa a interface experimental worker.desktop.observe e o painel de área de trabalho da Control UI para ambientes de workers na nuvem compatíveis com área de trabalho.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pool de workers de nuvem preparados`},help:{"v1-rw51o5-6b":`Limites para workers de nuvem preparados, mantidos prontos para sessões futuras. As reservas geram cobranças por máquinas em execução até que a limpeza pelo provedor seja concluída; seu prazo fixo de expiração segue a demanda real do projeto e a política de inatividade existente do provedor.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Limite da reserva de workers na nuvem prontos`},help:{"v1-1mpd1dt-7u":`Limite global do Gateway para workers na nuvem preparados e não atribuídos, abrangendo todos os projetos e perfis (padrão: 4). Workers em preparação e reservas cuja limpeza ainda não foi confirmada contam para o limite. Defina como 0 para esvaziar as reservas não atribuídas e desativar a reposição, preservando a reutilização de snapshots e as sessões ativas.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Perfis de workers na nuvem`},help:{"v1-eii67l-3j":`Perfis nomeados de workers na nuvem. Cada perfil seleciona um provedor de workers registrado por um plugin e contém configurações específicas do provedor.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Perfil de worker na nuvem`},help:{"v1-1v2w7jl-4u":`Um perfil de worker na nuvem selecionado pelo nome ao criar um ambiente. Mantenha as credenciais do provedor em referências compatíveis, em vez de incorporar dados sigilosos neste bloco.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Método de instalação do worker na nuvem`},help:{"v1-blrtbf-74":`Método de instalação do worker: "bundle" (padrão) transfere a compilação instalada do Gateway, identificada pelo hash do conteúdo, e aceita versões lançadas, de desenvolvimento e ainda não lançadas; "npm" instala a versão exata do Gateway e só está disponível quando essa versão já foi lançada.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Provedor de workers na nuvem`},help:{"v1-1p4s4c1-44":`ID do provedor de workers registrado por um plugin. O plugin configurado deve expor esse ID antes que o gateway possa provisionar ambientes a partir do perfil.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Meta da reserva de workers na nuvem prontos`},help:{"v1-1nwve9s-7w":`Quantidade desejada de workers preparados e não atribuídos por projeto elegível que usa este perfil (padrão: 1), sujeita ao limite global do pool de workers preparados do Gateway. Defina como 0 para desativar as reservas deste perfil, preservando a reutilização de snapshots. Workers em preparação e reservas cuja limpeza ainda não foi confirmada contam para a meta.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Configurações do provedor de workers na nuvem`},help:{"v1-mq7u32-4j":`Configurações próprias do provedor, validadas pelo plugin selecionado. Use objetos SecretRef para valores que contenham segredos; configurações opacas não recebem resolução automática de segredos.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Tempo de inatividade para suspensão do worker na nuvem`},help:{"v1-1keuwgh-4w":`Libera automaticamente os recursos de um worker na nuvem inativo após esse período, como 45m ou 2h; a próxima mensagem provisiona um substituto. Mínimo: 1m. Deixe sem definir para manter os workers em execução.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Perfis de workers na nuvem por projeto`},help:{"v1-1kkfrif-46":`Nomes dos perfis padrão de workers na nuvem, indexados pela identidade do repositório normalizada em letras minúsculas (host/owner/repo). IDs de perfil de despacho explícitos têm precedência.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Perfil de worker na nuvem do projeto`},help:{"v1-1mux5u0-30":`Nome do perfil de worker na nuvem usado por padrão quando a origem da árvore de trabalho de uma sessão corresponde a esta identidade de repositório.`}},commands:{label:{"v1-15x4mpf-8":`Comandos`},help:{"v1-1gi0dr2-5a":`Controla as interfaces de comandos de chat, as restrições por proprietário e o comportamento de acesso elevado a comandos entre provedores. Mantenha os padrões, a menos que precise de controles mais rígidos para operadores ou de maior disponibilidade de comandos.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Regras de acesso elevado a comandos`},help:{"v1-7azkw-5g":`Define regras de permissão de comandos elevados por canal e remetente para interfaces de comandos no nível de proprietário. Use identidades específicas de cada provedor com escopo restrito para não expor comandos privilegiados a públicos amplos do chat.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Permitir comando Bash no chat`},help:{"v1-83ah7w-36":"Permite que o comando bash no chat (`!`; alias `/bash`) execute comandos de shell no host (padrão: false; requer tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Janela de execução do Bash em primeiro plano (ms)`},help:{"v1-1o0o4dw-2c":`Tempo que o bash espera antes de passar para segundo plano (padrão: 2000; 0 passa para segundo plano imediatamente).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Permitir /config`},help:{"v1-151bb7c-21":`Permite que o comando /config no chat leia/grave a configuração em disco (padrão: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Permitir /debug`},help:{"v1-y1lc3j-1y":`Permite o comando /debug no chat para substituições válidas apenas em tempo de execução (padrão: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Permitir /mcp`},help:{"v1-1rtwcgd-2o":`Permite que o comando /mcp no chat gerencie a configuração de servidores MCP do OpenClaw em mcp.servers (padrão: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Comandos nativos`},help:{"v1-dighr2-5n":`Registra comandos nativos de barra/menu nos canais que oferecem suporte ao registro de comandos (Discord, Slack, Telegram). Mantenha ativado para facilitar a descoberta, a menos que você use intencionalmente fluxos de trabalho com comandos somente de texto.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Comandos nativos de habilidades`},help:{"v1-19gtqci-5h":`Registra comandos nativos de habilidades para que os usuários possam invocar habilidades diretamente nos menus de comandos do provedor, quando houver suporte. Mantenha o alinhamento com sua política de habilidades para que os comandos expostos correspondam ao que os operadores esperam.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Proprietários de comandos`},help:{"v1-1di38gv-3y":`Lista explícita de proprietários autorizados para comandos restritos a proprietários. Use IDs nativos do canal (opcionalmente com prefixo, como "whatsapp:+15551234567"). '*' é ignorado.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Permitir /plugins`},help:{"v1-akwy9y-33":`Permite que o comando de chat /plugins liste os plugins descobertos e ative ou desative plugins na configuração (padrão: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Permitir reinicialização`},help:{"v1-m32fv2-27":`Permitir /restart, /update e solicitações externas de reinicialização via SIGUSR2 (padrão: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Comandos de texto`},help:{"v1-1utu76s-5j":`Habilita a interpretação de comandos de texto na entrada do chat, além das interfaces de comandos nativos, quando disponíveis. Mantenha esta opção habilitada para garantir a compatibilidade com canais que não oferecem suporte ao registro de comandos nativos.`}},cron:{label:{"v1-1qlte4b-b":`Automações`},help:{"v1-4md8ic-5u":`Configurações globais do agendador para automações armazenadas, execuções simultâneas, entrega alternativa e retenção de sessões de execução. Mantenha os padrões, a menos que esteja aumentando o volume de automações ou integrando receptores externos de webhook.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automações habilitadas`},help:{"v1-y8otx6-5i":`Habilita a execução de automações para agendamentos armazenados gerenciados pelo Gateway. Mantenha esta opção habilitada para os fluxos normais de lembretes e automações e desabilite-a apenas para pausar todas as execuções de automações sem excluir tarefas.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Retenção de sessões de automações`},help:{"v1-4wagu6-7e":"Controla por quanto tempo as sessões de execuções de automação concluídas são mantidas antes da limpeza (`24h`, `7d`, `1h30m` ou `false` para desativar a limpeza; uma duração zero, como `0h`, também a desativa; padrão: `24h`). Use uma retenção mais curta para reduzir o crescimento do armazenamento em agendamentos de alta frequência."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Ignorar automações recorrentes não executadas`},help:{"v1-w9wfmo-66":`Ignora os horários recorrentes de cron/every não executados na inicialização do Gateway e agenda a próxima ocorrência futura em vez de executar as ocorrências atrasadas. Padrão: false. Ative para evitar lembretes desatualizados após períodos de inatividade; tarefas únicas do tipo at ainda são executadas se estiverem atrasadas.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Política de SSRF dos webhooks de automação`},help:{"v1-1xlfqnu-5h":`Política de SSRF aplicada a todos os webhooks de saída de automação. Destinos privados, de loopback, de link local e internos permanecem bloqueados, a menos que esta política os permita explicitamente. Deixe sem configuração para manter as restrições rigorosas de entrega.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Nomes de host permitidos para webhooks de automação`},help:{"v1-1i94hyz-3n":`Nomes de host exatos ou endereços IP literais permitidos para a entrega de webhooks de automação, incluindo destinos que seriam bloqueados de outra forma. Mantenha a lista com o mínimo necessário.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Permitir faixa local única IPv6 para webhooks de automação`},help:{"v1-rke0oj-3b":`Permite webhooks de automação para endereços locais únicos IPv6 (fc00::/7). Use apenas em ambientes confiáveis de proxy com IP fictício.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Permitir faixa de benchmark RFC 2544 para webhooks de automação`},help:{"v1-x1usg4-3h":`Permite webhooks de automação para IPs da faixa de benchmark RFC 2544 (198.18.0.0/15). Use apenas em ambientes confiáveis de proxy com IPs fictícios.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Nomes de host bloqueados para webhooks de automação`},help:{"v1-16cv1ic-6a":`Padrões de nomes de host bloqueados antes da resolução DNS e das regras de permissão para entrega de webhooks de automação. Aceita hosts exatos e "*.example.com" apenas para subdomínios; adicione "example.com" separadamente para bloquear o domínio raiz. Se estiver vazio ou não definido, não adiciona bloqueios.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Permitir acesso perigoso à rede privada para webhooks de automação`},help:{"v1-1n9710c-3t":`Permite webhooks de automação para destinos em redes privadas e internas. Mantenha desativado, a menos que todos os destinos de webhook configurados sejam confiáveis.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token Bearer para webhooks de automação`},help:{"v1-1l90hxg-5l":`Token Bearer anexado às entregas POST de webhooks de automação quando o modo webhook é usado. Prefira a substituição por segredos ou variáveis de ambiente e faça a rotação deste token regularmente se os endpoints de webhook compartilhados forem acessíveis pela internet.`}},desktop:{label:{"v1-rs698z-7":`Área de trabalho`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Área de trabalho local`},help:{"v1-99weio-30":`Visualização da área de trabalho de nós pareados ou da fonte experimental do host do Gateway, usando um servidor VNC local.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Compartilhamento da área de trabalho`},help:{"v1-m9lbcj-83":`Habilita a fonte de área de trabalho desta máquina. Nós macOS, Windows e Linux pareados ficam habilitados por padrão; uma preferência explícita de compartilhamento no aplicativo para desktop tem prioridade. A fonte Labs do host do Gateway fica desabilitada por padrão e aplica as alterações em tempo real. Reinicie um nó pareado após alterar sua configuração de área de trabalho.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Área de trabalho gerenciada do host Linux`},help:{"v1-1r7n22m-49":`Executa e supervisiona um ambiente de área de trabalho TigerVNC/XFCE sem monitor, acessível apenas via loopback, no Linux. Uma porta explícita ou um servidor VNC existente na porta padrão ainda tem precedência.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Arquivo de senha do VNC local`},help:{"v1-1m5lsox-37":`Caminho absoluto para o arquivo de senha do VNC. No macOS, omita este campo para inserir as credenciais da conta ao abrir o visualizador da área de trabalho.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Porta do VNC local`},help:{"v1-1ku4w9b-2b":`Porta RFB de loopback de um servidor VNC já em execução nesta máquina (padrão: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnóstico`},help:{"v1-1d5rnym-5p":`Controles de diagnóstico para rastreamento direcionado, exportação de telemetria e inspeção de cache durante a depuração. Mantenha os diagnósticos básicos no mínimo em produção e ative sinais mais detalhados apenas ao investigar problemas.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Rastreamento de cache`},help:{"v1-10523zm-5b":`Configurações de registro de rastreamento de cache para observar decisões de cache e o contexto da carga útil em execuções incorporadas. Ative temporariamente para depuração e desative depois para reduzir a quantidade de dados sensíveis nos logs.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Rastreamento de cache ativado`},help:{"v1-2c1umi-1v":`Registra instantâneos de rastreamento de cache para execuções de agentes incorporados (padrão: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnósticos ativados`},help:{"v1-a46pxt-4h":`Controle principal da saída da instrumentação de diagnóstico nos logs e nos caminhos de integração de telemetria. Ativado por padrão; defina como false apenas em ambientes com restrições rigorosas.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Sinalizadores de diagnóstico`},help:{"v1-x4w5ok-33":`Ative logs de diagnóstico específicos por sinalizador (por exemplo, ["telegram.http"]). Aceita curingas como "telegram.*" ou "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Configurações de exportação do OpenTelemetry para rastreamentos, métricas e logs emitidos pelos componentes do Gateway. Use ao integrar com backends centralizados de observabilidade e pipelines de rastreamento distribuído.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Captura de conteúdo do OpenTelemetry`},help:{"v1-19tid4t-2t":`Captura opcional de conteúdo de spans OTEL. Desativada por padrão; true captura o conteúdo de mensagens que não sejam do sistema e de ferramentas.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry ativado`},help:{"v1-193bm0-5b":`Ativa o pipeline de exportação do OpenTelemetry para rastreamentos, métricas e logs com base nas configurações de endpoint/protocolo. Mantenha desativado até que o endpoint do coletor e a autenticação estejam totalmente configurados.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Endpoint do OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL do endpoint do coletor usada no transporte de exportação do OpenTelemetry, incluindo esquema e porta. Use um endpoint de coletor acessível e confiável e monitore os erros de ingestão após a implantação.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Intervalo de envio do OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Intervalo em milissegundos para o envio periódico de telemetria dos buffers ao coletor. Aumente para reduzir a frequência das exportações ou diminua para obter visibilidade mais rápida durante a resposta ativa a incidentes.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Cabeçalhos do OpenTelemetry`},help:{"v1-s26t2a-52":`Cabeçalhos HTTP adicionais enviados com as solicitações de exportação do OpenTelemetry, geralmente usados para autenticação de tenants ou roteamento. Mantenha os segredos em valores provenientes de variáveis de ambiente e evite a proliferação desnecessária de cabeçalhos.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Logs do OpenTelemetry habilitados`},help:{"v1-12wo6rv-4k":`Habilita a exportação de sinais de log pelo OpenTelemetry, além dos destinos de log locais. Use quando for necessária a correlação centralizada de logs entre serviços e agentes.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Endpoint de logs do OpenTelemetry`},help:{"v1-1vgzldu-40":`Endpoint OTLP/HTTP específico para sinais de log. Quando definido, substitui diagnostics.otel.endpoint e OTEL_EXPORTER_OTLP_ENDPOINT apenas para a exportação de logs.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Exportador de logs do OpenTelemetry`},help:{"v1-9bzywd-5q":`Destino de exportação de logs para diagnostics.otel.logs. Use "otlp" para o endpoint de logs OTLP configurado, "stdout" para um registro JSON por linha de stdout em pipelines de logs de contêineres e "both" quando ambos os destinos forem necessários.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefixo dos nomes de métricas do OpenTelemetry`},help:{"v1-1epdpi9-b2":`Substitui o prefixo padrão "openclaw." nos nomes de métricas pertencentes ao OpenClaw. Use uma string vazia para remover o prefixo ou até 128 caracteres ASCII entre letras, dígitos, sublinhados, pontos, hífens e barras, começando com uma letra. Inclua qualquer separador necessário, por exemplo, "acme."; os nomes de métricas padrão gen_ai.* permanecem inalterados. Alterar esse valor exige atualizar os painéis e alertas que consultam os nomes antigos.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Métricas do OpenTelemetry habilitadas`},help:{"v1-13r4cf4-4x":`Ative a exportação de sinais de métricas para o endpoint configurado do coletor OpenTelemetry. Mantenha ativada para painéis de integridade em tempo de execução e desative apenas se for necessário minimizar o volume de métricas.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Endpoint de métricas do OpenTelemetry`},help:{"v1-qlfh7x-47":`Endpoint de métricas OTLP/HTTP específico para esse sinal. Quando definido, substitui diagnostics.otel.endpoint e OTEL_EXPORTER_OTLP_ENDPOINT apenas na exportação de métricas.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protocolo do OpenTelemetry`},help:{"v1-17ine8s-5e":`Protocolo de transporte OTel para exportação de telemetria. Apenas "http/protobuf" é aceito; execute "openclaw doctor --fix" para corrigir um valor legado "grpc" persistido ou obter orientações de edição manual específicas para a origem.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Taxa de amostragem de rastreamentos do OpenTelemetry`},help:{"v1-brcwep-50":`Taxa de amostragem de rastreamentos (0-1) que controla quanto tráfego de rastreamento é exportado para backends de observabilidade. Taxas menores reduzem a sobrecarga e o custo, enquanto taxas maiores melhoram a fidelidade da depuração.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nome do serviço do OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nome do serviço informado nos atributos de recurso da telemetria para identificar esta instância do Gateway nos backends de observabilidade. Use nomes estáveis para que painéis e alertas permaneçam consistentes entre implantações.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Rastreamentos do OpenTelemetry ativados`},help:{"v1-j7zrrp-4s":`Ative a exportação de sinais de rastreamento para o endpoint configurado do coletor OpenTelemetry. Mantenha ativada quando precisar de rastreamentos de latência ou depuração e desative se quiser apenas métricas e logs.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Endpoint de traces do OpenTelemetry`},help:{"v1-8yw5p1-43":`Endpoint de traces OTLP/HTTP específico para o tipo de sinal. Quando definido, substitui diagnostics.otel.endpoint e OTEL_EXPORTER_OTLP_ENDPOINT apenas para a exportação de traces.`}},discovery:{label:{"v1-l2sr05-9":`Descoberta`},help:{"v1-1sqleij-4w":`Configurações de descoberta de serviços para anúncio local via mDNS e sinalização opcional de presença em redes de longa distância. Restrinja a descoberta às redes esperadas para evitar o vazamento de metadados dos serviços.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Descoberta via mDNS`},help:{"v1-vtbyyq-4w":`Grupo de configurações de descoberta via mDNS para anúncio na rede local e ajuste do comportamento de descoberta. Mantenha o modo mínimo para a descoberta rotineira na LAN, a menos que sejam necessários metadados adicionais.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Modo de descoberta via mDNS`},help:{"v1-1p28pd5-2m":`Modo de transmissão mDNS ("minimal" é o padrão, "full" inclui cliPath/sshPort, "off" desativa o mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Descoberta em redes de longa distância`},help:{"v1-1akkqjm-53":`Grupo de configurações de descoberta em redes de longa distância para expor sinais de descoberta além do escopo do enlace local. Ative apenas em implantações que agreguem intencionalmente a presença de gateways em diferentes locais.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domínio de descoberta em redes de longa distância`},help:{"v1-rxrygo-4m":`Domínio DNS-SD unicast opcional para descoberta em redes de longa distância, como openclaw.internal. Use quando quiser publicar intencionalmente a descoberta de gateways além do escopo do mDNS local.`}},env:{label:{"v1-1zc80q-b":`Ambiente`},help:{"v1-1ao5po6-55":`Configurações de importação e sobrescrita do ambiente usadas para fornecer variáveis de execução ao processo do gateway. Use esta seção para controlar o carregamento do ambiente do shell e o comportamento de injeção explícita de variáveis.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Importação do ambiente do shell`},help:{"v1-1gw487t-4y":`Controles de importação do ambiente do shell para carregar variáveis do seu shell de login durante a inicialização. Mantenha esta opção ativada se você depende de segredos definidos no perfil ou de personalizações de PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Importação do ambiente do shell ativada`},help:{"v1-5tiuup-5u":`Permite carregar variáveis de ambiente do perfil de shell do usuário durante a inicialização. Mantenha esta opção ativada em máquinas de desenvolvimento ou desative-a em ambientes de serviço restritos com gerenciamento explícito de variáveis de ambiente.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Tempo limite de importação do ambiente do shell (ms)`},help:{"v1-nsk2yf-5c":`Tempo máximo em milissegundos permitido para a resolução do ambiente do shell antes de aplicar o comportamento alternativo. Use tempos limites menores para uma inicialização mais rápida ou aumente-os quando a inicialização do shell for demorada.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Substituições de variáveis de ambiente`},help:{"v1-yxc3z7-5n":`Substituições explícitas de variáveis de ambiente em pares de chave/valor, incorporadas ao ambiente do processo do OpenClaw em tempo de execução. Use esta opção para uma configuração determinística do ambiente, em vez de depender apenas dos efeitos indiretos do perfil do shell.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Configurações de execução do Gateway para modo de vinculação, autenticação, interface de controle, transporte remoto e controles de segurança operacional. Mantenha os padrões conservadores, a menos que você queira expor o gateway além das interfaces locais confiáveis.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Permitir x-real-ip como alternativa no Gateway`},help:{"v1-1wr3qmw-4c":`Permite usar x-real-ip como alternativa quando x-forwarded-for estiver ausente em cenários com proxy. Mantenha esta opção desativada, a menos que sua infraestrutura de entrada exija esse comportamento de compatibilidade.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Autenticação do Gateway`},help:{"v1-70b6ni-50":`Política de autenticação para acesso HTTP/WebSocket ao Gateway, incluindo modo, credenciais, comportamento de proxy confiável e limitação de taxa. Mantenha a autenticação ativada em todas as implantações com acesso fora do loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Permitir identidade Tailscale na autenticação do Gateway`},help:{"v1-vqtmgw-53":`Permite que mecanismos de identidade confiáveis do Tailscale satisfaçam as verificações de autenticação do Gateway quando configurados. Use esta opção somente quando a segurança das identidades da sua tailnet for robusta e os fluxos de trabalho dos operadores dependerem dela.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Concessões de escopo por identidade do Gateway`},help:{"v1-1h0zxy7-5n":`Mapeia identidades verificadas de proxy confiável ou Tailscale para concessões de escopo de operador válidas apenas para a conexão. As chaves de e-mail são comparadas sem diferenciar maiúsculas de minúsculas; as concessões ampliam os escopos do dispositivo antes da aplicação do limite de escopo da conexão.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Modo de autenticação do Gateway`},help:{"v1-j8rodq-9t":`Modo de autenticação do Gateway: "none", "token", "password" ou "trusted-proxy", dependendo da sua arquitetura de borda. O modo token/password seleciona o segredo configurado (gateway.auth.token ou gateway.auth.password); os clientes podem enviá-lo em qualquer um dos campos de autenticação de connect. Use token/password para exposição direta e trusted-proxy somente atrás de proxies com reconhecimento de identidade e segurança reforçada.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Senha do Gateway`},help:{"v1-1ndt0u2-4g":`Segredo compartilhado selecionado por gateway.auth.mode=password. Os clientes podem enviá-lo em auth.token ou auth.password. O modo de senha é obrigatório para o Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Limite de taxa de autenticação do Gateway`},help:{"v1-1kstr42-54":`Controles de limitação de tentativas de login/autenticação para reduzir o risco de ataques de força bruta contra credenciais no perímetro do gateway. Mantenha-os ativados em ambientes expostos e ajuste os limites ao seu padrão de tráfego.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token do Gateway`},help:{"v1-16i7cxs-5q":`Segredo compartilhado selecionado por gateway.auth.mode=token, o padrão para novas configurações locais. Os clientes podem enviá-lo em auth.token ou auth.password. Vinculações a endereços que não sejam de loopback exigem um modo de autenticação ativado.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Autenticação do Gateway por proxy confiável`},help:{"v1-12fsi5d-58":`Mapeamento de cabeçalhos de autenticação por proxy confiável para provedores de identidade upstream que injetam declarações de usuário. Use apenas com CIDRs de proxy conhecidos e listas restritas de cabeçalhos permitidos para impedir cabeçalhos de identidade falsificados.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Identidade do GitHub via OIDC do Cloudflare Access`},help:{"v1-1puth4k-6t":`Identidade verificada opcional do GitHub proveniente de um provedor OIDC selecionado do Cloudflare Access. Requer os cabeçalhos padrão de e-mail e de asserção do Access. Na ausência de declarações, os perfis continuam usando apenas e-mail; as funções existentes do perfil e as preferências de coautoria são preservadas.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Declaração do ID da conta do GitHub`},help:{"v1-pcaaw7-57":`Declaração OIDC encaminhada exata cujo valor é um ID de conta do GitHub verificado, representado como uma string decimal positiva. Configure o Access para encaminhá-la em oidc_fields; nunca use uma declaração não verificada que possa ser editada pelo usuário.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Emissor do Cloudflare Access`},help:{"v1-gykv03-56":`Origem HTTPS exata da equipe confiável do Cloudflare Access, como https://example.cloudflareaccess.com, sem barra final. As declarações de outros emissores não fornecem identidade do GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID do provedor OIDC do Cloudflare Access`},help:{"v1-kbyo5w-44":`ID exato do provedor de identidade do Access para a integração OIDC confiável. Um nome de exibição do provedor ou um nome de declaração correspondente, por si só, não estabelece confiança.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Aprovação automática de dispositivos por proxy confiável`},help:{"v1-uh32ha-6z":`Política opcional para aprovar automaticamente novos dispositivos de operadores que usam o navegador ou a interface nativa, além de ampliações de escopo com a mesma chave, após a autenticação por proxy confiável. As permissões concedidas são limitadas por deviceAutoApprove.scopes e pelo cabeçalho x-openclaw-scopes do proxy, quando presente.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Aprovação automática de dispositivos por proxy confiável ativada`},help:{"v1-1nntwls-78":`Aprova automaticamente novos dispositivos de operadores que usam o navegador ou a interface nativa, além de ampliações de escopo com a mesma chave, depois que o proxy reverso autentica um usuário autorizado. Padrão: false. Ative apenas quando o perímetro de identidade do proxy for robusto o suficiente para substituir o pareamento manual de dispositivos.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Escopos de aprovação automática de dispositivos via proxy confiável`},help:{"v1-raeila-g3":`Escopos máximos concedidos a dispositivos de operadores aprovados automaticamente. Os valores padrão são operator.read, operator.write, operator.approvals e operator.questions. Os escopos solicitados são limitados a esta lista; solicitações sem escopos recebem esta lista. Quando não configurada, a aprovação automática também adiciona operator.questions para clientes de interface mais antigos; uma lista explícita nunca é ampliada. Incluir operator.admin explicitamente permite que todos os usuários autenticados pelo proxy aprovem automaticamente o acesso administrativo completo e faz com que solicitações sem escopos recebam esse acesso automaticamente; isso também gera uma ocorrência crítica na auditoria de segurança e um aviso na inicialização do Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Modo de vinculação do Gateway`},help:{"v1-1unqude-4y":`Perfil de vinculação de rede: "auto", "lan", "loopback", "custom" ou "tailnet" para controlar a exposição das interfaces. Mantenha "loopback" para operação apenas local; "auto" pode expor todas as interfaces.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agentes CLI`},help:{"v1-1qqo8m2-5a":`Descoberta na Control UI de mecanismos externos de sessão CLI expostos pelo catálogo de sessões do Gateway. Ativada por padrão; desative para impedir a inicialização desses mecanismos pelo seletor de modelos de nova sessão.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agentes CLI ativados`},help:{"v1-ufu7fx-8p":`Exibe agentes CLI provenientes do catálogo no seletor de modelos de novas sessões da Control UI quando definido como true (padrão: true). Defina como false para desativar os agentes CLI e a criação de sessões CLI nativas. Somente catálogos que anunciam suporte à criação de sessões são listados, e o seletor permanece oculto quando o Gateway não anuncia suporte ao catálogo de sessões.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Configurações de hospedagem da Control UI, incluindo ativação, caminhos e comportamento de reforço de segurança de origens do navegador e autenticação. Mantenha a exposição da interface ao mínimo e combine-a com controles de autenticação robustos antes de implantações expostas à internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Origens permitidas da Control UI`},help:{"v1-1stgitk-9i":`Origens do navegador permitidas para conexões WebSocket da Control UI/WebChat (somente origens completas, por exemplo, https://control.example.com). Obrigatório para implantações da Control UI fora do endereço de loopback, a menos que o uso perigoso do cabeçalho Host como alternativa esteja explicitamente ativado. Definir ["*"] permite qualquer origem do navegador e deve ser evitado fora de testes locais rigorosamente controlados.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Permitir URLs externas de incorporação na Control UI`},help:{"v1-obwpfg-6s":`Opção PERIGOSA que permite que incorporações hospedadas carreguem URLs http(s) externas absolutas. Mantenha esta opção desativada, a menos que sua Control UI incorpore intencionalmente páginas confiáveis de terceiros; documentos hospedados em /__openclaw__/canvas e /__openclaw__/a2ui não precisam dela.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Buscar favicons de links automaticamente`},help:{"v1-bn9u34-ag":`Buscar favicons de links e prévias sociais das abas do navegador por meio do Gateway (ativado por padrão). Os cartões das abas do navegador carregam metadados públicos das páginas e imagens declaradas sem usar cookies do navegador nem credenciais dos sites. Todas as solicitações usam verificações rigorosas de SSRF e processamento limitado de HTML e imagens. Defina como false para desativar tanto a busca automática de favicons quanto a de prévias de páginas; as capturas de tela ao vivo do navegador não são afetadas.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Caminho base da Control UI`},help:{"v1-1dx68ar-1w":`Prefixo de URL opcional no qual a Control UI é servida (por exemplo, /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Convite para a comunidade na Control UI`},help:{"v1-1rz3zsx-73":`Exibe o convite para a comunidade no Discord na Control UI servida por este Gateway (ativado por padrão). Defina como false para ocultá-lo em todos os navegadores que usam esta implantação da UI. As alterações são aplicadas após atualizar a página ou reconectar; a reativação preserva as dispensas locais de cada navegador.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Permitir fallback de origem pelo cabeçalho Host (perigoso)`},help:{"v1-1t1qi4c-7v":`Opção PERIGOSA que habilita o fallback de origem baseado no cabeçalho Host para verificações de WebSocket da Control UI/WebChat. Este modo é compatível com implantações que dependem intencionalmente de uma política de origem baseada no cabeçalho Host; a configuração explícita de gateway.controlUi.allowedOrigins continua sendo o padrão recomendado para maior segurança.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Modo sandbox de conteúdo incorporado da Control UI`},help:{"v1-d54l3a-7c":'Política de sandbox de iframe para conteúdo incorporado hospedado na Control UI. "strict" desativa scripts, "scripts" permite conteúdo incorporado interativo mantendo o isolamento de origem (padrão), e "trusted" adiciona `allow-same-origin` para documentos do mesmo site que precisam intencionalmente de privilégios mais elevados.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI ativada`},help:{"v1-1hhyymc-4w":`Habilita o fornecimento da Control UI do gateway pelo processo HTTP do gateway quando definido como true. Mantenha ativado para administração local e desative quando uma interface de controle externa a substituir.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Ambiente da Control UI`},help:{"v1-paarso-4n":`Identidade pública opcional do ambiente, exibida na faixa da Control UI, no avatar do agente, nos selos de rótulo, no título do navegador e no favicon. Omita-a para preservar a aparência padrão.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Cor do ambiente da Control UI`},help:{"v1-mp6cta-2i":`Escala de cores nomeada do ambiente: teal, amber, purple, coral, pink, blue, green, red ou gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Rótulo do ambiente da Control UI`},help:{"v1-1njve3z-3z":`Rótulo do ambiente exibido na Control UI e na aba do navegador; os espaços em branco no início e no fim são removidos, e o rótulo deve conter de 1 a 24 caracteres.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Recursos experimentais da Control UI`},help:{"v1-1qobi2m-3g":`Experimentos da Control UI com ativação opcional. Esses recursos podem mudar entre versões e permanecem desativados, a menos que sejam ativados explicitamente.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Interface de plugins personalizados`},help:{"v1-108u6ts-9e":`Permita que plugins instalados pelo usuário executem JavaScript nativo na Control UI (padrão: false). As visualizações dos plugins incluídos continuam disponíveis. A interface personalizada compartilha as permissões de Gateway do operador conectado; ative apenas para plugins confiáveis. As alterações são aplicadas sem reiniciar o Gateway. Recarregue as páginas abertas da Control UI para limpar o código de plugins carregado anteriormente.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Credencial de serviço do GitHub para a Control UI`},help:{"v1-1p31phh-d6":`Credencial de serviço baseada em SecretRef para descoberta de projetos na Control UI e prévias do GitHub ao passar o cursor, sem uma identidade gerenciada. As prévias ao passar o cursor priorizam a identidade do GitHub configurada para o agente selecionado, herdando a identidade do sistema quando não há substituição. Prefira uma configuração explícita para definir claramente a responsabilidade pelo serviço. Omita este campo para manter o uso de GH_TOKEN/GITHUB_TOKEN como alternativa no ambiente compartilhado do processo do Gateway. Uma credencial configurada explicitamente, mas indisponível, bloqueia o acesso por segurança.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Diretório raiz dos recursos da Control UI`},help:{"v1-elck04-25":`Diretório raiz opcional no sistema de arquivos para os recursos da Control UI (padrão: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Observador de sessões da Control UI`},help:{"v1-1ahs80-8a":`Produz resumos de status das sessões em tempo real para clientes inscritos da Control UI usando o modelo utilitário de cada agente (ativado por padrão). Defina como false para desativar as chamadas ao modelo observador em todo o Gateway; definir agents.defaults.utilityModel como uma string vazia desativa a observação pelo modelo utilitário para agentes que não substituem essa configuração.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Host de vinculação personalizado do Gateway`},help:{"v1-lwjcyo-4d":`Endereço IPv4 usado para uma vinculação personalizada. Endereços IPv4 específicos também exigem a mesma porta do Gateway em 127.0.0.1; evite 0.0.0.0, a menos que seja necessário expor o serviço em todas as interfaces.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP do Gateway`},help:{"v1-ebtex7-4j":`Configuração da API HTTP do Gateway que agrupa opções de ativação de endpoints e controles de exposição da API na camada de transporte. Mantenha habilitados apenas os endpoints necessários para reduzir a superfície de ataque.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Endpoints HTTP do Gateway`},help:{"v1-1a0r104-55":`Controles de ativação de endpoints HTTP na API do Gateway para rotas de compatibilidade e integrações opcionais. Ative os endpoints de forma deliberada e monitore os padrões de acesso após a implantação.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Endpoint do OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Ative o endpoint `POST /v1/chat/completions` compatível com a OpenAI (padrão: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Limites de imagem do OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Controles de busca e validação de imagens para partes `image_url` compatíveis com a OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Lista de tipos MIME de imagem permitidos do OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Tipos MIME permitidos para partes `image_url` (lista sem distinção entre maiúsculas e minúsculas)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Permitir URLs de imagens no OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Permita buscas por URL no lado do servidor para partes `image_url` (padrão: false; URIs de dados continuam sendo aceitos). Defina como `false` para desativar completamente a busca por URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Máximo de bytes por imagem do OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Máximo de bytes por imagem `image_url` obtida ou decodificada (padrão: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Máximo de redirecionamentos de imagens do OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Número máximo de redirecionamentos HTTP permitidos ao buscar URLs de `image_url` (padrão: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Tempo limite para imagens do OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Tempo limite em milissegundos para buscas de URLs de `image_url` (padrão: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Lista de URLs de imagens permitidas do OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Lista opcional de nomes de host permitidos para buscas de URLs de `image_url`; aceita hosts exatos e curingas como `*.example.com`. Listas vazias ou omitidas indicam que não há restrição por lista de nomes de host permitidos."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Cabeçalhos de segurança HTTP do Gateway`},help:{"v1-n8z1hb-44":`Cabeçalhos de segurança de resposta HTTP opcionais aplicados pelo próprio processo do Gateway. Prefira configurá-los no proxy reverso quando o TLS terminar nele.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Cabeçalho de segurança de transporte estrita`},help:{"v1-1buwhc3-3v":`Valor do cabeçalho de resposta Strict-Transport-Security. Defina apenas em origens HTTPS que você controle totalmente; use false para desativar explicitamente.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Modo do Gateway`},help:{"v1-nfjirv-5m":`Modo de operação do Gateway: "local" executa os canais e o ambiente de execução do agente neste host, enquanto "remote" se conecta por transporte remoto. Mantenha "local", a menos que você execute intencionalmente uma topologia dividida com Gateway remoto.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills dos nós do Gateway habilitadas`},help:{"v1-1xwu6at-3g":`Aceita Skills publicadas por nós pareados enquanto estiverem conectados (padrão: true). Defina como false para ignorar Skills publicadas pelos nós.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Modo de navegador dos nós do Gateway`},help:{"v1-oeu1nc-69":`Roteamento do navegador por nós ("auto" = dar preferência ao navegador do host e usar um único nó de navegador conectado quando o recurso local estiver indisponível; "manual" = exigir a seleção explícita de um nó ou uma vinculação configurada; "off" = desativar o roteamento por nós).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Fixação do nó de navegador do Gateway`},help:{"v1-1cykty2-1p":`Fixa o roteamento do navegador a um ID ou nome de nó específico (opcional).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Lista de permissões dos nós do Gateway (comandos extras)`},help:{"v1-6l4otb-5m":"Comandos node.invoke extras a permitir além dos padrões do Gateway (array de strings de comandos). Habilitar comandos perigosos aqui é uma alteração sensível à segurança e é sinalizada por `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Lista de bloqueio dos nós do Gateway`},help:{"v1-u7c8wx-53":"Nomes de comandos dos nós a bloquear mesmo que estejam presentes nas declarações dos nós ou na lista de permissões padrão (apenas correspondência exata do nome do comando, por exemplo, `system.run`; não inspeciona o texto de shell dentro desse comando)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Pareamento dos nós do Gateway`},help:{"v1-gldsi2-4s":`Configurações da política de pareamento de nós. A aprovação automática verificada por SSH é habilitada por padrão; a aprovação automática por CIDR permanece desabilitada, a menos que listas explícitas de CIDRs/IPs confiáveis permitidos sejam configuradas.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDRs para aprovação automática do pareamento de nós do Gateway`},help:{"v1-1m6jsxj-6x":`Lista opcional de CIDRs/IPs permitidos para aprovar automaticamente o primeiro pareamento de dispositivos com função de nó, sem escopos solicitados. Desabilitada quando não definida. Pareamentos de operador, navegador e Control UI, bem como qualquer pareamento que amplie funções, escopos, metadados ou chaves públicas, ainda exigem aprovação manual.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Aprovação automática local do pareamento de nós do Gateway`},help:{"v1-glzm36-41":`Aprova silenciosamente pareamentos locais confiáveis e ampliações de acesso (padrão: true); defina como false para trocar a conveniência pela aprovação explícita de cada dispositivo.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Verificação SSH do pareamento de nós do Gateway`},help:{"v1-1e4da92-ct":"Aprovação automática verificada por SSH para o primeiro pareamento de dispositivos com função de nó (padrão: habilitada). O Gateway se conecta de volta via SSH ao host que solicita o pareamento (BatchMode, verificação estrita de chaves de host) e aprova somente quando a saída remota de `openclaw node identity` corresponde à chave do dispositivo pendente. Defina como false para desabilitar a verificação SSH (independentemente de autoApproveCidrs, que permanece ativo); para permitir apenas pareamento manual, remova também a definição de autoApproveCidrs. Passe um objeto para substituir user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Ferramentas de plugins de nós do Gateway`},help:{"v1-1c24iq3-28":`Controla se os nós pareados podem publicar descritores de ferramentas de plugins visíveis para o agente.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Ferramentas de plugins dos nós do Gateway habilitadas`},help:{"v1-14lgfu6-47":`Aceita descritores de ferramentas de plugins visíveis para o agente publicados por nós pareados (padrão: true). Defina como false para ignorar e remover todas as ferramentas de plugins publicadas pelos nós.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Porta do Gateway`},help:{"v1-for8t5-54":`Porta TCP usada pelo serviço de escuta do Gateway para a API, a Control UI e as rotas de entrada dos canais. Use uma porta dedicada e evite conflitos com proxies reversos ou serviços de desenvolvimento locais.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portais do Gateway`},help:{"v1-1v2lkw9-1c":`Configurações de publicação de portais e entrada privada.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Entrada privada de portais`},help:{"v1-20w4gq-69":`Proxy reverso HTTPS privado opcional com domínio curinga, gerenciado pelo operador. Encaminhe o Host original, os caminhos e as atualizações de protocolo WebSocket para o listener de loopback dedicado. A autenticação por token bearer do portal continua sendo obrigatória. Exige a reinicialização do Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Domínio curinga de portais`},help:{"v1-1ipbfad-53":`Domínio DNS sem prefixos para subdomínios aleatórios de portais (por exemplo, previews.example.net). Configure o DNS curinga e o HTTPS de forma privada; não compartilhe o espaço de nomes de host do Gateway ou do Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Porta de loopback de entrada de portais`},help:{"v1-1mb98cv-4g":`Porta HTTP de loopback dedicada que recebe o tráfego do proxy HTTPS privado com curinga. Deve ser diferente da porta do Gateway. Esta é a porta do backend, não a porta HTTPS pública.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origem pública do Gateway`},help:{"v1-17vekvx-87":`Origem HTTPS do Gateway acessível externamente. HTTP é permitido apenas para localhost, 127.0.0.1 ou [::1]. O OAuth do MCP por solicitante a utiliza para construir a URL de retorno em /oauth/mcp/callback; links de sessões de canais e links de visualização gerados por plugins a utilizam para acessar a Control UI e as rotas do Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Entrega de notificações push do Gateway`},help:{"v1-h23oz7-5s":`Configurações de entrega de notificações push usadas pelo Gateway quando precisa ativar ou notificar dispositivos pareados. Configure aqui o APNs via retransmissor para compilações oficiais do iOS; a autenticação direta do APNs continua sendo feita por variáveis de ambiente para compilações locais/manuais.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Entrega via APNs do Gateway`},help:{"v1-4bbafr-4e":`Configurações de entrega via APNs para dispositivos iOS pareados com este Gateway. Use as configurações do retransmissor para compilações oficiais da App Store que se registram por meio do retransmissor externo de notificações push.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Retransmissor APNs do Gateway`},help:{"v1-7glbel-6x":`Configurações de retransmissão externa para envios APNs via retransmissor. O gateway usa o retransmissor hospedado do OpenClaw por padrão, ou este retransmissor personalizado para push.test, estímulos de ativação e ativações de reconexão após uma compilação oficial pareada do iOS publicar um registro via retransmissor.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL base do retransmissor APNs do Gateway`},help:{"v1-1o8mgnq-69":`URL HTTPS base personalizada opcional para o serviço externo de retransmissão APNs usado pelas compilações oficiais do iOS da App Store. Mantenha-a alinhada com a URL de retransmissão incorporada à compilação do iOS para que o tráfego de registro e envio chegue à mesma implantação.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Tempo limite do retransmissor APNs do Gateway (ms)`},help:{"v1-a0jkb1-4z":`Tempo limite em milissegundos para solicitações de envio do gateway ao retransmissor APNs (padrão: 10000). Aumente para retransmissores ou redes mais lentos, ou diminua para encerrar mais rapidamente as tentativas de ativação malsucedidas.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Recarga da configuração`},help:{"v1-d02mvq-4w":`Política de recarga da configuração em tempo real que define como as edições são aplicadas e quando reinicializações completas são acionadas. Mantenha o comportamento híbrido para atualizações operacionais mais seguras, exceto ao depurar os mecanismos internos de recarga.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Modo de recarga da configuração`},help:{"v1-1q1etcf-3m":`Controla como as edições de configuração são aplicadas: "off" ignora edições em tempo real e "hybrid" aplica as alterações seguras sem interrupção e reinicia quando necessário.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Gateway remoto`},help:{"v1-6xv7gd-5a":`Configurações de conexão do gateway remoto para transporte direto ou via SSH quando esta instância atua como proxy para outro host de execução. Use o modo remoto apenas quando a operação distribuída entre hosts estiver configurada intencionalmente.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Cabeçalhos de autenticação de borda do Gateway remoto`},help:{"v1-jg9p7d-5o":`Cabeçalhos HTTP baseados em segredos apresentados a um proxy com reconhecimento de identidade à frente do Gateway remoto configurado. Os cabeçalhos são enviados apenas à origem exata de gateway.remote.url por WSS e nunca seguem redirecionamentos.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Senha do Gateway remoto`},help:{"v1-16jc0yx-7y":`Segredo compartilhado enviado no campo de senha para autenticar este cliente em um Gateway remoto. A configuração gateway.auth.mode do servidor seleciona o segredo configurado; tanto o campo de token quanto o de senha do cliente são aceitos. Mantenha esse segredo gerenciado externamente e evite valores em texto simples em configurações incluídas em commits.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Política de chave de host SSH do Gateway remoto`},help:{"v1-7qoxtb-49":`Política de verificação de chave de host SSH no macOS. "strict" exige uma chave de host já confiável; "openssh" delega explicitamente à configuração efetiva do OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Identidade SSH do Gateway remoto`},help:{"v1-hz2hsm-1f":`Caminho opcional do arquivo de identidade SSH (passado para ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Destino SSH do Gateway remoto`},help:{"v1-85w39w-2t":`Gateway remoto via SSH (cria um túnel da porta do Gateway para localhost). Formato: user@host ou user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Impressão digital TLS do Gateway remoto`},help:{"v1-1ri16lk-23":`Impressão digital TLS sha256 esperada para o Gateway remoto (fixe-a para evitar ataques MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token do Gateway remoto`},help:{"v1-1pb9q8w-7v":`Segredo compartilhado enviado no campo de token para autenticar este cliente em um Gateway remoto. O gateway.auth.mode do servidor seleciona o segredo configurado; tanto o campo de token quanto o de senha do cliente são aceitos. Armazene por meio de substituição de segredos/variáveis de ambiente e faça a rotação junto com as alterações de autenticação do Gateway remoto.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transporte do Gateway remoto`},help:{"v1-1acfs7m-54":`Transporte da conexão remota: "direct" usa a conectividade pela URL configurada, enquanto "ssh" cria um túnel via SSH. Use SSH quando precisar de um túnel criptografado sem expor portas remotas.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL do Gateway remoto`},help:{"v1-va7exe-1b":`URL WebSocket do Gateway remoto (ws:// ou wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Papéis de operador do Gateway`},help:{"v1-b59sc5-6w":`Papéis de operador opcionais vinculados a perfis para Gateways de equipe. Cada papel nomeado controla o acesso às sessões de outras pessoas, o isolamento em sandbox, os agentes de sessão e de execução e os escopos de operador concedidos; omitir esta seção preserva o comportamento existente dos operadores.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Papel de operador padrão`},help:{"v1-1v8add8-4u":`Papel obrigatório atribuído a perfis autenticados sem uma atribuição explícita válida sempre que papéis de operador estiverem configurados. Seu nome deve corresponder a uma definição de papel configurada.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definições de papéis de operador`},help:{"v1-uv91an-53":`Definições não vazias de papéis nomeados pelo administrador que agrupam as políticas restritivas de compartilhamento de sessões, isolamento em sandbox, acesso a agentes e escopos de operador aplicadas a perfis de usuários autenticados.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definição de função de operador`},help:{"v1-p8tfws-6q":`Uma função de operador nomeada. Cada definição deve fornecer explicitamente sua política de compartilhamento de sessões, os agentes permitidos para sessões e execuções e o limite de escopo do operador. Também pode exigir isolamento em sandbox para sessões recém-criadas e uma política de acesso de plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin de política de acesso da função de operador`},help:{"v1-1gq4q08-9n":`ID exato e opcional do plugin cuja política de acesso ao Gateway deve autorizar esta função. O acesso é negado quando o plugin está ausente, desabilitado, não é carregado ou não fornece uma autoridade vigente. IDs de plugins indisponíveis continuam sendo configurações válidas para que funções independentes da equipe e o proprietário do Gateway possam restaurar o acesso. Omitir este campo não adiciona nenhuma dependência de plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Agentes permitidos para a função de operador`},help:{"v1-fvun18-4v":`Agentes disponíveis quando esta função cria sessões ou inicia execuções: defina "*" para permitir todos os agentes, liste os IDs dos agentes para permitir apenas esses agentes ou use uma lista vazia para desativar ambas as ações.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Isolamento em sandbox da função de operador`},help:{"v1-sknx21-66":`Isolamento de execução para sessões recém-criadas: "inherit" (padrão) usa a política do agente; "required" exige permanentemente um sandbox, mesmo quando o modo sandbox do agente está desativado, e bloqueia a execução se o backend estiver indisponível.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Limite de escopos da função de operador`},help:{"v1-1selr2i-4s":`Lista fechada de escopos de operador concedidos como autoridade máxima de conexão desta função. Os escopos solicitados, pareados, concedidos por identidade e ampliados são limitados à interseção com esta lista.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Acesso a sessões da função de operador`},help:{"v1-hsoiop-45":`Permissões de compartilhamento de sessões concedidas a esta função para sessões criadas por outras pessoas autenticadas; as sessões da própria pessoa permanecem acessíveis a ela.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Acesso da função de operador a outras sessões`},help:{"v1-vf8umx-5r":`Acesso às sessões de outras pessoas: "none" as oculta, "view" permite a leitura, "suggest" permite o fluxo de sugestões e "write" permite a participação. A inclusão explícita como membro da sessão pode conceder acesso adicional.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale do Gateway`},help:{"v1-6ar9o-4x":`Configurações de integração com Tailscale para exposição via Serve/Funnel e gerenciamento do ciclo de vida na inicialização e no encerramento do Gateway. Mantenha desativado, a menos que sua implantação dependa intencionalmente do acesso de entrada via Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Modo do Tailscale do Gateway`},help:{"v1-6l2099-5a":`Modo de publicação do Tailscale: "off", "serve" ou "funnel" para formas de exposição privada ou pública. Use "serve" para acesso restrito à tailnet e "funnel" apenas quando for necessário acesso pela internet pública.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Proteção de migração de Funnel externo do Tailscale do Gateway`},help:{"v1-1mntkor-7q":`Proteção de migração obsoleta para mode='serve'. Se um Funnel externo ainda apontar para o listener padrão do Gateway, o OpenClaw mantém a exposição inalterada e avisa que apenas webhooks autenticados por plugins continuam utilizáveis até que a autenticação por senha seja configurada e o modo seja migrado para 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal do operador`},help:{"v1-18f5rgm-8b":`Terminal do operador disponibilizado para a Control UI e clientes móveis: um shell baseado em PTY no host do Gateway, restrito a sessões de operador com escopo de administrador. Ele inicia no espaço de trabalho do agente de destino e é recusado para agentes totalmente isolados em sandbox (sandbox.mode 'all'), em vez de fornecer um shell do host sem isolamento.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Tempo limite da sessão desacoplada do terminal do operador`},help:{"v1-k6qbgr-9e":`Tempo em segundos que uma sessão de terminal permanece ativa após a conexão cair (suspensão do laptop, recarregamento da página), permitindo reconexão via terminal.attach com reprodução da saída recente. Defina como 0 para encerrar as sessões assim que a conexão cair. Padrão: 300 (5 minutos). Sessões desconectadas continuam executando seus comandos, portanto reduza esse tempo em hosts compartilhados ou expostos.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Terminal do operador habilitado`},help:{"v1-1nez06v-7p":`Habilita o terminal do operador para clientes com escopo de administrador (padrão: true). Isso disponibiliza um shell no navegador ou dispositivo móvel com o ambiente do processo do Gateway; defina como false para desabilitá-lo em implantações nas quais operadores administradores não devem ter acesso a um shell do host. As alterações são aplicadas sem reiniciar o Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell do terminal do operador`},help:{"v1-19mfe6t-5i":`Executável de shell iniciado pelo terminal do operador. Deixe sem configuração para usar o shell de login do host ($SHELL no Unix, %ComSpec% no Windows) ou especifique um interpretador para garantir um ambiente consistente para o operador.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS do Gateway`},help:{"v1-1dx77dq-4z":`Configurações de certificado e chave TLS para terminação HTTPS diretamente no processo do Gateway. Use certificados explícitos em produção e evite exposição em texto simples em redes não confiáveis.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Geração automática de certificado TLS do Gateway`},help:{"v1-1ld6uiu-4w":`Gera automaticamente um par local de certificado e chave TLS quando arquivos explícitos não estão configurados. Use apenas em ambientes locais ou de desenvolvimento e substitua por certificados reais para o tráfego de produção.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Caminho da CA TLS do Gateway`},help:{"v1-andqlu-52":`Caminho opcional para o pacote de certificados de CA usado na verificação de clientes ou para atender a requisitos de cadeia de confiança personalizada na borda do Gateway. Use quando uma PKI privada ou cadeias de certificados personalizadas fizerem parte da implantação.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Caminho do certificado TLS do Gateway`},help:{"v1-1wznaof-4q":`Caminho no sistema de arquivos para o arquivo de certificado TLS usado pelo Gateway quando o TLS está habilitado. Use caminhos de certificados gerenciados e mantenha a automação de renovação alinhada com esse local.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS do Gateway habilitado`},help:{"v1-ykhwp0-4o":`Habilita a terminação TLS no ponto de escuta do Gateway para que os clientes se conectem diretamente por HTTPS/WSS. Mantenha habilitado em caso de exposição direta à internet ou em qualquer fronteira com redes não confiáveis.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Caminho da chave TLS do Gateway`},help:{"v1-15knri0-4i":`Caminho no sistema de arquivos para o arquivo de chave privada TLS usado pelo Gateway quando o TLS está habilitado. Mantenha as permissões desse arquivo de chave restritas e faça a rotação conforme sua política de segurança.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Política de exposição de ferramentas do Gateway`},help:{"v1-1ffol26-5a":`Política de permissão e bloqueio de exposição de ferramentas no nível do Gateway, que pode restringir a disponibilidade de ferramentas em tempo de execução independentemente dos perfis de agentes ou ferramentas. Use para controles emergenciais amplos e reforço de segurança em produção.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Lista de ferramentas permitidas do Gateway`},help:{"v1-163khb1-4y":`Lista explícita de ferramentas permitidas no nível do Gateway para quando você quiser disponibilizar um conjunto restrito de ferramentas em tempo de execução. Use em ambientes restritos nos quais o escopo das ferramentas deve ser rigorosamente controlado.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Lista de ferramentas bloqueadas do Gateway`},help:{"v1-1lhssnf-4o":`Lista explícita de ferramentas bloqueadas no nível do Gateway para bloquear ferramentas de risco, mesmo que políticas de níveis inferiores as permitam. Use regras de bloqueio para resposta a emergências e reforço da defesa em profundidade.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDRs de proxies confiáveis do Gateway`},help:{"v1-n5zcvf-4f":`Lista de CIDRs/IPs de proxies a montante autorizados a fornecer cabeçalhos encaminhados de identidade do cliente. Mantenha esta lista restrita para que intermediários não confiáveis não possam se passar por usuários.`}},hooks:{label:{"v1-j9ywl7-5":`Hooks`},help:{"v1-1mzh0ry-5v":`Interface de automação de webhooks de entrada para mapear eventos externos para ações de ativação ou de agentes no OpenClaw. Mantenha esta interface protegida com controles explícitos de token, sessão e agente antes de expô-la fora de redes confiáveis.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`IDs de agentes permitidos para hooks`},help:{"v1-hree88-7c":`Lista de IDs efetivos de agentes que podem ser usados como destino de solicitações e mapeamentos de hooks, incluindo o roteamento para o agente padrão quando agentId é omitido. Use esta configuração para restringir eventos de automação a agentes de serviço dedicados e reduzir o alcance do impacto caso um token de hook seja exposto.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Prefixos de chaves de sessão permitidos para hooks`},help:{"v1-b346oh-4r":`Lista de prefixos de chaves de sessão aceitos para solicitações de hooks de entrada quando chaves fornecidas pelo chamador estão habilitadas. Use prefixos restritos para impedir a injeção arbitrária de chaves de sessão.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Permitir chave de sessão na solicitação de hook`},help:{"v1-11n9ps-52":`Permite que chamadores forneçam uma chave de sessão nas solicitações de hooks quando definido como true, habilitando o roteamento controlado pelo chamador. Mantenha como false, a menos que integradores confiáveis precisem explicitamente de um agrupamento personalizado de sessões.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Chave de sessão padrão dos hooks`},help:{"v1-bzdgkn-57":`Chave de sessão alternativa usada para entregas de hooks quando uma solicitação não fornece uma pelos canais permitidos. Use uma chave estável, mas com escopo delimitado, para evitar misturar conversas de automação não relacionadas.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks ativados`},help:{"v1-1mixmjf-4n":`Ativa o endpoint de hooks e o pipeline de execução de mapeamentos para solicitações de webhook recebidas. Mantenha desativado, a menos que esteja roteando ativamente eventos externos para o Gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook do Gmail`},help:{"v1-4cibmt-4r":`Configurações de integração push do Gmail usadas para notificações do Pub/Sub e atendimento local opcional de callbacks. Sempre que possível, restrinja essa integração a contas do Gmail dedicadas à automação.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Conta do hook do Gmail`},help:{"v1-12l1h96-4v":`Identificador da conta Google usado para operações de monitoramento e assinatura do Gmail nesta integração de hook. Use uma conta de e-mail dedicada à automação para isolar as permissões operacionais.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Permitir conteúdo externo inseguro no hook do Gmail`},help:{"v1-1w3gdvs-55":`Quando ativado, permite que conteúdo externo do Gmail com sanitização reduzida seja encaminhado para processamento. Mantenha desativado para uma configuração padrão mais segura e ative apenas para fluxos de e-mail confiáveis com transformações controladas.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL de callback do hook do Gmail`},help:{"v1-19fhn6q-4z":`URL pública de callback que o Gmail ou intermediários invocam para entregar notificações a este pipeline de hooks. Mantenha essa URL protegida com validação de token e exposição restrita à rede.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Incluir corpo da mensagem no hook do Gmail`},help:{"v1-14cf1c3-52":`Quando definido como true, busca e inclui o conteúdo do corpo do e-mail para mapeamento e processamento posterior pelo agente. Mantenha false, a menos que o texto do corpo seja necessário, pois isso aumenta o tamanho e a sensibilidade dos dados enviados.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Marcador do hook do Gmail`},help:{"v1-9zpdg8-4g":`Filtro opcional por marcador do Gmail que limita quais mensagens marcadas acionam eventos do hook. Mantenha os filtros restritos para evitar sobrecarregar as automações com mensagens não relacionadas da caixa de entrada.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Máximo de bytes do corpo no hook do Gmail`},help:{"v1-2aaxx1-4b":`Número máximo de bytes dos dados do Gmail processados por evento quando includeBody está ativado. Mantenha limites conservadores para reduzir o custo e o risco de processar mensagens muito grandes.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Substituição de modelo do hook do Gmail`},help:{"v1-1var65t-59":`Substituição opcional de modelo para execuções acionadas pelo Gmail quando as automações da caixa de correio devem usar um comportamento de modelo dedicado. Deixe sem definir para herdar os padrões do agente, a menos que as tarefas da caixa de correio exijam especialização.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Token de push do hook do Gmail`},help:{"v1-h1vx01-4o":`Token secreto compartilhado exigido nos callbacks do hook de push do Gmail antes de processar as notificações. Use substituição por variável de ambiente e faça a rotação do token se os endpoints de callback estiverem expostos externamente.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Intervalo de renovação do hook do Gmail (min)`},help:{"v1-pr1z9-49":`Frequência de renovação em minutos das assinaturas de monitoramento do Gmail para evitar que expirem. Defina um intervalo menor que os prazos de expiração do provedor e monitore falhas de renovação nos logs.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Servidor local do hook do Gmail`},help:{"v1-hom4wq-54":`Bloco de configurações do servidor local de callback para receber notificações do Gmail diretamente, sem uma camada de entrada separada. Ative somente quando este processo precisar receber e tratar o tráfego de webhook por conta própria.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Endereço de vinculação do servidor de hooks do Gmail`},help:{"v1-55bieu-4d":`Endereço de vinculação do servidor HTTP local de callback do Gmail usado ao servir hooks diretamente. Restrinja ao loopback, a menos que o acesso externo seja intencionalmente necessário.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Caminho do servidor de hooks do Gmail`},help:{"v1-1jqhcw4-4h":`Caminho HTTP no servidor local de callback do Gmail em que as notificações push são aceitas. Mantenha esse caminho consistente com a configuração da assinatura para evitar a perda de eventos.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Porta do servidor de hooks do Gmail`},help:{"v1-1yku7dz-43":`Porta do servidor HTTP local de callback do Gmail quando o modo de serviço está ativado. Use uma porta dedicada para evitar conflitos com as interfaces de Gateway e de controle.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Assinatura do hook do Gmail`},help:{"v1-127h8vg-5b":`Assinatura do Pub/Sub consumida pelo Gateway para receber notificações de alterações do Gmail a partir do tópico configurado. Defina claramente quem é responsável pela assinatura para que vários consumidores não disputem eventos inesperadamente.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale do hook do Gmail`},help:{"v1-7jzidp-4l":`Bloco de configuração de exposição do Tailscale para publicar callbacks do Gmail por meio de rotas Serve/Funnel. Use modos privados da tailnet antes de habilitar qualquer caminho de entrada público.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Modo do Tailscale do hook do Gmail`},help:{"v1-vhm395-4u":`Modo de exposição do Tailscale para callbacks do Gmail: "off", "serve" ou "funnel". Use "serve" para entrega privada pela tailnet e "funnel" somente quando for necessário receber tráfego da internet pública.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Caminho do Tailscale para o hook do Gmail`},help:{"v1-fr8qi-4m":`Caminho publicado pelo Tailscale Serve/Funnel para encaminhar callbacks do Gmail quando habilitado. Mantenha-o alinhado à configuração do webhook do Gmail para que as solicitações cheguem ao manipulador esperado.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Destino do Tailscale para o hook do Gmail`},help:{"v1-1twwxge-47":`Destino do serviço local para o qual o Tailscale Serve/Funnel encaminha o tráfego (por exemplo, http://127.0.0.1:8787). Use destinos de loopback explícitos para evitar roteamento ambíguo.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Substituição do nível de raciocínio do hook do Gmail`},help:{"v1-17owk9q-4z":`Substituição do esforço de raciocínio para execuções do agente acionadas pelo Gmail: "off", "minimal", "low", "medium" ou "high". Mantenha valores padrão moderados para automações rotineiras da caixa de entrada a fim de controlar custos e latência.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Tópico do Pub/Sub para o hook do Gmail`},help:{"v1-iled0e-4p":`Nome do tópico do Google Pub/Sub usado pelo monitoramento do Gmail para publicar notificações de alterações nesta conta. Certifique-se de que o IAM do tópico conceda ao Gmail permissão de publicação antes de habilitar o monitoramento.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hooks internos`},help:{"v1-piq9k-4v":`Configurações de execução de hooks internos para manipuladores de eventos integrados ou personalizados carregados a partir de caminhos de módulos. Use estas configurações para automações confiáveis dentro do processo e mantenha o carregamento dos manipuladores com escopo estritamente limitado.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Hooks internos habilitados`},help:{"v1-1wv0289-4c":`Habilita o processamento de hooks internos e de entradas configuradas no ambiente de execução de hooks internos. Mantenha desabilitado, a menos que os hooks internos sejam configurados intencionalmente.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Entradas de hooks internos`},help:{"v1-1ovi38l-4o":`Registros de entradas de hooks internos configurados, usados para registrar implementações de manipuladores e metadados no ambiente de execução. Mantenha as entradas explícitas e versionadas para que o comportamento em produção seja auditável.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Carregador de hooks internos`},help:{"v1-11re5ph-4p":`Configurações do carregador de hooks internos que controlam onde os módulos de manipuladores são encontrados na inicialização. Restrinja os diretórios raiz de carregamento para reduzir conflitos ou sombreamento acidental de módulos.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Diretórios adicionais de hooks internos`},help:{"v1-1xfdqxg-4c":`Diretórios adicionais em que são procurados módulos de hooks internos, além dos caminhos de carregamento padrão. Mantenha essa lista mínima e controlada para reduzir o sombreamento acidental de módulos.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Mapeamentos de hooks`},help:{"v1-frhp3v-5i":`Regras de mapeamento ordenadas que identificam solicitações de hooks recebidas e escolhem ações de ativação ou de agente, com roteamento de entrega opcional. Coloque os mapeamentos específicos primeiro para evitar que regras com padrões amplos capturem tudo.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Ação do mapeamento de hook`},help:{"v1-1r5zt5f-5f":`Tipo de ação do mapeamento: "wake" aciona o fluxo de ativação do agente, enquanto "agent" encaminha diretamente para processamento pelo agente. Use "agent" para execução imediata e "wake" quando preferir o processamento acionado por pulsos periódicos.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID do agente do mapeamento de hook`},help:{"v1-l0uioz-4y":`ID do agente de destino para a execução do mapeamento quando o roteamento de ações não deve usar os padrões. Use agentes de automação dedicados para isolar o comportamento do webhook das sessões interativas do operador.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Permitir conteúdo externo inseguro no mapeamento de hooks`},help:{"v1-1np9426-57":`Quando definido como true, o conteúdo do mapeamento pode incluir dados externos do payload com menor nível de sanitização nas mensagens geradas. Mantenha false por padrão e habilite apenas para fontes confiáveis com lógica de transformação revisada.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Canal de entrega do mapeamento de hooks`},help:{"v1-oz7pu5-5s":`Substituição do canal de entrega para as saídas do mapeamento (por exemplo, "last", "telegram", "discord", "slack", "signal", "imessage" ou "msteams"). Mantenha as substituições de canal explícitas para evitar envios acidentais entre canais.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Entregar resposta do mapeamento de hooks`},help:{"v1-12tbbam-5o":`Controla se os resultados da execução do mapeamento são enviados de volta a um destino de canal ou processados silenciosamente. Desabilite a entrega para automações em segundo plano que não devem publicar conteúdo visível ao usuário.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Chave de distribuição do mapeamento de hooks`},help:{"v1-1d593op-7e":`Chave do array no nível superior do payload sobre o qual o mapeamento distribui as ações: cada elemento dispara sua própria ação, e os modelos ou as transformações recebem um payload cujo array contém apenas o elemento atual. A predefinição do Gmail usa forEach: messages para que notificações push em lote disparem uma execução por e-mail.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID do mapeamento de hooks`},help:{"v1-q1t4zw-57":`Identificador estável opcional para uma entrada de mapeamento de hook, usado em auditoria, solução de problemas e atualizações direcionadas. Use IDs exclusivos para que logs e diferenças de configuração possam referenciar mapeamentos sem ambiguidade.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Correspondência do mapeamento de hook`},help:{"v1-6u73k2-5a":`Objeto que agrupa predicados de correspondência do mapeamento, como caminho e origem, antes de aplicar o roteamento de ações. Mantenha os critérios de correspondência específicos para que o tráfego de webhooks não relacionado não acione automações.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Caminho de correspondência do mapeamento de hook`},help:{"v1-1d7dc5j-4k":`Condição de correspondência de caminho para um mapeamento de hook, geralmente comparada com o caminho da solicitação recebida. Use esta opção para separar o comportamento da automação por famílias de caminhos de endpoints de webhook.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Origem de correspondência do mapeamento de hook`},help:{"v1-177zgy7-52":`Condição de correspondência de origem para um mapeamento de hook, normalmente definida por metadados confiáveis de sistemas anteriores ou pela lógica do adaptador. Use identificadores de origem estáveis para que o roteamento permaneça determinístico entre novas tentativas.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Modelo de mensagem do mapeamento de hook`},help:{"v1-ggqszl-5c":`Modelo para transformar a entrada estruturada do mapeamento no conteúdo final da mensagem enviada ao caminho da ação de destino. Mantenha os modelos determinísticos para que a análise e o comportamento nas etapas seguintes permaneçam estáveis.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Substituição de modelo do mapeamento de hook`},help:{"v1-10qyo4j-5e":`Substituição opcional do modelo para execuções acionadas por mapeamentos quando a automação deve usar um modelo diferente do padrão do agente. Use com moderação para manter o comportamento previsível entre as execuções de mapeamentos.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nome do mapeamento de hook`},help:{"v1-zrd9tn-4v":`Nome de exibição legível do mapeamento, usado em diagnósticos e interfaces de configuração voltadas a operadores. Use nomes concisos e descritivos para que a intenção do roteamento fique clara durante a análise de incidentes.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Chave de sessão do mapeamento de hook`},help:{"v1-lfnt1n-58":`Substituição explícita da chave de sessão para mensagens entregues pelo mapeamento, a fim de controlar a continuidade da conversa. Use chaves estáveis com escopo definido para correlacionar eventos repetidos sem interferir em conversas não relacionadas.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Modo de sessão do mapeamento de hook`},help:{"v1-1ggtdze-5k":`Controla a continuidade da sessão do mapeamento: "isolated" inicia uma nova sessão de execução, enquanto "persistent" reutiliza a sessionKey resolvida. Mantenha "isolated", a menos que a integração precise intencionalmente de contexto duradouro.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Modelo de texto do mapeamento de hook`},help:{"v1-1rg732b-4y":`Modelo alternativo somente de texto, usado quando a renderização de conteúdo enriquecido não é desejada ou não é compatível. Use-o para fornecer um resumo conciso e consistente às interfaces de entrega de chat.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Substituição do raciocínio do mapeamento de hook`},help:{"v1-17hq8me-57":`Substituição opcional do esforço de raciocínio para execuções acionadas por mapeamentos, permitindo equilibrar a latência e a profundidade do raciocínio. Mantenha o esforço baixo ou mínimo para hooks de alto volume, a menos que um raciocínio mais profundo seja claramente necessário.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Tempo limite do mapeamento de hook (s)`},help:{"v1-1r44ox2-4i":`Tempo máximo permitido para a execução da ação do mapeamento antes que o tratamento de tempo limite seja aplicado. Use limites mais curtos para fontes de webhook de alto volume para evitar acúmulos na fila.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Destino de entrega do mapeamento de hook`},help:{"v1-1p7928e-55":`Identificador de destino no canal selecionado quando as respostas do mapeamento devem ser encaminhadas a um destino fixo. Verifique os formatos de destino específicos do provedor antes de habilitar mapeamentos em produção.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformação do mapeamento de hook`},help:{"v1-14igxpm-5m":`Bloco de configuração de transformação que define o pré-processamento por módulo/exportação antes do tratamento da ação do mapeamento. Use transformações apenas de caminhos de código revisados e mantenha o comportamento determinístico para uma automação reproduzível.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Exportação da transformação de hook`},help:{"v1-atn8v-4b":`Exportação nomeada a ser invocada no módulo de transformação; quando omitida, usa a exportação padrão do módulo. Defina esta opção quando um arquivo contiver vários manipuladores de transformação.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Módulo de transformação de hook`},help:{"v1-56futq-4v":`Caminho relativo do módulo de transformação carregado de hooks.transformsDir para reescrever os payloads recebidos antes da entrega. Mantenha os módulos locais, revisados e livres de padrões de travessia de diretórios.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Modo de ativação do mapeamento de hooks`},help:{"v1-1dzqfnw-59":`Modo de agendamento da ativação: "now" ativa imediatamente, enquanto "next-heartbeat" adia até o próximo ciclo de heartbeat. Use o modo adiado para automações de menor prioridade que tolerem um pequeno atraso.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Caminho do endpoint de hooks`},help:{"v1-1l9ijzv-4u":"Caminho HTTP usado pelo endpoint de hooks (por exemplo, `/hooks`) no servidor de controle do Gateway. Use um caminho difícil de adivinhar e combine-o com a validação de token para uma defesa em profundidade."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Predefinições de hooks`},help:{"v1-dp8m0l-4v":`Conjuntos nomeados de predefinições de hooks aplicados no carregamento para estabelecer mapeamentos e comportamentos padrão. Mantenha o uso de predefinições explícito para que os operadores possam auditar quais automações estão ativas.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token de autenticação de hooks`},help:{"v1-1ihf6mv-82":`Token bearer compartilhado verificado na entrada de hooks para autenticar solicitações antes da execução dos mapeamentos. Trate os detentores como solicitantes de confiança total para a interface de entrada de hooks, e não como um papel separado de não proprietário. Use substituição por variáveis de ambiente e faça a rotação regularmente quando os endpoints de webhook estiverem acessíveis pela internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Diretório de transformações de hooks`},help:{"v1-1ayj9p0-4t":`Diretório base dos módulos de transformação de hooks referenciados pelos caminhos transform.module dos mapeamentos. Use um diretório de repositório controlado para que as importações dinâmicas permaneçam passíveis de revisão e previsíveis.`}},logging:{label:{"v1-rq08xq-7":`Registro de logs`},help:{"v1-11an9pb-5e":`Controles do comportamento de registro para severidade, destinos de saída, formatação e ocultação de dados sensíveis. Mantenha os níveis e a ocultação rigorosos o suficiente para produção, preservando diagnósticos úteis.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Registro de auditoria`},help:{"v1-1lauvy2-6w":`Histórico de auditoria limitado, contendo apenas metadados, para análise pelo operador. Os registros de execuções e ferramentas são habilitados por padrão; os metadados do ciclo de vida das mensagens exigem uma ativação separada e têm implicações de privacidade. A gravação em segundo plano é feita na medida do possível, e não constitui um arquivo de conformidade sem perdas.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Registro de auditoria habilitado`},help:{"v1-snknxb-4v":`Registra novos eventos de auditoria de execução, ferramenta e mensagens habilitadas. Padrão: true. As alterações são aplicadas imediatamente; as gravações aceitas são concluídas e os registros retidos permanecem disponíveis para consulta até expirarem.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Auditoria de identidade de execução`},help:{"v1-1ucirwv-5b":`Retém dados limitados de atribuição de identidade de execução para inspeção de execuções específicas. Padrão: false. Requer logging.audit.enabled e se aplica às novas execuções admitidas; os contextos existentes permanecem inalterados.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Escopo da auditoria de mensagens`},help:{"v1-1yg4lc3-76":`Controla os registros do ciclo de vida das mensagens, sem incluir seu conteúdo: "off" (padrão), "direct" apenas para conversas diretas conhecidas ou "all" para conversas diretas, em grupo, em canal e de tipo desconhecido. Requer logging.audit.enabled. As alterações se aplicam aos eventos subsequentes do ciclo de vida.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Nível de log do console`},help:{"v1-16badbd-5u":`Nível mínimo de log específico do console: "silent", "fatal", "error", "warn", "info", "debug" ou "trace" para controlar a saída do terminal. Use esta opção para reduzir a saída no console local e manter logs mais detalhados em arquivo, se necessário.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Estilo de log do console`},help:{"v1-d7u0iq-3q":`Estilo de formatação da saída do console: "pretty" ou "json". Use json em pipelines de processamento automatizado e pretty em fluxos de trabalho no terminal voltados à leitura humana.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Caminho do arquivo de log`},help:{"v1-16gaitv-4w":`Caminho de arquivo opcional para persistir a saída de log, além dos logs do console ou em substituição a eles. Use um caminho gerenciado com permissão de gravação e alinhe a retenção e a rotação à sua política operacional.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Nível de log`},help:{"v1-1r5yku0-5o":`Nível mínimo principal para a saída de logs em tempo de execução: "silent", "fatal", "error", "warn", "info", "debug" ou "trace". Mantenha "info" ou "warn" em produção e use debug/trace apenas durante investigações.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Padrões personalizados de ocultação`},help:{"v1-1esa6eg-7k":`Strings de expressões regulares personalizadas substituem a lista padrão de strings para a saída de logs/transcrições e complementam as regras de limite de segurança da interface, das ferramentas e dos diagnósticos. As proteções integradas para corpos de formulários, autenticação estruturada e chaves AWS isoladas sempre se aplicam. Use esta opção para mascarar tokens e identificadores específicos da implantação.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Definições globais de servidores MCP gerenciadas pelo OpenClaw. O OpenClaw incorporado e outros adaptadores de ambiente de execução podem usar esses servidores sem armazená-los nas configurações de projeto pertencentes ao ambiente de execução.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Aplicativos MCP`},help:{"v1-amyd91-38":`Suporte à interface do MCP Apps. Quando ativado, os servidores MCP configurados podem fornecer visualizações HTML interativas para os resultados de suas ferramentas.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps ativado`},help:{"v1-ghqy98-3w":`Renderização do MCP Apps e ponte entre aplicativo e servidor com ativação opcional. Mantenha desativado, a menos que você confie nos servidores MCP configurados que fornecem recursos de interface de aplicativos.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Origem do sandbox do MCP Apps`},help:{"v1-1sxv3mf-6v":`Origem HTTP(S) pública dedicada opcional para o MCP Apps. Use-a atrás de um proxy reverso ou terminador TLS e encaminhe o tráfego apenas para a porta configurada do sandbox do MCP Apps. Ela deve ser diferente da origem da Control UI e não deve servir conteúdo autenticado.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Porta do sandbox do MCP Apps`},help:{"v1-1b8n71l-4p":`Porta de escuta dedicada do sandbox do MCP Apps. Por padrão, usa a porta do Gateway mais um. Defina uma porta não utilizada quando outro serviço local ou perfil do Gateway já estiver usando essa porta.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Servidores MCP`},help:{"v1-157ozoz-42":`Definições nomeadas de servidores MCP. O OpenClaw as armazena em sua própria configuração, e os adaptadores de execução decidem quais transportes são compatíveis no momento da execução.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autenticação do servidor MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Certificado do cliente MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Chave do cliente MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Certificado do cliente MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Chave do cliente MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Projeção MCP do Codex`},help:{"v1-slcmq1-6x":`Metadados de projeção do OpenClaw apenas para threads do app-server do Codex. Não afeta sessões ACP nem a configuração genérica do harness do Codex. Omita este bloco para manter o servidor disponível para todos os agentes do app-server do Codex com o comportamento padrão de aprovação MCP do Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agentes MCP do Codex`},help:{"v1-8q98n8-67":`IDs opcionais e não vazios de agentes do OpenClaw que devem receber este servidor MCP na configuração de threads do app-server do Codex. Listas vazias, em branco ou inválidas bloqueiam o acesso por segurança; quando omitidas, o servidor é projetado para todos os agentes do app-server do Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Aprovação de ferramentas MCP do Codex`},help:{"v1-1xql0qr-3d":`Grafia nativa do Codex para o mesmo modo de aprovação de ferramentas MCP por servidor. Prefira defaultToolsApprovalMode na configuração do OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Aprovação de ferramentas MCP do Codex`},help:{"v1-y5vsqq-3s":`Modo opcional de aprovação de ferramentas MCP do Codex para este servidor: "auto", "prompt" ou "approve". Use apenas para servidores MCP nos quais você confia intencionalmente.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Tempo limite de conexão MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Servidor MCP ativado`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth do MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Perfil de autenticação OAuth do MCP`},help:{"v1-fcrb4u-5z":`ID do perfil de autenticação com suporte à renovação usado para injetar o token bearer atual neste servidor MCP remoto. Quando definido, o OpenClaw resolve e renova o perfil em tempo de execução e não repassa os dados de renovação aos componentes subsequentes.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL de metadados do cliente OAuth do MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Identidade OAuth do MCP`},help:{"v1-1ie6ys7-59":`Titularidade das credenciais OAuth deste servidor. Omita este campo ou use "shared" para credenciais gerenciadas pelo operador; use "per-requester" para permitir que cada remetente autenticado conecte sua própria conta.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL de redirecionamento OAuth do MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Escopo OAuth do MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Tempo limite de solicitação MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Verificação TLS do MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Verificação TLS do MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Chamadas paralelas de ferramentas MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Chamadas paralelas de ferramentas MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Seleção de ferramentas MCP`},help:{"v1-10poyzb-4v":`Seleção de ferramentas MCP por servidor. Use include para expor apenas os nomes de ferramentas MCP selecionados, ou exclude para ocultar os nomes de ferramentas MCP selecionados. As entradas aceitam nomes exatos e padrões glob simples com '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Ferramentas MCP excluídas`},help:{"v1-ijrc5y-1u":`Nomes exatos de ferramentas MCP ou padrões glob simples com '*' para ocultar ferramentas deste servidor.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Ferramentas MCP incluídas`},help:{"v1-89fdfq-3o":`Nomes exatos de ferramentas MCP ou padrões glob simples com '*' para disponibilizar ferramentas deste servidor. Quando omitido, todas as ferramentas do servidor permanecem elegíveis, a menos que sejam excluídas.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL de inatividade da sessão MCP (ms)`},help:{"v1-j9si74-87":`Remoção opcional por inatividade dos ambientes de execução MCP das sessões do OpenClaw, em milissegundos. Se não definido ou definido como 0, mantém os ambientes ativos até a limpeza da sessão ou o desligamento do Gateway. Valores positivos são arredondados para baixo; concessões ativas e aquisições pendentes impedem a remoção. Ambientes vinculados a uma execução ainda são encerrados quando sua execução única termina.`}},memory:{label:{"v1-oopaku-6":`Memória`},help:{"v1-1wlx40m-13":`Configuração da memória integrada (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Modo de citações da memória`},help:{"v1-1q6dxr5-4u":`Controla a visibilidade das citações nas respostas: "auto" mostra citações quando úteis, "on" sempre as mostra e "off" as oculta. Mantenha "auto" como padrão para equilibrar informações úteis e ruído.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Busca na memória`},help:{"v1-1ukbud1-25":`Busca vetorial em MEMORY.md e memory/*.md (permite configurações específicas por agente).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Cache de embeddings da busca na memória`},help:{"v1-d8h2e4-5b":`Armazena em cache no SQLite os embeddings calculados dos trechos para acelerar a reindexação e as atualizações incrementais (padrão: true). Mantenha esta opção ativada, a menos que esteja investigando a integridade do cache ou minimizando o uso de disco.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Tipo de entrada de documento da busca na memória`},help:{"v1-1ui33sv-5f":"Valor opcional de `input_type`, específico do provedor, para embeddings de memória usados em documentos e indexação. Use com endpoints de embeddings assimétricos compatíveis com OpenAI que exigem um rótulo de passagem ou documento."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Ativar busca na memória`},help:{"v1-14f11b9-4t":`Controle principal da indexação e da recuperação da busca na memória neste perfil de agente. Mantenha ativado para recuperação semântica e desative quando quiser respostas totalmente sem estado.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Índice de sessões da busca na memória (experimental)`},help:{"v1-qvhv8z-3i":`Indexa transcrições de sessões na busca na memória. Mantenha esta substituição avançada quando a herança das configurações de recuperação na raiz e por agente for diferente.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Caminhos adicionais de memória`},help:{"v1-ojqokq-7i":`Adiciona diretórios ou arquivos .md extras ao índice de memória, além dos arquivos de memória padrão. As entradas podem ser strings de caminho ou objetos com um padrão glob relativo à raiz. Quando a memória multimodal está ativada, os arquivos de imagem/áudio correspondentes nesses caminhos também podem ser indexados.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Caminho adicional de memória`},help:{"v1-b9mbq8-3m":`Define o diretório ou arquivo adicional de memória. Caminhos relativos são resolvidos a partir do espaço de trabalho do agente; entradas que apontam diretamente para arquivos são indexadas exatamente como especificadas.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Padrão de caminho adicional de memória`},help:{"v1-j8br1v-4e":`Limita uma entrada de diretório aos arquivos compatíveis que correspondem a este glob relativo à raiz, por exemplo, "runbooks/**/*.md". Omita para examinar recursivamente todos os arquivos compatíveis.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Alternativa para busca na memória`},help:{"v1-1r6368w-6p":`Provedor de reserva usado quando os embeddings primários falham: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" ou "none". Defina uma alternativa real para garantir a confiabilidade em produção; use "none" apenas se preferir falhas explícitas.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Tipo de entrada da busca na memória`},help:{"v1-26vbwe-5u":"Use este valor opcional de `input_type`, específico do provedor, apenas quando o mesmo rótulo deva ser aplicado às solicitações de embeddings tanto de consultas quanto de documentos. Para provedores assimétricos, prefira queryInputType e documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Caminho do modelo de embeddings local`},help:{"v1-13ymbnt-5q":"Especifica a origem do modelo de embeddings local para a busca local na memória, como um caminho de arquivo GGUF ou um URI `hf:`. Use esta opção apenas quando provider for `local` e verifique a compatibilidade do modelo antes de reconstruções de índices grandes."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modelo de busca na memória`},help:{"v1-11pohrl-59":`Modelo de embeddings usado no lugar do padrão pelo provedor de memória selecionado quando um modelo diferente é necessário. Defina esta opção apenas quando precisar ajustar explicitamente a qualidade da recuperação ou o custo além dos padrões do provedor.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Busca multimodal na memória`},help:{"v1-1jn02s-9e":'Configurações opcionais de memória multimodal para indexar arquivos de imagem e áudio dos caminhos adicionais configurados. Mantenha esta opção desativada, a menos que seu modelo de embeddings ofereça suporte explícito a embeddings entre modalidades, e defina `memory.search.fallback` como "none" enquanto ela estiver ativada. Os arquivos correspondentes são enviados ao provedor remoto de embeddings configurado durante a indexação.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Ativar busca multimodal na memória`},help:{"v1-1dk5d7o-7e":`Ativa a indexação de imagens e áudio na memória a partir de extraPaths. Atualmente, isso exige o Gemini embedding-2, mantém os diretórios raiz padrão da memória restritos a Markdown, desativa os provedores alternativos de busca na memória e envia o conteúdo binário correspondente ao provedor remoto de embeddings configurado.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Limite de bytes por arquivo na busca multimodal na memória`},help:{"v1-1mmdrvk-5d":`Define o tamanho máximo em bytes permitido por arquivo multimodal antes que ele seja ignorado durante a indexação da memória. Use esse limite para controlar o custo de envio e a latência da indexação, ou aumente-o para clipes de áudio curtos de alta qualidade.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalidades da busca multimodal na memória`},help:{"v1-alp4vh-4l":`Seleciona quais tipos de arquivo multimodal são indexados a partir de extraPaths: "image", "audio" ou "all". Mantenha essa seleção restrita para evitar a indexação acidental de grandes coleções de arquivos binários.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Dimensionalidade de saída da busca na memória`},help:{"v1-1f7zu53-93":`Substitui o tamanho do vetor de saída dos embeddings de memória, conforme o provedor. Os modelos Gemini aceitam de 128 a 3072 dimensões e recomendam 768, 1536 ou 3072; famílias do Bedrock, como Titan V2, Cohere V4 e Nova, disponibilizam seus próprios tamanhos permitidos. Ao alterar esse valor, espere uma reindexação completa, pois as dimensões dos vetores armazenados precisam permanecer consistentes.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Provedor de busca na memória`},help:{"v1-5evseb-71":`Seleciona o backend de embeddings usado para criar e consultar vetores de memória. O padrão é "openai"; defina "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" ou "local" quando quiser um backend diferente.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Máximo de resultados da busca na memória`},help:{"v1-13ekath-4x":`Número máximo de resultados de memória retornados pela busca antes da reclassificação posterior e da inserção no prompt. Aumente para uma recuperação mais abrangente ou reduza para prompts mais enxutos e respostas mais rápidas.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Pontuação mínima da busca na memória`},help:{"v1-1ww231l-4v":`Limite mínimo de pontuação de relevância para incluir resultados de memória na saída final da recuperação. Aumente para reduzir correspondências fracas ou com ruído, ou reduza quando precisar de uma recuperação mais permissiva.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Tipo de entrada da consulta de busca na memória`},help:{"v1-831yrv-4q":"Valor opcional de `input_type`, específico do provedor, para embeddings de memória no momento da consulta. Use com endpoints de embeddings assimétricos compatíveis com OpenAI que exigem um rótulo de consulta."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Lembrar entre conversas`},help:{"v1-k1itm8-7y":`Use contexto relevante de outras conversas privadas deste agente por meio da recuperação protegida de transcrições. Ativado por padrão somente quando session.dmScope global não está definido ou é "main" e nenhum vínculo substitui o escopo das mensagens diretas; qualquer isolamento de mensagens diretas configurado o desativa por padrão. Um valor explícito true ou false sempre prevalece.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Chave de API de embeddings remotos`},help:{"v1-nfuuu-62":`Fornece uma chave de API dedicada para chamadas remotas de embeddings usadas na indexação de memória e na geração de embeddings durante consultas. Use esta opção quando os embeddings de memória precisarem usar credenciais diferentes dos padrões globais ou das variáveis de ambiente.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL base de embeddings remotos`},help:{"v1-1ugvqgt-5p":`Substitui o endpoint da API de embeddings, por exemplo, por um proxy compatível com OpenAI ou uma URL base personalizada do Gemini. Use esta opção apenas ao rotear pelo seu próprio gateway ou endpoint do fornecedor; caso contrário, mantenha os padrões do provedor.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Embeddings remotos em lote ativados`},help:{"v1-1fehqi-5x":`Ativa as APIs de processamento em lote do provedor para tarefas de embeddings quando houver suporte (OpenAI/Gemini), aumentando a taxa de processamento em execuções de indexação maiores. Mantenha esta opção ativada, exceto ao depurar falhas no processamento em lote do provedor ou executar cargas de trabalho muito pequenas.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Cabeçalhos de embeddings remotos`},help:{"v1-1uic0kd-5i":`Adiciona cabeçalhos HTTP personalizados às solicitações remotas de embeddings, combinando-os com os padrões do provedor. Use esta opção para cabeçalhos de autenticação de proxy e de roteamento por locatário, e limite os valores ao mínimo necessário para evitar o vazamento de metadados sensíveis.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Fontes de busca na memória`},help:{"v1-btxtzg-57":`Escolhe quais fontes são indexadas: "memory" lê MEMORY.md + arquivos de memória, e "sessions" inclui o histórico de transcrições. Mantenha ["memory"], a menos que precise recuperar informações de transcrições de conversas anteriores.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Índice vetorial de busca na memória`},help:{"v1-fbybkj-37":`Controla o índice semântico sqlite-vec. Mantenha esta substituição avançada quando as políticas vetoriais da raiz e por agente forem diferentes.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Caminho da extensão vetorial da busca na memória`},help:{"v1-1hysv5q-58":"Substitui o caminho da biblioteca de extensão sqlite-vec detectado automaticamente (`.dylib`, `.so` ou `.dll`). Use esta opção quando seu ambiente de execução não conseguir encontrar sqlite-vec automaticamente ou quando você fixar uma compilação comprovadamente funcional."}},messages:{label:{"v1-1wwzqad-8":`Mensagens`},help:{"v1-i5k0iw-5k":`Infraestrutura de mensagens e padrões compartilhados entre agentes. As seções no mesmo nível da raiz controlam a infraestrutura e os padrões compartilhados entre agentes; agents.defaults controla o comportamento do ciclo do agente; as entradas de agentes podem substituir ambos, quando houver suporte.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji de reação de confirmação`},help:{"v1-1iip0zs-1x":`Reação com emoji usada para confirmar o recebimento de mensagens (vazio desativa).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Escopo da reação de confirmação`},help:{"v1-1jvdg5n-7s":`Quando enviar reações de confirmação ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" confirma o recebimento de mensagens de grupo que mencionam o agente, independentemente de o grupo exigir menções; "group-all" confirma o recebimento de todas as mensagens de grupo. "off"/"none" desativa completamente as reações de confirmação.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Regras de conversa em grupo`},help:{"v1-chqsvh-4l":`Controles de tratamento de mensagens de grupo, incluindo gatilhos de menção e dimensionamento da janela de histórico. Mantenha os padrões de menção restritos para que os canais de grupo não acionem o agente a cada mensagem.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Limite do histórico do grupo`},help:{"v1-1mkbpw-9k":`Número máximo de mensagens anteriores do grupo carregadas como contexto por turno em sessões de grupo. Use valores maiores para uma continuidade mais completa ou valores menores para respostas mais rápidas e econômicas. O histórico automático do prompt é limitado a 200 mensagens. O valor inteiro máximo do JSON seleciona a janela padrão do canal (50 para o histórico compartilhado do grupo), não uma janela ilimitada.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Padrões de menção em grupos`},help:{"v1-i7h7qc-6f":`Padrões seguros de expressões regulares, sem distinção entre maiúsculas e minúsculas, usados para detectar menções explícitas ou frases de acionamento em conversas de grupo. Use padrões precisos para reduzir falsos positivos em canais com alto volume de mensagens; padrões inválidos ou inseguros com repetições aninhadas são ignorados.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Mensagens recebidas sem menção em grupos`},help:{"v1-17wef8h-5f":`Controla como as mensagens de grupo sem menção, com monitoramento sempre ativo, são enviadas. "user_request" trata essas mensagens como uma solicitação do usuário; "room_event" as envia como contexto silencioso, no qual a saída visível exige a ferramenta de mensagens.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Respostas visíveis em grupos`},help:{"v1-qa4z1s-aa":`Substitui as respostas de origem geradas pelo modelo em conversas de grupo/canal. O padrão é "automatic" quando nenhuma política global de respostas visíveis está definida. "message_tool" exige message(action=send) para a saída normal do assistente e mídias genéricas de ferramentas; a saída em tempo de execução explicitamente sob responsabilidade do host continua podendo ser entregue, exceto para eventos de contexto da sala. "automatic" publica respostas normais como antes.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Agrupamento temporal de mensagens recebidas`},help:{"v1-ebyu5x-4a":`Configurações de agrupamento temporal de mensagens recebidas diretamente, usadas antes do início do processamento da fila ou do turno. Configure esta opção para sequências rápidas de mensagens do mesmo remetente específicas de cada provedor.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Agrupamento temporal de mensagens recebidas por canal (ms)`},help:{"v1-wbz54j-4g":`Substituições por canal do intervalo de debounce de entrada, em milissegundos, indexadas pelo ID do provedor. Use esta opção quando alguns provedores enviarem fragmentos de mensagens com mais frequência que outros.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Debounce de mensagens recebidas (ms)`},help:{"v1-1616yo2-7w":`Intervalo de espera (ms) para agrupar mensagens recebidas em rápida sequência do mesmo remetente. O Telegram usa 300ms por padrão quando não há uma substituição global nem por canal; os demais canais usam 0 por padrão. Zero desativa o agrupamento normal de mensagens em sequência, mas o Telegram ainda reagrupa os fragmentos de mensagens longas próximos ao limite.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Fila de entrada`},help:{"v1-hm2o31-48":`Estratégia de fila para mensagens recebidas durante uma execução ativa da sessão. Use esta opção para ajustar o direcionamento, os acompanhamentos adiados, o agrupamento ou a interrupção.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Modo de fila por canal`},help:{"v1-4rf8z8-54":`Substituições do modo de fila por canal, indexadas pelo ID do provedor (por exemplo, telegram, discord, slack). Use esta opção quando o padrão de tráfego de um canal exigir um comportamento diferente dos padrões globais.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Capacidade da fila`},help:{"v1-16ql8c7-4j":`Número máximo de itens recebidos mantidos na fila antes da aplicação da política de descarte. O padrão é 20; mantenha limites em canais com muito tráfego para que o uso de memória permaneça previsível.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Debounce de fallback da fila por canal (ms)`},help:{"v1-4tpyt7-4e":`Substituições de debounce por canal para o comportamento da fila, indexadas pelo ID do provedor. Use esta opção para ajustar de forma independente o tratamento de picos de mensagens em interfaces de chat com ritmos diferentes.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Estratégia de descarte da fila`},help:{"v1-ydb2rw-6m":`Estratégia de descarte quando o limite da fila é excedido. "summarize" descarta as entradas mais antigas, mas preserva resumos compactos; "old" descarta as mais antigas sem resumos; "new" rejeita o item mais recente. Use "summarize" para conversas de longa duração em que o contexto é importante.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Modo da fila`},help:{"v1-19k7gy1-67":`Modo da fila para execuções ativas. Use "steer" para inserir prompts na execução ativa, "followup" para executar depois, "collect" para agrupar mensagens compatíveis e processá-las depois, ou "interrupt" para abortar a execução ativa antes de iniciar o prompt mais recente.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefixo das respostas de saída`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Modo padrão do rodapé de uso`},help:{"v1-l3shsx-dv":`Modo padrão do rodapé de uso por resposta ("off"|"tokens"|"full"), aplicado inicialmente às sessões que não escolheram um modo via /usage. Também aceita "on" como alias legado de "tokens". Aceita um modo simples ou um mapa por canal com "default" como alternativa padrão. Precedência: valor da sessão -> entrada do canal -> default -> off; uma escolha explícita via /usage (incluindo off) é persistida e substitui o padrão. Use /usage reset (aliases: inherit, clear, default) para remover a substituição da sessão e voltar a herdar este padrão configurado.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Reações de status`},help:{"v1-193764l-3s":`Reações de status do ciclo de vida que atualizam o emoji na mensagem que acionou o agente conforme ele avança (na fila → pensando → ferramenta → concluído/erro).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Ativar reações de status`},help:{"v1-1qnmmnc-7x":`Ativa reações de status do ciclo de vida nos canais compatíveis. O Discord considera essa opção ativada quando não está definida e as reações de confirmação estão ativas; Slack, Signal, Telegram e WhatsApp exigem que ela seja true para usar reações do ciclo de vida. Por padrão, o Slack usa o status nativo da conversa do assistente para indicar o progresso.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Modelo de rodapé de uso`},help:{"v1-1xibc23-47":`Modelo personalizado de rodapé de /usage full, definido como um objeto inline ou um caminho de arquivo JSON. Se o modelo for inválido ou estiver indisponível, será usada a linha de uso padrão.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Respostas visíveis`},help:{"v1-7yfwc2-8t":`Controla as respostas de origem geradas pelo modelo em conversas diretas, em grupo e em canais. "message_tool" exige message(action=send) para a saída normal do assistente e para mídias genéricas de ferramentas; a saída de execução explicitamente pertencente ao host continua podendo ser entregue, exceto no caso de eventos ambientes da sala. "automatic" publica respostas normais como antes.`}},meta:{label:{"v1-1xpfxac-m":`Metadados de compatibilidade`},help:{"v1-1owqhgn-2w":`Metadados de compatibilidade legíveis por versões anteriores, mantidos para que binários mais antigos possam recusar reversões inseguras da configuração.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Versão da última alteração da configuração`},help:{"v1-qykpv1-1i":`Versão do OpenClaw que gravou esta configuração mais recentemente.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Marcadores de migração da configuração`},help:{"v1-burt8q-1q":`Marcadores de compatibilidade limitados para migrações de configuração concluídas.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migração da lista de permissões da política de modelos`},help:{"v1-5psop1-1z":`Registra que as restrições legadas do mapa de modelos foram preservadas ou avaliadas.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migração de separação de modelos utilitários`},help:{"v1-vzdfqx-2t":`Registra que os modelos primários implícitos legados foram preservados antes da separação da seleção de modelos utilitários.`}},models:{label:{"v1-hzmwb-6":`Modelos`},help:{"v1-1h1niol-5q":`Raiz do catálogo de modelos para definições de provedores, comportamento de mesclagem/substituição e integração opcional com a descoberta do Bedrock. Mantenha as definições de provedores explícitas e validadas antes de depender de rotas de failover em produção.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Atualização do catálogo de modelos`},help:{"v1-1hess4t-40":`Controla as atualizações em segundo plano do catálogo de modelos integrado. Entradas remotas podem atualizar os metadados dos modelos, mas não podem alterar endpoints ou cabeçalhos dos provedores.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Atualização do catálogo de modelos ativada`},help:{"v1-1fogpjj-3j":`Busca atualizações do catálogo de modelos hospedado em segundo plano (padrão: true). Defina como false para desativar todo o tráfego remoto do catálogo de modelos.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL de atualização do catálogo de modelos`},help:{"v1-e02ai2-44":`Substitui a URL do catálogo de modelos hospedado pela de um espelho HTTPS com hospedagem própria (HTTP em localhost é permitido para testes). As alterações são aplicadas após a reinicialização do Gateway.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Modo do catálogo de modelos`},help:{"v1-1ofrnsp-es":`Controla o comportamento do catálogo de provedores: "merge" mantém os provedores integrados e sobrepõe seus provedores personalizados, enquanto "replace" usa apenas os provedores configurados por você. Em "merge", IDs de provedores correspondentes preservam os valores não vazios de baseUrl no models.json do agente, enquanto os valores de apiKey são preservados apenas quando o provedor não é gerenciado por SecretRef no contexto atual de configuração/perfil de autenticação; provedores gerenciados por SecretRef atualizam apiKey a partir dos marcadores de origem atuais, e contextWindow/maxTokens de modelos correspondentes usam o maior valor entre as entradas explícitas e implícitas.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Provedores de modelos`},help:{"v1-1y5jg0v-8p":`Mapa de provedores indexado pelo ID do provedor, contendo configurações de conexão/autenticação e definições concretas de modelos. Provedores integrados podem ser ajustados com sobreposições no nível do provedor; provedores personalizados devem incluir baseUrl e models. Use chaves de provedor estáveis para que as referências de agentes e ferramentas permaneçam portáveis entre ambientes.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Ambiente de execução do provedor de modelos`},help:{"v1-1luy4fb-5o":`Política opcional de baixo nível para o ambiente de execução do agente neste provedor. Use uma política de ambiente de execução por provedor/modelo em vez de fixar um ambiente para todo o agente; se omitida ou definida como padrão, permite que o OpenClaw escolha o ambiente de execução para o provedor selecionado.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`ID do ambiente de execução do provedor de modelos`},help:{"v1-1gusd9s-69":`ID do ambiente de execução do agente do provedor: "openclaw", "auto", um ID de harness de plugin registrado, como "codex", ou um alias de backend CLI compatível, como "claude-cli". Quando omitido, o OpenAI no endpoint oficial usa o harness Codex por padrão.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adaptador de API do provedor de modelos`},help:{"v1-16c28rb-57":`Seleção do adaptador de API do provedor que controla o tratamento de compatibilidade de requisições e respostas nas chamadas de modelos. Use o adaptador correspondente ao protocolo do seu provedor de origem para evitar incompatibilidades de recursos.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Chave de API do provedor de modelos`},help:{"v1-1p84k96-54":`Credencial do provedor usada para autenticação baseada em chave de API quando o provedor exige autenticação direta por chave. Use substituição por segredos ou variáveis de ambiente e evite armazenar chaves reais em arquivos de configuração incluídos em commits.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Modo de autenticação do provedor de modelos`},help:{"v1-1l1lwxr-5p":`Seleciona o tipo de autenticação do provedor: "api-key" para autenticação por chave de API, "token" para autenticação por token bearer, "oauth" para credenciais OAuth e "aws-sdk" para resolução de credenciais AWS. Ajuste conforme os requisitos do seu provedor.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Cabeçalho Authorization do provedor de modelos`},help:{"v1-1gn3lt3-59":`Quando true, as credenciais são enviadas pelo cabeçalho HTTP Authorization, mesmo que outra forma de autenticação seja possível. Use apenas quando seu provedor ou proxy exigir explicitamente o encaminhamento de Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL base do provedor de modelos`},help:{"v1-1ku88v8-53":`URL base do endpoint do provedor usado para atender às solicitações de modelos dessa entrada de provedor. Use endpoints HTTPS e mantenha URLs específicas para cada ambiente por meio de templates de configuração, quando necessário.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Cabeçalhos do provedor de modelos`},help:{"v1-chg59u-4x":`Cabeçalhos HTTP estáticos adicionados às solicitações do provedor para roteamento por locatário, autenticação de proxy ou requisitos personalizados de gateway. Use com moderação e mantenha valores sensíveis dos cabeçalhos em segredos.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Injeção de num_ctx pelo provedor de modelos (compatibilidade com OpenAI)`},help:{"v1-53rmcr-6n":"Controla se o OpenClaw injeta `options.num_ctx` em provedores Ollama configurados com o adaptador compatível com OpenAI (`openai-completions`). O padrão é true. Defina como false apenas se o seu proxy ou serviço de destino rejeitar campos desconhecidos de `options` no payload."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Serviço local do provedor de modelos`},help:{"v1-19zkcow-4y":`Processo opcional de servidor local de modelos sob demanda para este provedor. O OpenClaw verifica healthUrl, inicia o comando quando necessário, aguarda o servidor ficar pronto e então envia a solicitação ao modelo.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argumentos do serviço local do provedor de modelos`},help:{"v1-t12wib-27":`Lista de argumentos passados ao comando do servidor local de modelos sem expansão pelo shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Comando do serviço local do provedor de modelos`},help:{"v1-1x6hz64-4j":`Caminho absoluto do executável do processo do servidor local de modelos. Mantenha esse caminho explícito para que a inicialização do provedor seja determinística e não dependa da busca no PATH pelo shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Diretório de trabalho do serviço local do provedor de modelos`},help:{"v1-fi3xlx-1h":`Diretório de trabalho do processo do servidor local de modelos.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Ambiente do serviço local do provedor de modelos`},help:{"v1-1lwb9k1-3k":`Variáveis de ambiente adicionais para o processo do servidor local de modelos. Valores que parecem ser secretos são ocultados nos instantâneos de configuração.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL de verificação de integridade do serviço local do provedor de modelos`},help:{"v1-jv7aw-35":`URL consultada para verificar a prontidão antes das solicitações ao modelo. Se omitida, o OpenClaw usa baseUrl do provedor com /models acrescentado ao final.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Parada por inatividade do serviço local do provedor de modelos`},help:{"v1-1efg054-3z":`Tempo em milissegundos para manter ativo um servidor de modelos local iniciado pelo OpenClaw após a conclusão da última solicitação. Defina como 0 para mantê-lo ativo até o OpenClaw encerrar.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Tempo limite de prontidão do serviço local do provedor de modelos`},help:{"v1-4gp0f0-2r":`Tempo máximo em milissegundos para aguardar a verificação de prontidão do servidor de modelos local após iniciar o processo.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Máximo de tokens do provedor de modelos`},help:{"v1-fnj50y-38":`Limite máximo padrão de tokens de saída aplicado aos modelos deste provedor quando a entrada do modelo não define maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Lista de modelos do provedor de modelos`},help:{"v1-1vbm0gt-63":`Lista de modelos declarados para um provedor, incluindo identificadores, metadados, parâmetros específicos do provedor e indicações opcionais de compatibilidade e custo. Mantenha os IDs exatamente iguais aos valores do catálogo do provedor para que a seleção e o uso de alternativas funcionem corretamente.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Ambiente de execução do modelo`},help:{"v1-1k70g2n-3g":`Política opcional de baixo nível para o ambiente de execução do agente neste modelo específico. A política de execução do modelo substitui a política de execução do provedor.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID do ambiente de execução do modelo`},help:{"v1-1llzv33-42":`ID do ambiente de execução do agente do modelo: "openclaw", "auto", um ID de harness de plugin registrado, como "codex", ou um alias de backend CLI compatível, como "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Entrada de mídia do modelo`},help:{"v1-wxtj8e-2x":`Metadados opcionais sobre os recursos de mídia do modelo, usados por ferramentas para escolher padrões conservadores de compressão de imagens.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Entrada de imagem do modelo`},help:{"v1-1nviirq-3c":`Limites opcionais de entrada de imagem para este modelo, como comprimento máximo do lado, número máximo de pixels e dimensão preferencial do lado para compressão.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Máximo de bytes por imagem do modelo`},help:{"v1-c2469j-23":`Tamanho máximo dos dados de imagem codificados aceito pelo provedor para este modelo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Máximo de pixels por imagem do modelo`},help:{"v1-9d6yqp-1u":`Número máximo de pixels por imagem aceito pelo provedor para este modelo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Dimensão máxima do lado da imagem do modelo`},help:{"v1-1gbci08-1y":`Largura ou altura máxima da imagem aceita pelo provedor para este modelo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Dimensão preferencial do lado da imagem do modelo`},help:{"v1-1u1mpcg-2x":`Dimensão preferencial do lado ao redimensionar imagens para uma compressão equilibrada. Deixe sem definir para usar o padrão conservador do OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Modo de contagem de tokens de imagem do modelo`},help:{"v1-1oy6z7v-1z":`Estilo de contagem de tokens de imagem do provedor: "tile", "detail" ou "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Parâmetros de execução do provedor de modelos`},help:{"v1-464sgu-4t":`Parâmetros de execução específicos do provedor, interpretados pelos plugins do provedor. Mantenha as chaves documentadas pelo provedor e prefira a documentação explícita do provedor a suposições compartilhadas feitas de forma improvisada.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Região do provedor de modelos`},help:{"v1-yq7rxk-5h":`Região opcional de implantação/API do provedor, interpretada por provedores que disponibilizam endpoints regionais. Consulte a documentação do provedor para obter os valores compatíveis; as substituições de baseUrl geralmente têm precedência quando ambos estão definidos.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Substituições de requisição do provedor de modelos`},help:{"v1-1lkxryk-87":`Substituições opcionais para requisições ao provedor de modelos, incluindo cabeçalhos extras, substituições de autenticação, roteamento por proxy, configurações de cliente TLS e a opção allowPrivateNetwork para endpoints auto-hospedados confiáveis. Use-as somente quando o serviço de destino ou o caminho de rede corporativa exigir personalização do transporte.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Permitir rede privada nas requisições ao provedor de modelos`},help:{"v1-1nbtcjk-fo":`Quando true, permite que requisições HTTP ao provedor de modelos acessem faixas de endereços privadas, CGNAT ou semelhantes por meio da proteção de fetch HTTP do provedor (fetchWithSsrFGuard). URLs base de provedores personalizados/locais já confiam na origem exata configurada, exceto em origens de metadados, link-local e NAT64 de uso local (64:ff9b:1::/48); defina como false para desativar essa confiança. O WebSocket de OpenAI Responses reutiliza request para cabeçalhos/TLS, mas não usa esse caminho de fetch com proteção contra SSRF. Use true apenas para endpoints auto-hospedados controlados pelo operador que precisem acessar origens privadas fora da origem configurada em baseUrl.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Substituição da autenticação de requisições ao provedor de modelos`},help:{"v1-ucdgnf-1w":`Substitui o comportamento de autenticação de requisições para este provedor.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nome do cabeçalho de autenticação de requisições ao provedor de modelos`},help:{"v1-1881nqr-1i":`Nome personalizado do cabeçalho de autenticação usado quando o modo de autenticação é header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Modo de autenticação de requisições ao provedor de modelos`},help:{"v1-1lhv8hs-24":`Modo de substituição da autenticação: "provider-default", "authorization-bearer" ou "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefixo do cabeçalho de autenticação de requisições ao provedor de modelos`},help:{"v1-1rbm9lz-21":`Prefixo opcional adicionado antes de request.auth.value quando o modo de autenticação é header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Token Bearer de requisições ao provedor de modelos`},help:{"v1-6rcasw-1l":`Token Bearer usado quando o modo de autenticação é authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Valor do cabeçalho de autenticação das requisições ao provedor de modelos`},help:{"v1-1v69ej-1j":`Valor personalizado do cabeçalho de autenticação usado quando o modo de autenticação é header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Cabeçalhos das requisições ao provedor de modelos`},help:{"v1-zj3orj-2i":`Cabeçalhos extras incorporados às requisições ao provedor após a atribuição padrão e a resolução da autenticação.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy das requisições ao provedor de modelos`},help:{"v1-md5uj8-4j":`Configuração opcional de proxy para substituir a padrão nas requisições ao provedor de modelos. Use "env-proxy" para respeitar as configurações de proxy do ambiente ou "explicit-proxy" para rotear por uma URL de proxy específica.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Modo de proxy das requisições ao provedor de modelos`},help:{"v1-1dx0ozg-29":`Modo de substituição do proxy nas requisições ao provedor de modelos: "env-proxy" ou "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS do proxy das requisições ao provedor de modelos`},help:{"v1-rdx62w-1v":`Configurações opcionais de TLS usadas ao conectar ao proxy configurado.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA TLS do proxy das requisições ao provedor de modelos`},help:{"v1-11pg2fd-1s":`Pacote personalizado de CAs usado para verificar a cadeia de certificados TLS do proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Certificado TLS do proxy das requisições ao provedor de modelos`},help:{"v1-x8nk2q-22":`Certificado TLS do cliente apresentado ao proxy quando o TLS mútuo é exigido.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Ignorar verificação TLS do proxy de requisições do provedor de modelos`},help:{"v1-12vjdm9-2j":`Ignora a verificação do certificado TLS do proxy. Use apenas em ambientes de desenvolvimento controlados.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Chave TLS do proxy de requisições do provedor de modelos`},help:{"v1-1skyr56-1w":`Chave privada associada a request.proxy.tls.cert para TLS mútuo com o proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Frase secreta TLS do proxy de requisições do provedor de modelos`},help:{"v1-wjvoxd-1m":`Frase secreta opcional usada para descriptografar request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nome do servidor TLS do proxy de requisições do provedor de modelos`},help:{"v1-b4oabu-22":`Substituição opcional do SNI/nome do servidor usada ao estabelecer uma conexão TLS com o proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL do proxy de requisições do provedor de modelos`},help:{"v1-kvbgou-48":`URL de proxy explícita usada quando request.proxy.mode é explicit-proxy. As credenciais incorporadas à URL são tratadas como dados sensíveis e ocultadas nos snapshots.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS de requisições do provedor de modelos`},help:{"v1-16u7v7h-2b":`Configurações opcionais de TLS usadas ao conectar diretamente ao endpoint do modelo de destino.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`CA de TLS das requisições ao provedor de modelos`},help:{"v1-ny8y3e-1v":`Pacote de certificados de CA personalizado usado para verificar a cadeia de certificados TLS do servidor de destino.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Certificado TLS das requisições ao provedor de modelos`},help:{"v1-1lltmhw-2e":`Certificado TLS do cliente apresentado ao endpoint de destino quando TLS mútuo é exigido.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Ignorar verificação TLS das requisições ao provedor de modelos`},help:{"v1-1006cuy-2m":`Ignora a verificação do certificado TLS do servidor de destino. Use apenas em ambientes de desenvolvimento controlados.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Chave TLS das requisições ao provedor de modelos`},help:{"v1-w2agir-1t":`Chave privada correspondente a request.tls.cert para TLS mútuo com o servidor de destino.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Frase secreta de TLS das requisições ao provedor de modelos`},help:{"v1-10ds42f-1g":`Frase secreta opcional usada para descriptografar request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nome do servidor TLS das requisições ao provedor de modelos`},help:{"v1-18yt7x9-1y":`Substituição opcional de SNI/nome do servidor usada ao estabelecer uma conexão TLS com o servidor de destino.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Tempo limite das requisições ao provedor de modelos`},help:{"v1-t3yn8l-ih":`Tempo limite opcional, em segundos, para solicitações de modelos por provedor. As configurações de solicitação no nível do provedor afetam as entradas de modelos explicitamente definidas para ele; elas não criam modelos implícitos. Para provedores personalizados, defina esse valor junto com baseUrl e models do provedor. Aplica-se às requisições HTTP do provedor, incluindo conexão, cabeçalhos, corpo e tratamento do cancelamento da solicitação como um todo, e também aumenta o limite do monitor de inatividade/streaming do LLM para esse provedor acima do padrão implícito de ~120s. Use essa opção para servidores de modelos locais ou auto-hospedados lentos, ou para provedores de nuvem que acumulam tokens de raciocínio sem transmitir dados (Gemini preview, Claude/Opus com grandes volumes de dados de ferramentas), em vez de alterar os tempos limite globais dos agentes.`}},nodeHost:{label:{"v1-nb8lk1-9":`Host do Nó`},help:{"v1-8recuz-4z":`Controles do host do nó para recursos expostos deste nó do Gateway a outros nós ou clientes. Mantenha os valores padrão, a menos que queira disponibilizar recursos locais por proxy na sua rede de nós.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Execuções de agentes do nó`},help:{"v1-4uz5ur-2k":`Ative turnos de agentes nativos sujeitos a aprovação neste host de nó sem interface gráfica. Desativado por padrão.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Execuções do agente Claude no nó`},help:{"v1-g8az5y-2l":`Controla se este host de nó sem interface gráfica pode anunciar ao Gateway a disponibilidade de turnos do agente Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Execuções do agente Claude no nó ativadas`},help:{"v1-1ke804l-44":`Anuncia a disponibilidade de continuação de sessões do Claude em um nó pareado quando o binário local claude está disponível (padrão: false). As execuções ainda exigem aprovação de execução no nó.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Atualizações automáticas do nó`},help:{"v1-16xjk4e-5n":`Controla as atualizações automáticas do ambiente de execução separado para hosts de nós empacotados sem interface gráfica. Verifica a cada hora e aguarda a conclusão de todas as tarefas do nó antes de reiniciar; as reinicializações automáticas ocorrem com um intervalo mínimo de 12 horas.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Atualizações automáticas do nó ativadas`},help:{"v1-1sa0yeg-7w":`Ativa atualizações automáticas estáveis ou beta para nós empacotados sem interface gráfica que permanecem em execução por longos períodos (padrão: true). Defina como false para desativar. Também são desativadas por update.checkOnStart=false ou OPENCLAW_NO_AUTO_UPDATE=1; cópias locais do código-fonte, aplicativos nativos, workers privados, dev e extended-stable não aplicam atualizações automaticamente.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Proxy de navegador do nó`},help:{"v1-2xrew7-4f":`Agrupa as configurações de proxy do navegador para expor o controle do navegador local por meio do roteamento de nós. Ative somente quando os fluxos de trabalho de nós remotos precisarem dos seus perfis de navegador locais.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Perfis permitidos no proxy de navegador do nó`},help:{"v1-1ew5dkm-8b":`Lista opcional de nomes de perfis de navegador permitidos, expostos por meio do roteamento de proxy do nó. Deixe em branco para manter o acesso completo padrão aos perfis, incluindo as rotas de criação e exclusão de perfis. Quando definida, o OpenClaw aplica o princípio do menor privilégio ao acesso aos perfis e bloqueia a criação e a exclusão de perfis persistentes pelo proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Proxy de navegador do nó ativado`},help:{"v1-pa04pd-5b":`Expõe o servidor local de controle do navegador por meio do roteamento de proxy do nó para que clientes remotos possam usar os recursos de navegador deste host. Mantenha desativado, a menos que a automação remota dependa explicitamente disso.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP do host do nó`},help:{"v1-1mdhrwl-48":`Use como ferramentas do agente os servidores MCP iniciados pelo host do nó sem interface gráfica e publicados no Gateway pareado com ele. Reinicie o host do nó após alterar esta seção.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Servidores MCP do host do nó`},help:{"v1-19m002f-3x":`Definições nomeadas de servidores MCP locais deste nó. Usa a mesma estrutura de servidor de mcp.servers; servidores OAuth não são compatíveis com o host do nó.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills do host do nó`},help:{"v1-v8txza-41":`Use esta seção para publicar as Skills instaladas em ~/.openclaw/skills a partir do host do nó sem interface gráfica. Reinicie o host do nó após alterar os arquivos das Skills.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills do host do nó ativadas`},help:{"v1-1ggpkqb-36":`Detecta e publica as skills hospedadas no nó após a conexão (padrão: true). Defina como false para desativar a publicação de skills do nó.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Execuções de workers no nó`},help:{"v1-1w83rox-2p":`Ative a hospedagem completa de sessões de workers do OpenClaw a partir de pacotes gerenciados pelo Gateway. Desativada por padrão.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Capacidade de execução de workers no nó`},help:{"v1-10nvk8f-3w":`Número máximo de sessões simultâneas de workers hospedadas neste nó (padrão: o número de núcleos de CPU disponíveis). Deve ser um número inteiro de 1 a 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Imagem de contêiner para execução de workers no nó`},help:{"v1-1oqx50o-5t":`Imagem opcional do Node 24.16+ ou 26.1+ para workers isolados em contêineres (padrão: "node:24.19.0-slim"). Use uma imagem fixada por digest, de um registro privado ou pré-carregada quando necessário; imagens ausentes são baixadas no primeiro uso.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Execuções de workers no nó ativadas`},help:{"v1-b3t0xp-2t":`Permite que este nó pareado hospede sessões a partir dos pacotes exatos instalados pelo seu Gateway (padrão: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolamento de execução de workers no nó`},help:{"v1-19i6swo-58":`Selecione o limite de isolamento de processo das sessões de workers: "none" executa diretamente no host do nó (padrão); "container" exige um mecanismo compatível com Docker em funcionamento e nunca recorre à execução no host como alternativa.`}},plugins:{label:{"v1-10renyj-7":`Plugins`},help:{"v1-1qbev2k-5c":`Controles do sistema de plugins para ativar extensões, restringir o escopo de carregamento, configurar entradas e acompanhar instalações. Mantenha a política de plugins explícita e siga o princípio do menor privilégio em ambientes de produção.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Lista de plugins permitidos`},help:{"v1-pupwbe-7z":`Lista opcional de IDs de plugins permitidos; quando definida, apenas os plugins listados podem ser carregados. Canais de chat integrados já configurados ainda podem ativar seus plugins integrados quando o canal estiver explicitamente habilitado na configuração. Use esta opção para restringir as extensões às aprovadas em ambientes controlados.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Lista de plugins bloqueados`},help:{"v1-4gyt4z-4i":`Lista opcional de IDs de plugins bloqueados, mesmo que estejam incluídos em listas de permissões ou caminhos. Use regras de bloqueio para reversões de emergência e bloqueios rigorosos de plugins que apresentem riscos.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Habilitar plugins`},help:{"v1-pnygd7-50":`Habilite ou desabilite globalmente o carregamento de plugins/extensões durante a inicialização e a recarga da configuração (padrão: true). Mantenha habilitado apenas quando sua implantação exigir recursos de extensões.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Entradas de plugins`},help:{"v1-cn74rf-54":`Configurações individuais de plugins, indexadas por ID do plugin, incluindo habilitação e dados de configuração de execução específicos de cada plugin. Use esta opção para ajustar plugins individualmente sem alterar a política global de carregamento.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Chave de API do plugin`},help:{"v1-ctytg2-53":`Campo opcional de chave de API usado por plugins que aceitam a configuração direta da chave nas configurações da entrada. Use substituição por segredos/variáveis de ambiente e evite incluir credenciais reais em arquivos de configuração versionados.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Configuração do plugin`},help:{"v1-1he672p-51":`Dados de configuração definidos pelo plugin e interpretados de acordo com seu próprio esquema e suas regras de validação. Use apenas os campos documentados pelo plugin para evitar configurações ignoradas ou inválidas.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin ativado`},help:{"v1-12soc0h-9a":`Substituição da configuração de ativação de um plugin específico, aplicada sobre a política global de plugins. No modo padrão de recarga híbrida, as alterações recarregam dinamicamente o ambiente de execução do plugin para novos turnos do agente, sem reiniciar o Gateway, a menos que o plugin exija uma reinicialização para esse caminho. Use esta opção para implantar o plugin gradualmente em diferentes ambientes.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Variáveis de ambiente do plugin`},help:{"v1-p39pu4-52":`Mapa de variáveis de ambiente por plugin, injetado apenas no contexto de execução desse plugin. Use esta opção para restringir as credenciais do provedor a um único plugin, em vez de compartilhar o ambiente global do processo.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Política de hooks do plugin`},help:{"v1-1oslnrf-4c":`Controles de política de hooks tipados por plugin para verificações de segurança impostas pelo núcleo. Use esta opção para restringir categorias de hooks de alto impacto sem desativar o plugin inteiro.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Permitir hooks de acesso à conversa`},help:{"v1-xqz31z-7e":"Controla se este plugin pode ler o conteúdo bruto da conversa por meio de hooks tipados, como `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` e `agent_end`. Plugins não incluídos na distribuição precisam habilitar esse acesso explicitamente."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Permitir hooks de injeção de prompt`},help:{"v1-7y6cny-32":"Controla se este plugin pode modificar prompts por meio de hooks tipados. Defina como false para bloquear `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Tempo limite dos hooks do plugin (ms)`},help:{"v1-4ra6b7-74":`Tempo limite padrão em milissegundos para os hooks tipados deste plugin, limitado a 600000. Quando não definido, cada hook usa o tempo limite declarado pelo plugin ou a política por hook do Gateway; não há um único padrão fixo. Os valores por hook em hooks.timeouts têm precedência.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Substituições de tempo limite dos hooks do plugin`},help:{"v1-yphl9b-5s":`Substituições de tempo limite por hook em milissegundos, indexadas pelo nome do hook tipado e limitadas a 600000. Use substituições específicas para hooks reconhecidamente lentos, como before_prompt_build ou agent_end, em vez de aumentar o tempo limite de todos os hooks.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Política de LLM do plugin`},help:{"v1-dlca6c-4j":`Controles de api.runtime.llm.complete por plugin para permissões de substituição de modelo e agente. Deixe esta opção sem definir, a menos que um plugin precise direcionar explicitamente as chamadas de geração de texto gerenciadas pelo host.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Permitir substituição de agente pelo LLM do plugin`},help:{"v1-k8c08b-4n":`Permite explicitamente que este plugin solicite api.runtime.llm.complete com um ID de agente diferente do padrão. Mantenha false, a menos que o plugin seja confiável para acessar modelos de outros agentes.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Permitir substituição do perfil de autenticação pelo LLM do plugin`},help:{"v1-9ityw9-4x":`Permite que este plugin selecione um perfil de autenticação diferente do padrão para gerações de texto isoladas no ambiente de execução do agente. Mantenha false, a menos que o plugin seja confiável para o roteamento explícito de credenciais isoladas.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Modelos de geração de texto permitidos para o LLM do plugin`},help:{"v1-1ul08he-54":`Destinos permitidos para cada conclusão de LLM do plugin como referências canônicas "provider/model", incluindo padrões resolvidos pelo host e substituições. Use "*" somente quando quiser permitir qualquer modelo.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Modelos de LLM permitidos para o plugin`},help:{"v1-154sk45-47":`Destinos de substituição permitidos para chamadas de LLM de plugins confiáveis como referências canônicas "provider/model". Use "*" somente quando quiser permitir qualquer substituição de modelo.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Permitir substituição do modelo de LLM do plugin`},help:{"v1-uw4jmc-47":`Permite explicitamente que este plugin solicite substituições de modelo em api.runtime.llm.complete. Mantenha false, a menos que o plugin seja confiável para direcionar a seleção do modelo.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Política de subagentes do plugin`},help:{"v1-wbf4m1-4d":`Controles de execução de subagentes por plugin para confiança na substituição de modelos e listas de permissões. Deixe sem definir, a menos que um plugin precise direcionar explicitamente a seleção do modelo do subagente.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Modelos permitidos para subagentes do plugin`},help:{"v1-2pvkow-42":`Destinos de substituição permitidos para execuções de subagentes de plugins confiáveis como referências canônicas "provider/model". Use "*" somente quando quiser permitir qualquer modelo.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Permitir substituição do modelo de subagentes do plugin`},help:{"v1-1r5tzm1-4g":`Permite explicitamente que este plugin solicite substituições de provedor/modelo em execuções de subagentes em segundo plano. Mantenha false, a menos que o plugin seja confiável para orientar a seleção do modelo.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Carregador de plugins`},help:{"v1-1myjwbi-52":`Grupo de configuração do carregador de plugins para especificar caminhos do sistema de arquivos onde os plugins são descobertos. Mantenha os caminhos de carregamento explícitos e revisados para evitar o carregamento acidental de extensões não confiáveis.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Caminhos de carregamento de plugins`},help:{"v1-o689p1-4z":`Arquivos ou diretórios adicionais de plugins verificados pelo carregador além dos padrões integrados. Use diretórios dedicados a extensões e evite caminhos abrangentes com conteúdo executável não relacionado.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Slots de plugins`},help:{"v1-zx6crl-5f":`Seleciona quais plugins ocupam slots exclusivos em tempo de execução, como o de memória, para que apenas um plugin forneça essa capacidade. Defina explicitamente a ocupação dos slots para evitar provedores sobrepostos com comportamentos conflitantes.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Plugin de mecanismo de contexto`},help:{"v1-4v13iw-2t":`Seleciona o plugin de mecanismo de contexto ativo pelo id para que um único plugin forneça o comportamento de orquestração de contexto.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Plugin de memória`},help:{"v1-80ngcl-23":`Selecione o plugin de memória ativo pelo id ou "none" para desativar os plugins de memória.`}},presence:{label:{"v1-10fdwo4-8":`Presença`}},proxy:{label:{"v1-ji57pa-d":`Proxy gerenciado`},help:{"v1-vui6bx-58":`Roteamento por proxy de encaminhamento gerenciado pelo operador para HTTP, HTTPS, WebSocket e caminhos de saída bruta compatíveis em tempo de execução do OpenClaw. Use quando o controle centralizado de saída fizer parte dos limites da implantação.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Proxy gerenciado habilitado`},help:{"v1-1456xdw-49":`Substituição explícita da configuração do proxy gerenciado. A presença de uma URL habilita o roteamento por padrão; defina como false para ignorar URLs de proxy configuradas ou provenientes do ambiente sem excluí-las.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Modo de loopback do proxy gerenciado`},help:{"v1-1kaiuh0-3c":`Controla o roteamento do plano de controle de loopback do Gateway enquanto o modo de proxy gerenciado está ativo: "gateway-only", "proxy" ou "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL do proxy gerenciado`},help:{"v1-p36b5l-3v":`URL do proxy de encaminhamento gerenciado. Use http:// para um proxy CONNECT sem criptografia ou https:// quando a conexão com o próprio endpoint do proxy precisar usar TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS do proxy gerenciado`},help:{"v1-6i0vu-3q":`Configurações de TLS usadas ao se conectar ao endpoint do proxy gerenciado. Essas configurações se aplicam ao TLS do proxy, não ao TLS do destino após CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Arquivo de CA do TLS do proxy gerenciado`},help:{"v1-1ntzjia-2p":`Caminho no sistema de arquivos para um pacote personalizado de certificados de CA usado para verificar o certificado de um endpoint HTTPS de proxy gerenciado.`}},secrets:{label:{"v1-1sihgpy-7":`Segredos`},help:{"v1-jgn0o9-2l":`Provedores de referências a segredos, comportamento do armazenamento compartilhado e proteção opcional do tráfego de saída de subprocessos.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proxy de saída de segredos`},help:{"v1-1qfgid-4n":`Proxy de loopback controlado pelo Gateway que substitui os marcadores sentinela de segredos do armazenamento compartilhado somente no momento da requisição de saída. Reinicie o Gateway após alterar esta seção, cujas configurações são aplicadas na inicialização.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Hosts permitidos do proxy de saída de segredos`},help:{"v1-9ypodl-6t":`Lista opcional de permissões de tráfego para solicitações e túneis CONNECT. Quando definida, os destinos devem constar nesta lista, em uma vinculação de host por segredo ou em bypassHosts. Uma lista vazia permite apenas hosts vinculados ou com bypass. Reinicie o Gateway após alterá-la.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Hosts com bypass no proxy de saída de segredos`},help:{"v1-1oiiomv-57":`Nomes de host exatos que usam túneis CONNECT autenticados sem inspeção para clientes com fixação de certificado. Os sentinelas permanecem criptografados e falharão na autenticação do fornecedor, em vez de expor texto não criptografado.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Proxy de saída de segredos ativado`},help:{"v1-u99b1i-2h":`Ativa a substituição de segredos no tráfego de saída para subprocessos de agentes hospedados no Gateway. Padrão: false.`}},session:{label:{"v1-8yh9jr-7":`Sessão`},help:{"v1-j86s32-5d":`Controles globais de roteamento, redefinição, política de entrega e manutenção de sessões para o comportamento do histórico de conversas. Mantenha os padrões, a menos que precise de restrições mais rigorosas de isolamento, retenção ou entrega.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Escopo de sessão de mensagens diretas`},help:{"v1-ql362c-5l":`Definição do escopo de sessão de mensagens diretas: "main" mantém a continuidade, enquanto "per-peer", "per-channel-peer" e "per-account-channel-peer" aumentam o isolamento. Use modos isolados para caixas de entrada compartilhadas ou implantações com várias contas.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Escopo de sessão de grupo`},help:{"v1-1fdezx2-6i":`Definição do escopo de sessão de grupos/canais: "per-group" mantém as salas separadas enquanto a sessão principal do agente as monitora em segundo plano, independentemente de dmScope; "main" incorpora o contexto das salas à sessão principal e dispensa o monitoramento. Use "main" apenas para salas confiáveis.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Vínculos de identidade de sessão`},help:{"v1-1y5jnsm-5n":`Mapeia identidades canônicas para IDs de pares com prefixo do provedor, para que usuários equivalentes sejam associados a uma única conversa de mensagem direta (exemplo: telegram:123456). Use quando a mesma pessoa aparecer em vários canais ou contas.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Chave principal da sessão`},help:{"v1-18p638h-3q":`Aceito, mas ignorado: o sufixo da sessão principal por agente é sempre "main". Omita este campo; o escopo global de sessão usa "global" em vez disso.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Manutenção de sessões`},help:{"v1-imr441-66":`Controles de manutenção automática do armazenamento de sessões para arquivamento do painel, remoção por idade, limites de entradas, retenção de arquivos de redefinição e limpeza conforme o limite de uso de disco. Comece no modo warn para observar o impacto e, depois, use enforce quando os limites estiverem ajustados.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Arquivar sessões inativas do painel após`},help:{"v1-1frdtub-5n":"Arquiva sessões inativas do painel após este período (por exemplo, `7d`), para que continuem disponíveis sem sobrecarregar a lista de sessões ativas. Defina como `false` ou `0` para desativar o arquivamento automático do painel."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Armazenamento frio de transcrições`},help:{"v1-1kp9s9h-5s":`Move transcrições inativas para arquivos JSONL compactados, mantendo os metadados da sessão. Esses arquivos passam a ser parte obrigatória do histórico e devem ser incluídos nos backups. As alterações são aplicadas sem reiniciar o Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Arquivar após dias de inatividade`},help:{"v1-zay1q3-5b":`Arquiva transcrições após esta quantidade de dias de inatividade (número inteiro positivo, padrão 30). O trabalho ativo é protegido; a alteração do limite entra em vigor no próximo ciclo do processo de manutenção, sem reiniciar o Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Arquivar transcrições antigas automaticamente`},help:{"v1-6p6vmb-5a":`Ativa o arquivamento de transcrições em segundo plano (padrão: false). Um processo verifica a cada minuto se há transcrições elegíveis. Esta política explícita de arquivamento é independente da exclusão e da limpeza por limite de uso do disco.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Meta superior de uso de disco das sessões`},help:{"v1-143vh09-7z":`Tamanho desejado após a limpeza conforme o limite de uso de disco (marca superior). O padrão é 80% de maxDiskBytes; defina explicitamente para um controle mais rigoroso da recuperação de espaço em discos com capacidade limitada. Um valor que resulte em zero usa o padrão; valores negativos são inválidos. Para desativar o limite de uso, use maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Limite máximo de uso de disco das sessões`},help:{"v1-147lxk3-cj":'Limite de uso de disco físico por agente, incluindo o arquivo principal e o WAL do SQLite e os artefatos contabilizados no diretório de sessões (por exemplo, `500mb`). O padrão é `10gb`; dados protegidos podem manter o uso acima da meta. Quando o limite é excedido, o modo "warn" informa a pressão sobre o espaço em disco, e o modo "enforce" remove artefatos antigos de redefinição/exclusão, históricos sem referência e, em seguida, arquivos criados pelo limite de entradas. Arquivos manuais, de retenção por idade, do painel, de recuperação e legados permanecem protegidos. Defina como `false`, `0` ou `"0"` para desativar.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Máximo de entradas de sessão`},help:{"v1-1w2egrh-7u":`Limita as entradas de sessão não arquivadas (padrão: 5000). Conversas persistentes excedentes elegíveis são arquivadas com seus históricos; entradas descartáveis de automação são removidas. Arquivos existentes não são contabilizados nesse limite. Entradas ativas protegidas continuam sendo contabilizadas e podem manter o armazenamento acima do limite.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Modo de manutenção de sessões`},help:{"v1-bq39hk-6v":`Determina se as políticas de remoção e de limite de uso do disco são apenas reportadas ("warn") ou aplicadas ativamente ("enforce"). Mantenha "warn" durante a implantação e mude para "enforce" após validar limites seguros. O armazenamento de longo prazo tem sua própria configuração explícita de ativação.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Preservar sessões recentes`},help:{"v1-138q5wx-89":"Protege as sessões interativas ativas dentro deste período (por exemplo, `7d`) contra a remoção automática de histórico por idade, quantidade e limite de uso de disco. Se não for definido ou estiver definido como `false`, mantém a política normal de remover primeiro os mais antigos. Registros sintéticos de execução de modelo, cron, hook, heartbeat, ACP e subagentes continuam elegíveis para limpeza limitada."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Remover sessões após`},help:{"v1-1xn50w7-76":"Arquiva conversas persistentes elegíveis e remove entradas descartáveis de automação mais antigas que esta duração (padrão: `30d`; por exemplo, `12h`). As conversas arquivadas mantêm seu histórico e podem ser restauradas; conversas protegidas ou roteáveis permanecem ativas."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Retenção de arquivos de reinicialização de sessão`},help:{"v1-16amrs1-7r":"Retenção baseada em idade para transcrições arquivadas (`*.reset.<timestamp>` e `*.deleted.<timestamp>`). Por padrão, mantém os arquivos até que o limite de espaço em disco exija sua remoção, começando pelos mais antigos; defina uma duração (por exemplo, `30d`) para ativar a exclusão por tempo decorrido, ou `false` para desativá-la explicitamente."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Notificar Home ao criar uma sessão`},help:{"v1-c4prn5-8b":`Adiciona um aviso do sistema à fila da sessão Home do agente responsável quando uma sessão é criada (padrão: true). Os avisos incluem os metadados disponíveis de título e criador e são lidos no próximo turno de Home ou heartbeat. Defina como false para desativar; rascunhos, sessões anônimas, sessões internas e execuções cron agendadas são excluídos.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Política de reinicialização de sessão`},help:{"v1-1hmt7n3-6r":`Define o objeto de política de reinicialização padrão usado quando nenhuma substituição específica por tipo ou canal se aplica. Por padrão, as sessões não são reinicializadas automaticamente; use agendamentos diários ou por inatividade para ativar esse comportamento, enquanto /new e /reset permanecem disponíveis a qualquer momento.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Hora da reinicialização diária de sessão`},help:{"v1-wry8cv-59":`Define a hora local (0-23) para o modo de reinicialização diária, para que as sessões sejam renovadas em horários previsíveis. Use com mode=daily e ajuste ao fuso horário esperado pelo operador para um comportamento fácil de entender.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minutos de inatividade para reinicialização de sessão`},help:{"v1-1kzj0id-5e":`Define o período de inatividade antes da reinicialização no modo por inatividade e também pode servir como proteção secundária no modo diário. Use valores maiores para preservar a continuidade ou menores para manter conversas mais recentes e de curta duração.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Modo de reinicialização de sessão`},help:{"v1-e5ie4w-5b":`Seleciona a estratégia de reinicialização: "none" desativa a reinicialização automática (o padrão), "daily" reinicializa em um horário configurado e "idle" reinicializa após inatividade. /new e /reset continuam disponíveis em todos os modos.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Reinicialização de sessão por canal`},help:{"v1-1uxsulx-5h":`Fornece substituições de reinicialização específicas por canal, indexadas pelo ID do provedor/canal, para um controle detalhado do comportamento. Use apenas quando um canal precisar de um comportamento de reinicialização excepcional, além das políticas por tipo.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Reinicialização de sessão por tipo de conversa`},help:{"v1-ypdr7u-52":`Substitui o comportamento de reinicialização por tipo de conversa (direta, grupo, tópico) quando os padrões não são suficientes. Use quando a atividade em grupos/tópicos exigir uma frequência de reinicialização diferente da usada para mensagens diretas.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Reinicialização de sessão (direta)`},help:{"v1-fjnlp5-56":`Define a política de reinicialização para conversas diretas e substitui a configuração base session.reset para esse tipo. Use como a substituição principal para mensagens diretas, em vez do alias legado dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Reinicialização de sessão (grupo)`},help:{"v1-hl1200-4u":`Define a política de reinicialização para sessões de conversa em grupo, nas quais a continuidade e os padrões de ruído diferem dos de mensagens diretas. Use intervalos de inatividade mais curtos para grupos movimentados se o desvio de contexto se tornar um problema.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Reinicialização de sessão (tópico)`},help:{"v1-1hgpeke-4w":`Define a política de reinicialização para sessões restritas a um tópico, incluindo fluxos de trabalho focados em tópicos de canais. Use quando as sessões de tópicos precisarem expirar mais rápido ou mais devagar do que outros tipos de conversa.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Gatilhos de reinicialização de sessão`},help:{"v1-rcabsw-5a":`Lista os gatilhos de mensagem que forçam a reinicialização de uma sessão quando encontrados no conteúdo recebido. Use com moderação para frases explícitas de reinicialização, para que o contexto não seja descartado inesperadamente durante uma conversa normal.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Escopo da sessão`},help:{"v1-axt4ds-5z":`Define a estratégia básica de agrupamento de sessões: "per-sender" isola por remetente e "global" compartilha uma sessão por contexto de canal. Mantenha "per-sender" para um comportamento mais seguro com vários usuários, a menos que seja necessário compartilhar o contexto deliberadamente.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Política de envio entre sessões`},help:{"v1-17qpipb-5l":`Controla as permissões de envio entre sessões usando regras de permissão e negação avaliadas com base em channel, chatType e prefixos de chave. Use para delimitar os destinos aos quais as ferramentas de sessão podem enviar mensagens em ambientes complexos.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Ação padrão da política de envio entre sessões`},help:{"v1-15plhut-53":`Define a ação alternativa quando nenhuma regra de sendPolicy corresponde: "allow" ou "deny". Mantenha "allow" para configurações mais simples ou escolha "deny" quando precisar de regras explícitas de permissão para cada destino.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regras da política de envio entre sessões`},help:{"v1-o217za-5h":'Regras ordenadas de permissão e negação avaliadas antes da ação padrão, por exemplo, `{ action: "deny", match: { channel: "discord" } }`. Coloque as regras mais específicas primeiro para que as regras abrangentes não se sobreponham às exceções.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Ação da regra de envio entre sessões`},help:{"v1-178vm80-54":`Define a decisão da regra como "allow" ou "deny" quando os critérios de correspondência associados são atendidos. Priorize as regras de negação ao impor limites rígidos com exceções explícitas de permissão.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Correspondência da regra de envio da sessão`},help:{"v1-18qh5qg-5d":`Define condições opcionais de correspondência da regra que podem combinar restrições de channel, chatType e prefixo de chave. Mantenha as correspondências restritas para que a intenção da política permaneça clara e a depuração continue simples.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Canal da regra de envio da sessão`},help:{"v1-u5erwx-50":`Aplica a regra quando há correspondência com um ID específico de canal/provedor (por exemplo, discord, telegram, slack). Use esta opção quando um canal precisar permitir ou negar a entrega independentemente dos demais.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Tipo de conversa da regra de envio da sessão`},help:{"v1-7cv4f9-4z":`Aplica a regra quando há correspondência com o tipo de conversa (direct, group, thread), para que o comportamento varie conforme o formato da conversa. Use esta opção quando destinos de mensagens diretas e de grupo exigirem limites de segurança diferentes.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Prefixo de chave da regra de envio da sessão`},help:{"v1-ac4dee-5n":`Corresponde a um prefixo normalizado de chave de sessão após as etapas internas de normalização de chaves nos componentes que utilizam a política. Use esta opção para controles gerais por prefixo e prefira rawKeyPrefix quando for necessária a correspondência exata com a chave completa.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Prefixo de chave bruta da regra de envio da sessão`},help:{"v1-1g9w044-5e":`Corresponde ao prefixo bruto, não normalizado, da chave de sessão para aplicar a política à chave completa exata. Use quando o keyPrefix normalizado for abrangente demais e você precisar de precisão com prefixo de agente ou específica do transporte.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Modos de compartilhamento de sessões`},help:{"v1-xbh52d-5a":`Controla quais modos de colaboração os proprietários de sessões e administradores podem selecionar. Valores booleanos omitidos são considerados habilitados por padrão; defina um modo como false para removê-lo do seletor e rejeitar novas seleções.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Permitir sessões de rascunho`},help:{"v1-1lzap27-2p":`Permite a visibilidade de rascunho, que oculta sessões de operadores que não sejam proprietários nem administradores. Padrão: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Permitir sessões somente leitura`},help:{"v1-upl3nu-21":`Permite tornar as sessões somente leitura para quem não participa delas. Padrão: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Permitir sessões com sugestões`},help:{"v1-4i8owu-4g":`Permite a visibilidade de sugestões. Nesta fase, aplica a mesma política de admissão do modo somente leitura; as filas de sugestões são configuradas por um recurso posterior. Padrão: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Caminho de armazenamento de sessões`},help:{"v1-hreznz-56":`Define o caminho do arquivo de armazenamento de sessões usado para persistir os registros de sessão entre reinicializações. Use um caminho explícito apenas quando precisar de uma organização personalizada em disco, direcionamento de backups ou armazenamento em volume montado.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Vinculações de threads de sessão`},help:{"v1-zbzihu-4s":`Padrões compartilhados para criação e roteamento de sessões vinculadas a threads nos canais compatíveis. Configure os padrões globais aqui e substitua-os por canal apenas quando o comportamento for diferente.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Contexto de criação em threads`},help:{"v1-1set6nw-4c":`Contexto padrão do subagente nativo para criações vinculadas a threads. Use "fork" para iniciar a partir da transcrição do solicitante ou "isolated" para criar um subagente sem histórico. Padrão: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Vinculação a threads ativada`},help:{"v1-foomtc-3f":`Controle principal global para criação, roteamento e entrega de sessões vinculadas a threads. Desative para desabilitar a vinculação a threads globalmente.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Tempo limite de inatividade da vinculação a threads (horas)`},help:{"v1-gffnx3-3h":`Período padrão de inatividade em horas para sessões vinculadas a threads entre provedores/canais (0 desativa a expiração por inatividade). Padrão: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Duração máxima da vinculação a threads (horas)`},help:{"v1-1xfcyhw-39":`Limite máximo absoluto opcional de duração em horas para sessões vinculadas a threads entre provedores/canais (0 desativa o limite absoluto). Padrão: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Criação de sessões vinculadas a threads`},help:{"v1-1lqwbdl-46":`Permissão padrão global para criar sessões de trabalho vinculadas a threads por meio de sessions_spawn e de criações de threads ACP. Padrão: true quando as vinculações a threads estão ativadas.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Destinos permitidos de links simbólicos de habilidades`},help:{"v1-xzybiq-4t":`Diretórios raiz reais de destino confiáveis para os quais links simbólicos de Skills podem apontar quando estão fora da raiz de origem configurada. Restrinja esse escopo, por exemplo, a um diretório de Skills em um repositório adjacente.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Diretórios extras de Skills`},help:{"v1-11o7opu-53":`Diretórios raiz adicionais de Skills compartilhadas a serem examinados com a menor precedência. Use para repositórios adjacentes ou pacotes de Skills compartilhadas que devem estar disponíveis sem copiá-los para o espaço de trabalho do OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Monitorar Skills`},help:{"v1-1ckr2l5-5d":`Ativa o monitoramento do sistema de arquivos para detectar alterações nas definições de Skills, permitindo aplicar atualizações sem reiniciar todo o processo. Mantenha ativado em fluxos de desenvolvimento e desative em imagens de produção imutáveis.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Modo autônomo do Skill Workshop`},help:{"v1-1s3kgit-6j":`Controla o aprendizado em segundo plano: "off" mantém apenas o aviso de sugestão, "propose" cria propostas pendentes e "auto" aplica as propostas capturadas e executa uma revisão semanal das Skills gerenciadas pelo Workshop usando edições comuns de arquivos. Padrão: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Políticas de superfície`},help:{"v1-vgtjbs-50":`Substituições da política de mensagens por superfície, indexadas pelo ID da superfície de entrega resolvida. Use apenas quando uma superfície implantada precisar de um tratamento de respostas silenciosas mais rigoroso que o padrão do agente.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Política de resposta silenciosa da superfície`},help:{"v1-12zgc3n-60":`Substitui a política de resposta silenciosa para uma superfície de entrega resolvida. Campos não definidos herdam agents.defaults.silentReply; use IDs de superfície com escopo restrito para que comportamentos internos ou específicos de grupos não afetem outros destinos.`}},talk:{label:{"v1-15ukbjj-4":`Conversa`},help:{"v1-1gx10xa-5g":`Configurações de síntese de voz do modo Talk para identidade da voz, seleção de modelo, formato de saída e comportamento de interrupção. Use esta seção para ajustar a experiência de voz do usuário, controlando a latência e o custo.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agente do Talk`},help:{"v1-iee5l9-2b":`Agente responsável pelas sessões do Talk criadas sem uma chave de sessão explicitamente vinculada a um agente.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Modo rápido de consulta do Talk`},help:{"v1-syf3xk-2o":`Use esta opção para definir o modo rápido como true ou false na execução regular do agente por trás das consultas em tempo real do Talk.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Nível de raciocínio das consultas do Talk`},help:{"v1-1ft5njw-2o":`Use esta opção para substituir o nível de raciocínio da execução regular do agente por trás das consultas em tempo real do Talk.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Interromper ao detectar fala no Talk`},help:{"v1-8n9q4o-3l":`Se true (padrão), interrompe a fala do assistente quando o usuário começa a falar no modo Talk. Mantenha ativado para permitir a alternância de turnos na conversa.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Provedor ativo do Talk`},help:{"v1-wgnxhg-1g":`ID do provedor ativo do Talk (por exemplo, "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Configurações dos provedores do Talk`},help:{"v1-oh0yuv-30":`Configurações do Talk específicas de cada provedor, organizadas por ID do provedor. Durante a migração, prefira esta opção às chaves legadas talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Configuração do provedor do Talk`},help:{"v1-36pblg-1r":`Campos de configuração do Talk definidos pelo provedor para o ID de provedor correspondente.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Chave de API do provedor do Talk`},help:{"v1-1a1p9wp-v":`Chave de API do provedor para o modo Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk em tempo real`},help:{"v1-c2re7j-3z":`Provedor, modelo, voz, modo, transporte e estratégia de raciocínio do Talk em tempo real. Mantenha a configuração do provedor de fala/TTS em talk.provider e talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Raciocínio do Talk em tempo real`},help:{"v1-opsatw-37":`Estratégia de raciocínio do Talk: agent-consult para obter ajuda do agente mediada pelo Gateway, direct-tools para chamadas locais de ferramentas ou none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Roteamento de consultas do Talk em tempo real`},help:{"v1-10qjcvk-5f":`Encaminhamento alternativo pelo Gateway para transcrições finais do usuário quando o provedor em tempo real não chama openclaw_agent_consult. provider-direct preserva as respostas do provedor; force-agent-consult encaminha pelo OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instruções do Talk em tempo real`},help:{"v1-1jaaj84-5p":`Instruções de sistema adicionais anexadas ao prompt integrado do Talk em tempo real do OpenClaw. Use-as para definir o estilo de voz, o tom e outros comportamentos em tempo real voltados ao provedor, mantendo intactas as orientações de agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Modo do Talk em tempo real`},help:{"v1-1u2xui1-1l":`Modo de execução do Talk: realtime, stt-tts ou transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Modelo do Talk em tempo real`},help:{"v1-amou5a-27":`Substituição do ID do modelo do provedor em tempo real para sessões do Talk no navegador ou gerenciadas pelo Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Margem inicial do Talk em tempo real (ms)`},help:{"v1-1cwg07n-22":`Milissegundos de áudio retidos antes da detecção de atividade de voz em tempo real.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Provedor do Talk em tempo real`},help:{"v1-wwsmpt-1o":`ID do provedor de voz em tempo real ativo, como openai ou google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Configurações dos provedores em tempo real do Talk`},help:{"v1-ruagcu-1r":`Configurações de voz em tempo real específicas de cada provedor, indexadas pelo ID do provedor.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Configuração do provedor em tempo real do Talk`},help:{"v1-edfpxm-1u":`Configuração de voz em tempo real gerenciada pelo provedor com o ID correspondente.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Chave de API do provedor em tempo real do Talk`},help:{"v1-1fbmgpx-z":`Chave de API do provedor para o Talk em tempo real.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Esforço de raciocínio do Talk em tempo real`},help:{"v1-157xd3e-2t":`Esforço de raciocínio específico do provedor para sessões do Talk em tempo real, como minimal, low, medium ou high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Duração do silêncio do Talk em tempo real (ms)`},help:{"v1-1grnu06-1y":`Milissegundos de silêncio antes que um turno do usuário no Talk em tempo real seja confirmado.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Voz de saída do Talk em tempo real`},help:{"v1-1kgb166-2h":`Substituição do nome da voz de saída do provedor em tempo real para sessões do Talk no navegador ou gerenciadas pelo Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`ID da voz de saída do Talk em tempo real`},help:{"v1-1k8w6vk-2f":`Substituição do ID da voz de saída do provedor em tempo real para sessões do Talk no navegador ou gerenciadas pelo Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transporte do Talk em tempo real`},help:{"v1-2otjgn-2g":`Transporte de bytes/sessões do Talk: webrtc, provider-websocket, gateway-relay ou managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Limiar de VAD em tempo real do Talk`},help:{"v1-nf5l2t-2j":`Limiar de detecção de atividade de voz em tempo real, de 0 (mais sensível) a 1 (menos sensível).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Tempo limite de silêncio do Talk (ms)`},help:{"v1-1kim32f-59":`Milissegundos de silêncio do usuário antes que o modo Talk finalize e envie a transcrição atual. Deixe sem definir para manter o intervalo de pausa padrão da plataforma (700 ms no macOS e no Android, 900 ms no iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Localidade de fala do Talk`},help:{"v1-1un3x4l-4c":`Identificador de localidade BCP 47 para o reconhecimento de fala do Talk nos nós de dispositivos e para a voz do sistema iOS usada como alternativa, por exemplo, "ru-RU". Deixe sem definir para usar o padrão de cada dispositivo.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetria`},help:{"v1-1o5tru3-55":`Consentimento explícito para estatísticas anônimas de uso de recursos enviadas junto com a verificação diária de atualizações. As estatísticas de uso de recursos ficam desativadas por padrão e nunca incluem mensagens, credenciais ou identificadores.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Data e hora do consentimento para estatísticas de uso de recursos`},help:{"v1-1t051az-3t":`Registro de data e hora no formato ISO que indica quando o operador aceitou ou recusou as estatísticas anônimas de uso de recursos. Impede que o assistente de configuração pergunte novamente.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Estatísticas anônimas de uso de recursos`},help:{"v1-1ptrwuq-4r":`Compartilha os nomes dos canais e provedores habilitados, a contagem de plugins e a contagem de sessões recentes junto com a verificação diária de atualizações. Desativado por padrão e sempre desativado quando DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Ferramentas`},help:{"v1-1el54kl-5h":`Infraestrutura de ferramentas e padrões entre agentes. As configurações no mesmo nível da raiz controlam a infraestrutura e os padrões entre agentes; agents.defaults controla o comportamento do ciclo do agente; as entradas de agentes podem substituir ambos quando houver suporte.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Acesso a ferramentas entre agentes`},help:{"v1-1ynpa5f-cf":`Política para chamadas de ferramentas de sessão entre agentes: envios, listagem, histórico, pesquisa e leituras de status (padrão: habilitado). Use allow para restringir pares de agentes; enabled=false bloqueia o acesso comum entre agentes. As sessões de subagentes nativos e as sessões filhas ACP pertencentes ao solicitante continuam acessíveis com a visibilidade tree ou all. Para uma separação estrita, defina tools.sessions.visibility como agent ou self (tree ainda permite sessões filhas nativas/ACP pertencentes ao solicitante), ou use gateways separados.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Lista de destinos permitidos entre agentes`},help:{"v1-1jt2ari-76":`IDs de agentes ou padrões com * que podem participar de chamadas entre agentes; tanto o agente solicitante quanto o agente de destino devem corresponder. O acesso entre agentes é habilitado por padrão, e allow omitido ou vazio permite todos os pares. Defina uma lista explícita para restringir o acesso; entradas em branco negam o acesso.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Habilitar ferramenta entre agentes`},help:{"v1-w950oq-ba":`Habilita o acesso a ferramentas de sessão entre agentes (padrão: true); allow omitido ou vazio permite todos os pares de agentes. Defina como false para bloquear o acesso comum entre agentes; as sessões de subagentes nativos e as sessões filhas ACP pertencentes ao solicitante continuam acessíveis com a visibilidade tree ou all. Para uma separação estrita, defina tools.sessions.visibility como agent ou self (tree ainda permite sessões filhas nativas/ACP pertencentes ao solicitante), ou use gateways separados.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Lista de ferramentas permitidas`},help:{"v1-1is3eaq-4v":`Lista absoluta de ferramentas permitidas que substitui os padrões derivados do perfil em ambientes rigorosos. Use somente quando a intenção for executar um subconjunto de recursos de ferramentas selecionado com rigor.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Adições à lista de ferramentas permitidas`},help:{"v1-1xw9zp8-57":`Entradas extras na lista de ferramentas permitidas, adicionadas ao perfil de ferramentas selecionado e à política padrão. Mantenha esta lista pequena e explícita para que as auditorias possam identificar rapidamente as exceções intencionais à política.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Política de ferramentas por provedor`},help:{"v1-1ecljob-4y":`Substituições de permissões e bloqueios de ferramentas por provedor, indexadas pelo ID do canal/provedor, para adaptar os recursos a cada interface. Use quando um provedor precisar de controles mais rigorosos do que os da política global de ferramentas.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Modo de código`},help:{"v1-1ecc39k-6k":'Modo de código genérico do OpenClaw. Quando omitido globalmente, o padrão é `"auto"`; um objeto definido sem `enabled` permanece desativado. As execuções de agentes com o modo ativado expõem apenas `exec` e `wait` ao modelo e acessam as ferramentas normais por meio da ponte do catálogo.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Ativar modo de código`},help:{"v1-rgstxz-aj":'Ativação global do modo de código do OpenClaw. Se a configuração global estiver totalmente ausente, o padrão é `"auto"`; um objeto definido sem `enabled` permanece desativado. `"auto"` ativa o modo para modelos que priorizam o catálogo, enquanto `true` o ativa para execuções com suporte a ferramentas. As substituições de ativação por agente e por modelo têm precedência. Uma execução com o modo ativado é bloqueada por segurança se o ambiente de execução estiver indisponível, em vez de expor a lista completa de ferramentas.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Executor do modo de código`},help:{"v1-l8nlk2-6x":`Executor JavaScript: "node" (padrão) usa o vm do Node para código confiável e não é um ambiente isolado de segurança; "quickjs" usa o plugin QuickJS WASM incluído para execução de código convidado com segurança reforçada. As permissões de ferramentas se aplicam a ambos. Se o executor selecionado não estiver disponível, a execução será bloqueada por segurança.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Limite de saída do modo de código`},help:{"v1-1hmij9q-1n":`Número máximo de bytes serializados retornados pela saída do modo de código.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Limite de chamadas de ferramentas pendentes no modo de código`},help:{"v1-3b5tyd-2i":`Número máximo de chamadas aninhadas de ferramentas simultâneas que uma VM do modo de código pode iniciar antes de precisar retomar a execução mais tarde.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Máximo de resultados de pesquisa no modo de código`},help:{"v1-1gpue5r-28":`Número máximo de resultados de pesquisa no catálogo oculto que um programa no modo de código pode solicitar.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Limite de snapshot no modo de código`},help:{"v1-1mmgkqy-1x":`Número máximo de bytes serializados retidos para um snapshot suspenso do QuickJS.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Limite de memória no modo de código`},help:{"v1-xetora-6n":`Limite de heap do ambiente convidado QuickJS ou orçamento de heap do V8 para workers do Node, aplicado na medida do possível, em bytes. A sobrecarga do runtime do Node e as alocações mínimas do mecanismo afetam o orçamento efetivo; buffers externos e o RSS do processo são excluídos. Isso não é uma garantia de segurança.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interface do modo de código`},help:{"v1-dsp2b9-2x":'Interface voltada ao modelo. Somente "only" é compatível: expõe `exec` e `wait` do modo de código e oculta as ferramentas normais.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Resultados de pesquisa padrão no modo de código`},help:{"v1-1io42lu-2m":"Número padrão de resultados de pesquisa no catálogo oculto retornados por `catalog.search` no modo de código."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL de snapshot no modo de código`},help:{"v1-1nxfczz-28":"Por quanto tempo as execuções suspensas do Code Mode podem ser retomadas com `wait` antes de expirarem."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Tempo limite do modo de código`},help:{"v1-8csycm-1p":"Tempo máximo em milissegundos para uma chamada `exec` ou `wait` no modo de código."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Lista de ferramentas bloqueadas`},help:{"v1-wilr1b-4p":`Lista global que bloqueia as ferramentas listadas, mesmo quando as regras de perfil ou provedor as permitem. Use regras de bloqueio para bloqueios de emergência e defesa em profundidade a longo prazo.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Acesso a ferramentas com privilégios elevados`},help:{"v1-ehcm0r-5a":`Controles de acesso a ferramentas com privilégios elevados para interfaces de comandos privilegiados que devem ser acessíveis apenas a remetentes confiáveis. Mantenha desativado, a menos que os fluxos de trabalho do operador exijam explicitamente ações com privilégios elevados.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Regras de permissão para ferramentas com privilégios elevados`},help:{"v1-1u9bhih-54":`Regras de permissão de remetentes para ferramentas com privilégios elevados, geralmente indexadas por formatos de identidade do canal/provedor. Use identidades específicas e explícitas para que comandos com privilégios elevados não possam ser acionados por usuários não autorizados.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Ativar acesso a ferramentas com privilégios elevados`},help:{"v1-1n8oyal-4l":`Ativa o fluxo de execução de ferramentas com privilégios elevados quando as verificações de remetente e política são aprovadas. Mantenha desativado em canais públicos/compartilhados e ative apenas em contextos confiáveis operados pelo proprietário.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Ferramenta exec`},help:{"v1-p5piic-56":`Agrupamento de políticas da ferramenta exec para o host de execução do shell, o modo de segurança, o comportamento de aprovação e as vinculações em tempo de execução. Mantenha padrões conservadores em produção e restrinja os fluxos de execução com privilégios elevados.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Lista de modelos permitidos para apply_patch`},help:{"v1-4q5ovf-1x":`Lista opcional de IDs de modelos permitidos (por exemplo, "gpt-5.4" ou "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Ativar apply_patch`},help:{"v1-1erkir4-31":`Ative ou desative apply_patch para modelos OpenAI e OpenAI Codex quando permitido pela política de ferramentas (padrão: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch restrito ao espaço de trabalho`},help:{"v1-x2z207-3o":`Restrinja os caminhos de apply_patch ao diretório do espaço de trabalho (padrão: true). Defina como false para permitir a gravação fora do espaço de trabalho (perigoso).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Aviso de execução após aprovação de exec (ms)`},help:{"v1-1gwwann-4z":`Tempo de espera em milissegundos antes de exibir um aviso de execução em andamento após a aprovação de exec. Aumente para reduzir a oscilação visual em comandos rápidos ou diminua para informar o operador mais rapidamente.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Solicitação de aprovação de exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Realce de comandos de exec`},help:{"v1-kyxd4o-4n":`Mostre realces de comandos gerados pelo analisador nas solicitações de aprovação de exec (padrão: false). Ative esta opção para exibir o texto dos comandos com realce sem alterar a política de aprovação de exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Validade de autorizações permanentes (dias)`},help:{"v1-5uxe2j-6r":`Prazo de validade padrão, em dias (1-3650), para autorizações permanentes criadas por allow-always nas aprovações de automações. Se não definido, as autorizações permanecem válidas até serem revogadas ou até que a automação à qual pertencem seja alterada. As condições são fixadas na criação, portanto, alterar este valor afeta apenas autorizações futuras.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Destino de exec`},help:{"v1-rno1mf-5q":`Seleciona a estratégia de destino de execução para comandos shell. Use "auto" para um comportamento que se adapta ao ambiente de execução (sandbox quando disponível, caso contrário gateway), ou defina sandbox/gateway/node explicitamente quando precisar de um ambiente fixo.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Modo de execução`},help:{"v1-1wi6t4l-5q":`Seletor normalizado de política de execução. Use "auto" para casos sem aprovação revisados pelo classificador, "ask" para casos sem aprovação revisados por uma pessoa, "allowlist" apenas para comandos seguros determinísticos ou "full" para operação local confiável.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Vinculação de nó de execução`},help:{"v1-rfnz54-4s":`Configuração de vinculação de nó para ferramentas de execução quando a execução de comandos é delegada por meio de nós conectados. Use a vinculação explícita de nó apenas quando o roteamento entre vários nós for necessário.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Notificar ao encerrar a execução`},help:{"v1-1ounlvx-3q":`Quando true (padrão), o encerramento de sessões de execução em segundo plano e os eventos do ciclo de vida da execução em nós enfileiram um evento do sistema e solicitam um heartbeat.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Notificar execução bem-sucedida sem saída`},help:{"v1-1wx4xxd-3d":`Quando true, execuções em segundo plano encerradas com sucesso e sem saída ainda enfileiram um evento de conclusão do sistema (padrão: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Adicionar ao início do PATH de execução`},help:{"v1-s1aimc-1r":`Diretórios a adicionar ao início do PATH para execuções (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Revisor de execução`},help:{"v1-12y548k-4x":`Revisor de execução baseado em modelo, usado pelo modo automático antes de recorrer à aprovação humana. Configure aqui uma substituição de modelo específica quando quiser isolar a revisão de execução do modelo do agente principal.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Modo rápido do revisor de execução`},help:{"v1-175bx14-8u":`Modo rápido opcional para revisões de aprovação do OpenClaw: true solicita processamento prioritário nas rotas compatíveis do OpenAI Responses e do ChatGPT/OAuth; false solicita processamento padrão. Omita para manter os padrões do provedor. O modo rápido pode custar mais e está sujeito à disponibilidade do provedor. Não configura o Codex Guardian nativo.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modelo do revisor de execução`},help:{"v1-1lltiy5-3i":`Substituição opcional de provedor/modelo para o agente revisor de execução. Omita para reutilizar o modelo principal configurado para o agente de destino.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Raciocínio do revisor de execução`},help:{"v1-yg2gby-6u":`Nível de esforço de raciocínio opcional para revisões de aprovação do OpenClaw baseadas em modelos: minimal, low, medium, high, xhigh ou max. Omita para manter os padrões do provedor. Os níveis compatíveis são normalizados para o modelo selecionado. Não configura o Codex Guardian nativo.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Tempo limite do revisor de execução (ms)`},help:{"v1-1o30chi-3w":`Tempo limite por etapa do revisor de execução, em milissegundos, para a preparação do modelo e a conclusão da resposta antes de recorrer à aprovação humana (padrão: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Perfis de binários seguros para execução`},help:{"v1-4cdcwe-29":`Perfis opcionais de segurança por binário (limites de argumentos posicionais + opções permitidas/proibidas).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Binários seguros para execução`},help:{"v1-1of1m2s-21":`Permitir a execução de binários seguros que usam apenas stdin sem entradas explícitas na lista de permissões.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Diretórios confiáveis de binários seguros para execução`},help:{"v1-zljbcn-2v":`Diretórios adicionais explicitamente definidos como confiáveis para verificações de caminhos de binários seguros (entradas de PATH nunca são consideradas confiáveis automaticamente).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Segurança de execução`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Exigir aprovação para avaliação de código em linha`},help:{"v1-jkmgo7-5z":"Exigir aprovação explícita para formas de avaliação de código em linha por interpretadores, como `python -c`, `node -e`, `ruby -e` ou `osascript -e`. Impede a reutilização silenciosa da lista de permissões e restringe a permissão de permitir sempre para perguntar a cada vez nesses casos."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Tempo limite de execução (segundos)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Ferramentas de sistema de arquivos restritas ao espaço de trabalho`},help:{"v1-1mhuvka-2s":`Restringe as ferramentas de sistema de arquivos (read/write/edit/apply_patch) ao diretório do espaço de trabalho (padrão: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Identidade do GitHub CLI e autor do Git`},help:{"v1-1fl77im-5s":`Perfil local gerenciado do GitHub CLI e autor opcional do Git para ferramentas do agente. Omita este objeto para preservar a conta e o autor nativos do usuário que executa o Gateway; as credenciais remotas do repositório nunca são substituídas.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`E-mail do autor do Git`},help:{"v1-kol5g6-1i":`E-mail opcional do autor e do responsável pelo commit no Git, válido apenas no processo.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nome do autor do Git`},help:{"v1-z5bl1f-1h":`Nome opcional do autor e do responsável pelo commit no Git, válido apenas no processo.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Tipo de credencial do GitHub`},help:{"v1-qi3qun-3q":`Identifica um perfil OAuth gerenciado cuja credencial rotativa de renovação pertence ao Gateway. Perfis sem este campo usam um token de acesso pessoal.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Versão do perfil do GitHub`},help:{"v1-4lzl0-27":`Versão opaca gerada do perfil, usada para alternar credenciais gerenciadas de forma atômica.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Ativar compreensão de links`},help:{"v1-23t2io-59":`Ativa o pré-processamento automático de compreensão de links para que o conteúdo das URLs possa ser resumido antes do raciocínio do agente. Mantenha ativado para um contexto mais rico e desative quando for necessário limitar estritamente o processamento ao mínimo.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Máximo de links para compreensão de links`},help:{"v1-ksxmcv-52":`Número máximo de links expandidos por turno durante a compreensão de links. Use valores menores para controlar a latência e o custo em conversas movimentadas e valores maiores quando o contexto de vários links for essencial.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modelos de compreensão de links`},help:{"v1-6j3mnw-5a":`Lista de modelos preferenciais para tarefas de compreensão de links, avaliados em ordem como alternativas quando houver suporte. Use primeiro modelos leves para resumos rotineiros e modelos mais pesados apenas quando necessário.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Escopo da compreensão de links`},help:{"v1-183cwpa-55":`Controla quando a compreensão de links é executada de acordo com o contexto da conversa e o tipo de mensagem. Mantenha um escopo restrito para evitar buscas desnecessárias em mensagens cujos links não exigem ação.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Tempo limite da compreensão de links (s)`},help:{"v1-61v30o-4p":`Tempo limite em segundos para a compreensão de cada link antes que links não resolvidos sejam ignorados. Mantenha esse tempo limitado para evitar longas esperas quando sites externos estiverem lentos ou inacessíveis.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Detecção de loops de ferramentas`},help:{"v1-1e3rls8-5g":`Controla a detecção de ciclos de chamadas de ferramentas no histórico recente e a proteção após a compactação. Omita para manter a detecção no histórico recente desativada e a proteção após a compactação ativada. Defina como true para ativar ambas ou false para desativar ambas.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Política de anexos para compreensão de áudio`},help:{"v1-1s3t9s5-3o":`Escolha quais anexos de áudio correspondentes serão processados. Processe apenas o primeiro, a menos que a transcrição de vários anexos seja intencional.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Formato de eco da transcrição`},help:{"v1-glpdzh-3i":`Formate a transcrição enviada de volta com um marcador {transcript}. Mantenha o marcador intacto para que a entrega inclua a transcrição.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Enviar transcrição de volta ao chat`},help:{"v1-1dedp8c-3r":`Envie a transcrição do áudio de volta ao chat de origem antes do processamento pelo agente. Ative esta opção quando os usuários precisarem verificar o que o sistema ouviu.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Ativar compreensão de áudio`},help:{"v1-1v0x7te-2m":`Ative a compreensão de áudio para que mensagens de voz ou clipes de áudio possam ser transcritos para o contexto do agente.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Idioma da compreensão de áudio`},help:{"v1-1ruqt97-3z":`Indicação de idioma padrão para provedores de transcrição de áudio. Defina-a quando o idioma principal falado for conhecido e a detecção do provedor não for confiável.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Máximo de bytes para compreensão de áudio`},help:{"v1-1mcckc8-43":`Limite padrão de tamanho da entrada de áudio para modelos configurados e detectados automaticamente. Defina este valor de acordo com a maior gravação que seus provedores e sua rede devem aceitar.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Máximo de caracteres para compreensão de áudio`},help:{"v1-eo1dp-43":`Comprimento máximo padrão da transcrição para modelos configurados e detectados automaticamente. Use um valor menor para evitar que mensagens de voz longas ampliem o contexto do agente.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Modelo preferido para compreensão de áudio`},help:{"v1-1n5zya1-3c":`Dê preferência a uma entrada de tools.media.models marcada por capacidade para transcrição de áudio antes das demais alternativas compatíveis.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt de compreensão de áudio`},help:{"v1-1v5jtay-4b":`Prompt padrão de transcrição de áudio quando uma entrada de modelo não o substitui. Mantenha a instrução estável quando os fluxos de trabalho subsequentes dependerem do estilo da transcrição.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Escopo de compreensão de áudio`},help:{"v1-1pptfg0-3w":`Restrinja a compreensão de áudio por canal, tipo de conversa ou chave de origem. Mantenha esse escopo restrito quando a transcrição automática for sensível ou cara.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Tempo limite de compreensão de áudio (s)`},help:{"v1-n8wc6c-3b":`Tempo limite padrão para solicitações de compreensão de áudio. Aumente-o para gravações longas ou modelos locais de transcrição mais lentos.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Simultaneidade de compreensão de mídia`},help:{"v1-13kr9np-58":`Número máximo de operações simultâneas de compreensão de mídia por turno, considerando tarefas de imagem, áudio e vídeo. Reduza esse valor em implantações com recursos limitados para evitar a saturação da CPU ou da rede.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Política de anexos para compreensão de imagens`},help:{"v1-11hofbw-3e":`Escolha quais anexos de imagem correspondentes serão processados. Processe apenas o primeiro, a menos que a análise de várias imagens seja intencional.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Ativar compreensão de imagens`},help:{"v1-1b2zw34-50":`Ative a compreensão de imagens para que imagens anexadas ou referenciadas possam ser interpretadas como contexto textual. Desative se precisar operar apenas com texto ou quiser evitar custos de processamento de imagens.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Máximo de bytes para compreensão de imagens`},help:{"v1-jwwpd1-3v":`Limite padrão de tamanho das imagens de entrada para modelos configurados e detectados automaticamente. Defina este valor de acordo com os limites de payload do provedor e a largura de banda da implantação.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Máximo de caracteres para compreensão de imagens`},help:{"v1-ebnxhk-3q":`Comprimento máximo padrão da descrição de imagens. Use um valor menor para um contexto compacto ou um valor maior para OCR e análise de cenas detalhados.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Modelo preferencial para compreensão de imagens`},help:{"v1-1o2uwo6-3c":`Dê preferência a uma entrada de tools.media.models marcada com a capacidade de compreensão de imagens antes das demais alternativas compatíveis.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt de compreensão de imagens`},help:{"v1-1jdcu8b-3u":`Prompt padrão de compreensão de imagens quando uma entrada não o substitui. Mantenha-o determinístico quando os consumidores dependerem de descrições estáveis.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Escopo da compreensão de imagens`},help:{"v1-tievo1-3s":`Restrinja a compreensão de imagens por canal, tipo de conversa ou chave de origem. Mantenha este escopo restrito em canais movimentados ou não confiáveis para controlar o processamento.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Tempo limite da compreensão de imagens (s)`},help:{"v1-1wcm84x-31":`Tempo limite padrão para solicitações de compreensão de imagens. Aumente-o para imagens grandes ou modelos de visão locais mais lentos.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Modelos compartilhados de compreensão de mídia`},help:{"v1-f34u65-47":`Lista canônica de modelos de compreensão de mídia. Use tags de capacidade de imagem, áudio ou vídeo em cada entrada para que cada pipeline selecione apenas alternativas compatíveis.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Política de anexos para compreensão de vídeo`},help:{"v1-1qm1qrc-3e":`Escolha quais anexos de vídeo correspondentes serão processados. Processe apenas o primeiro, a menos que a análise de vários vídeos seja intencional.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Ativar compreensão de vídeo`},help:{"v1-1ltx5gl-58":`Ative a compreensão de vídeo para que os clipes possam ser resumidos em texto para raciocínio e respostas nas etapas seguintes. Desative quando o processamento de vídeo não for permitido pela política ou for caro demais para sua implantação.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Máximo de bytes para compreensão de vídeo`},help:{"v1-2mp77v-3v":`Limite padrão de tamanho de entrada de vídeo para modelos configurados e detectados automaticamente. Defina esse valor de acordo com os limites de carga útil do provedor e a largura de banda da implantação.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Máximo de caracteres para compreensão de vídeo`},help:{"v1-1j0x40b-3j":`Comprimento máximo padrão da descrição de vídeo. Use um valor menor para um contexto compacto ou um valor maior para resumos detalhados das cenas.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Modelo preferido de compreensão de vídeo`},help:{"v1-1cygq5k-3c":`Dê preferência a uma entrada de tools.media.models marcada com a capacidade de compreensão de vídeo antes das demais alternativas compatíveis.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt de compreensão de vídeo`},help:{"v1-ul2jx4-3r":`Prompt padrão de compreensão de vídeo quando uma entrada não o substitui. Mantenha-o determinístico quando os consumidores dependerem de resumos estáveis.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Escopo da compreensão de vídeo`},help:{"v1-7gfrx3-3s":`Restrinja a compreensão de vídeo por canal, tipo de conversa ou chave de origem. Mantenha esse escopo restrito em canais movimentados ou não confiáveis para controlar o processamento.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Tempo limite da compreensão de vídeo (s)`},help:{"v1-e8rzsy-33":`Tempo limite padrão para solicitações de compreensão de vídeo. Aumente-o para clipes mais longos ou modelos locais de análise mais lentos.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Lista de ações de mensagem permitidas`},help:{"v1-1iceqwa-5c":`Lista global de ações de mensagem permitidas para a ferramenta de mensagens. Use apenas quando todo o ambiente de execução precisar disponibilizar e aceitar um conjunto reduzido de ações; prefira listas de permissões por agente para agentes públicos ou em ambientes isolados.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Ativar transmissão de mensagens`},help:{"v1-1ms74z7-14":`Ativa a ação de transmissão (padrão: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Permitir envios entre contextos (entre provedores)`},help:{"v1-276qxo-2s":`Permitir envios entre provedores diferentes (padrão: true). Defina como false para bloquear mensagens entre provedores.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Permitir entre contextos (mesmo provedor)`},help:{"v1-1sg4x49-1z":`Permitir envios para outros canais dentro do mesmo provedor (padrão: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Marcador entre contextos`},help:{"v1-1fg6jrp-1z":`Adicionar um marcador de origem visível ao enviar entre contextos (padrão: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefixo do marcador entre contextos`},help:{"v1-eblsru-1p":`Prefixo de texto para marcadores entre contextos (aceita "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Sufixo do marcador entre contextos`},help:{"v1-1nk0jub-1p":`Sufixo de texto para marcadores entre contextos (aceita "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Perfil de ferramentas`},help:{"v1-h6k98q-5k":`Nome do perfil global de ferramentas usado para selecionar uma política base predefinida de ferramentas antes de aplicar substituições de permissão ou bloqueio. Use esta opção para manter uma postura consistente do ambiente entre os agentes e mantenha os nomes dos perfis estáveis.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Política de ferramentas do ambiente isolado`},help:{"v1-ea7awo-4k":`Camada de política de ferramentas para execuções de agentes em ambientes isolados, permitindo que essas execuções tenham limites de capacidade distintos. Use esta opção para reforçar a segurança em contextos isolados.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Política de permissão/bloqueio de ferramentas do ambiente isolado`},help:{"v1-ub701o-4t":`Política de permissão/bloqueio de ferramentas aplicada quando os agentes são executados em ambientes de execução isolados. Mantenha as políticas mínimas para que as tarefas nesses ambientes não possam se expandir para ações externas desnecessárias.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Visibilidade das ferramentas de sessão`},help:{"v1-1vtq2rh-c5":`Controla quais sessões podem ser acessadas por sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all", padrão = qualquer sessão no Gateway, incluindo as de outros agentes e usuários; "agent" = qualquer sessão no ID do agente atual; "self" = somente a atual; "tree" = sessão atual + sessões de subagentes criados). O acesso entre agentes é ativado por padrão e delimitado por tools.agentToAgent; use uma visibilidade mais limitada para restringir o acesso.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Política de ferramentas dos subagentes`},help:{"v1-1xoug01-4z":`Camada de política de ferramentas para subagentes criados, que permite restringir ou ampliar a disponibilidade de ferramentas em relação aos padrões do agente principal. Use-a para manter os recursos dos agentes delegados dentro do escopo da tarefa.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Política de permissão e bloqueio de ferramentas dos subagentes`},help:{"v1-7vxsbf-5d":`Política de permissão e bloqueio de ferramentas aplicada aos ambientes de execução dos subagentes criados. Mantenha-a mais restrita que o escopo do agente principal. Ferramentas exclusivas do agente principal, como progress_card, são sempre bloqueadas, inclusive por meio de allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Enxame`},help:{"v1-1q96vvs-45":`Orquestração de subagentes no modo coletor. Ativada por padrão; defina como false para desativar. As permissões de ferramentas continuam se aplicando a agents_wait e às opções de criação de subagentes do enxame.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Agente padrão do enxame`},help:{"v1-p4alpg-2m":`Agente de destino padrão para criações de subagentes do enxame que omitem agentId. A lista de subagentes permitidos continua se aplicando.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Ativar enxame`},help:{"v1-1nnnrq9-2e":`Ativa subagentes no modo coletor e agents_wait. Ativado por padrão; defina como false para desativar.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Filhos ativos por grupo de enxame`},help:{"v1-kfx6qp-1c":`Número máximo de filhos coletores ativos por grupo de enxame.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Filhos simultâneos do enxame`},help:{"v1-1d46jtm-1s":`Número máximo de filhos coletores em execução simultânea por grupo de enxame.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Total de filhos por grupo de enxame`},help:{"v1-1gc9vl1-1e":`Número máximo de coletores criados ao longo da vida de cada grupo de enxame.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Tempo limite máximo de espera do enxame`},help:{"v1-bog18y-1g":`Tempo limite máximo aceito por agents_wait, em segundos.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Busca de ferramentas`},help:{"v1-s0kx04-7y":`Compacte grandes catálogos de ferramentas do OpenClaw, do MCP e do cliente. Os ambientes de execução do OpenClaw usam o Tool Search estruturado automaticamente quando a opção não está definida; o Code Mode, quando ativado, tem precedência, e o Codex usa sua busca nativa. Defina false para desativar, true para a ponte de código ou use o formato de objeto para escolher um modo.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Tempo limite do código de busca de ferramentas`},help:{"v1-105r499-34":"Tempo máximo em milissegundos para uma execução de `tool_search_code`. O ambiente de execução restringe os valores ao intervalo compatível de 1 a 60 segundos."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Ativar busca de ferramentas`},help:{"v1-1vm3hfr-4h":"Ativa a busca de ferramentas. Quando ativada, o OpenClaw oculta grandes catálogos de ferramentas por trás de `tool_search_code` ou de ferramentas estruturadas de busca, descrição e chamada durante as execuções no ambiente integrado."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Máximo de resultados da busca de ferramentas`},help:{"v1-7du4kh-32":`Número máximo de resultados da busca de ferramentas que um modelo pode solicitar. Em tempo de execução, os valores são limitados ao intervalo compatível de 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interface de busca de ferramentas`},help:{"v1-jybcbe-7x":'Escolha a interface apresentada ao modelo: "code" expõe `tool_search_code`; "tools" expõe ferramentas estruturadas alternativas de busca/descrição/chamada; "directory" mantém um diretório limitado de ferramentas visível, expõe um conjunto limitado de esquemas prováveis ou obrigatórios e deixa os demais acessíveis por busca/descrição/chamada.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Resultados padrão da busca de ferramentas`},help:{"v1-1uchq7t-39":"Número padrão de resultados da busca de ferramentas retornados quando o modelo omite um limite. Em tempo de execução, esse valor é limitado a `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Ativar ferramenta de plano estruturado`},help:{"v1-1xgegme-4o":"Ferramenta unificada de status `progress_card` para planos persistentes e notas narrativas em sessões principais. Ativada por padrão; defina como false para desativar. Sempre indisponível para subagentes."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Ferramentas da web`},help:{"v1-fpsy5-4y":`Grupo de políticas de ferramentas da web para ajustar provedores de busca/obtenção de conteúdo, limites e comportamento alternativo. Mantenha as configurações ativadas alinhadas à disponibilidade das chaves de API e à política de tráfego de saída da rede.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL do cache de obtenção de conteúdo da web (min)`},help:{"v1-1hk89qp-17":`TTL do cache em minutos para resultados de web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Ativar ferramenta de obtenção de conteúdo da web`},help:{"v1-yrswld-1f":`Ativar a ferramenta web_fetch (obtenção leve de conteúdo via HTTP).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Cabeçalhos de requisição da busca na web`},help:{"v1-16bjkv5-me":"Cabeçalhos de requisição extras enviados com requisições diretas de web_fetch, por exemplo, cabeçalhos de roteamento de gateway ou de autenticação. Todo valor configurado é tratado como sensível e ocultado nas configurações expostas e nas capturas de depuração. Os valores são strings simples, aceitam substituição por ${VAR} e o escape literal global $${VAR}, e são enviados a URLs escolhidas pelo modelo. As entradas são validadas quando a requisição é montada, e não ao carregar a configuração. Assim, um nome inválido ou um valor que não possa ser enviado é descartado e registrado no log, em vez de desativar o recurso; Accept, Accept-Language, User-Agent e cabeçalhos de enquadramento, como Transfer-Encoding, também são descartados. Use tools.web.fetch.userAgent para alterar o agente de usuário. Redirecionamentos entre origens mantêm apenas os cabeçalhos da lista de permissões de cabeçalhos seguros do guarded-fetch, e a alteração dos cabeçalhos efetivamente enviados particiona o cache de busca."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Máximo de caracteres da busca na web`},help:{"v1-12d1fw7-1d":`Máximo de caracteres retornados por web_fetch (com truncamento).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Limite absoluto de caracteres da busca na web`},help:{"v1-cl2mf1-1v":`Limite absoluto de maxChars do web_fetch (aplicável à configuração e às chamadas de ferramentas).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Máximo de redirecionamentos da busca na web`},help:{"v1-t6eak9-1h":`Máximo de redirecionamentos permitidos para web_fetch (padrão: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Tamanho máximo de download da busca na web (bytes)`},help:{"v1-q6ld9c-10":`Tamanho máximo de download antes do truncamento.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Provedor de busca na web`},help:{"v1-6pb3nv-v":`ID do provedor alternativo de busca na web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extração com Readability na busca na web`},help:{"v1-19exqzx-2c":`Use Readability para extrair o conteúdo principal do HTML (recorre à limpeza básica de HTML em caso de falha).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Política de SSRF da busca na web`},help:{"v1-qtn7zx-3c":`Substituições de escopo limitado da política de SSRF para web_fetch. Mantenha o escopo restrito e ative apenas em ambientes conhecidos com proxy de rede local.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Nomes de host permitidos na busca na web`},help:{"v1-1j9ctya-35":`Nomes de host exatos ou endereços IP literais permitidos para web_fetch, incluindo destinos que seriam bloqueados de outra forma. Mantenha a lista mínima.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Permitir faixa de endereços locais únicos IPv6 na busca na web`},help:{"v1-1eyz55i-3b":`Permita endereços locais únicos IPv6 (fc00::/7) para compatibilidade com proxies confiáveis de IP fictício, como sing-box, Clash ou Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Permitir faixa de testes de desempenho RFC 2544 na busca na web`},help:{"v1-u5asdb-2y":`Permita IPs da faixa de testes de desempenho RFC 2544 (198.18.0.0/15) para compatibilidade com proxies de IP fictício, como Clash ou Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Nomes de host bloqueados na busca na web`},help:{"v1-1164vvk-66":`Padrões de nomes de host bloqueados antes da resolução DNS e das regras de permissão em cada redirecionamento de web_fetch. Aceita hosts exatos e "*.example.com" apenas para subdomínios; adicione "example.com" separadamente para bloquear o domínio raiz. Se estiver vazio ou não definido, não adiciona bloqueios.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Permitir acesso perigoso à rede privada na obtenção de conteúdo da web`},help:{"v1-2s6mv7-3t":`Permite que web_fetch acesse destinos em redes privadas e internas. Mantenha desativado, a menos que as URLs selecionadas pelo modelo sejam confiáveis nesta implantação.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Tempo limite da obtenção de conteúdo da web (s)`},help:{"v1-1c3yfr4-16":`Tempo limite em segundos para solicitações de web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent da obtenção de conteúdo da web`},help:{"v1-s7pe8j-1e":`Substitui o cabeçalho User-Agent das solicitações de web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Proxy confiável de ambiente para obtenção de conteúdo da web`},help:{"v1-1ypkqj7-54":`Encaminha web_fetch por um proxy HTTP(S) confiável configurado por variáveis de ambiente e permite que o proxy resolva o DNS. Ative apenas quando esse proxy for controlado pelo operador e aplicar a política de tráfego de saída após a resolução DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL do cache de pesquisa na web (min)`},help:{"v1-6trzlf-18":`TTL do cache em minutos para resultados de web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Ativar ferramenta de pesquisa na web`},help:{"v1-n1cm4y-27":`Ativa web_search gerenciado e a pesquisa nativa opcional do Codex para modelos compatíveis.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Máximo de resultados da pesquisa na web`},help:{"v1-mrw7mi-z":`Número de resultados a retornar (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Domínios permitidos do Codex`},help:{"v1-1cv4y44-43":`Lista de domínios permitidos para web_search nativo do Codex. Nos turnos com pesquisa hospedada nativa, ela também restringe o web_fetch gerenciado; os turnos com provedor gerenciado permanecem inalterados.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Tamanho do contexto de pesquisa do Codex`},help:{"v1-antack-1u":`Indicação do tamanho do contexto da pesquisa nativa do Codex: "low", "medium" ou "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Ativar pesquisa nativa na web do Codex`},help:{"v1-ek2jzd-1k":`Ativar a pesquisa nativa na web do Codex para modelos compatíveis com o Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Modo de pesquisa na web do Codex`},help:{"v1-1ahyq9f-32":`Preferência de pesquisa nativa na web do Codex: "cached" (padrão; turnos do Codex sem restrições usam live) ou "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Cidade do usuário do Codex`},help:{"v1-1y95orp-1d":`Cidade aproximada enviada à pesquisa nativa na web do Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`País do usuário do Codex`},help:{"v1-1xkm5ms-1g":`País aproximado enviado à pesquisa nativa na web do Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Região do usuário do Codex`},help:{"v1-lhar02-1l":`Região/estado aproximado enviado à pesquisa nativa na web do Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Fuso horário do usuário do Codex`},help:{"v1-fgv9fh-1h":`Fuso horário aproximado enviado à pesquisa nativa na web do Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Provedor de pesquisa na web`},help:{"v1-10omglr-1x":`ID do provedor de pesquisa. Detectado automaticamente a partir das chaves de API disponíveis, se omitido.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Tempo limite da pesquisa na web (s)`},help:{"v1-i0egvw-17":`Tempo limite em segundos para solicitações de web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transcrições`},help:{"v1-1i0sc09-66":`Configurações principais de captura de transcrições para notas de reunião, ferramentas de agente com capacidade de gravação e fontes configuradas de início automático de reuniões ao vivo. Os plugins de reunião capturam notas persistentes por padrão; defina enabled como false para desativar globalmente.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Fontes de início automático de transcrições`},help:{"v1-1mzsl79-5s":`Fontes de transcrição ao vivo gerenciadas automaticamente a partir da inicialização do Gateway. Cada entrada é ativada pela sua presença; remova uma entrada para desativar essa fonte. As fontes capturam continuamente, exceto quando whenOccupied está ativado.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`ID da conta de transcrição`},help:{"v1-6g2kjj-4b":`Identificador opcional de conta do provedor ou espaço de trabalho para fontes de transcrição que precisam distinguir entre contas. Use o formato de ID de conta documentado pelo provedor.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID do canal de transcrição`},help:{"v1-1lk9d5o-4u":`ID do canal no provedor para a fonte de transcrição ao vivo, como um canal de voz do Discord ou um canal de conversa em grupo do Slack. Verifique a semântica dos IDs específica do provedor antes de ativar o início automático.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID do servidor do Discord`},help:{"v1-fyfgnk-4l":`ID opcional do servidor do Discord para fontes de transcrição de voz do Discord. Configure este campo com o channelId correspondente quando o provedor precisar buscar canais de voz no escopo do servidor.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL da reunião para transcrição`},help:{"v1-1xtt9ci-4f":`URL opcional da reunião para provedores que entram por URL em vez de ID do canal. Use apenas links de reunião confiáveis, pois o início automático pode entrar nessa reunião e capturá-la.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID do provedor da fonte de transcrição`},help:{"v1-1uur06p-3s":`ID do provedor da fonte de transcrição, como um provedor de voz do Discord ou um futuro provedor de conversas em grupo do Slack. Use o ID exato disponibilizado pelo plugin do provedor.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID da sessão de transcrição`},help:{"v1-xyo4x5-5o":`ID fixo opcional da sessão de transcrição para esta fonte de início automático. Ignorado quando whenOccupied é true. Deixe sem definir para que os IDs sejam gerados, a menos que você precise de um seletor diário estável e possa evitar colisões no mesmo dia.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Título da transcrição`},help:{"v1-ycjnmp-5y":`Título opcional para futuras capturas de transcrição. Alterar apenas os títulos mantém as capturas atuais em execução e não renomeia o título atribuído a elas nem as notas salvas. Outras alterações na fonte mantêm o comportamento normal de reinicialização.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Captura de transcrição quando houver participantes`},help:{"v1-34jid4-78":`Inicia uma nova sessão de transcrição sempre que houver pessoas presentes na fonte e a encerra (gerando notas) após a saída da última pessoa. Requer um provedor que informe a presença de participantes, como discord-voice. Padrão: false (captura continuamente desde a inicialização do Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transcrições ativadas`},help:{"v1-fyqqr0-6d":`Ativa notas automáticas persistentes de reuniões, a ferramenta transcripts do agente e as fontes configuradas para início automático. Padrão: true. Defina como false para desativar a persistência e a ferramenta; o modo explícito de transcrição de reuniões mantém seu trecho final limitado em tempo real.`}},tts:{label:{"v1-bmxkk9-e":`Conversão de texto em fala`},help:{"v1-1o27tk2-4n":`Política de conversão de texto em fala para ler as respostas do agente em voz alta nas interfaces de voz ou áudio compatíveis. Mantenha desativada, a menos que a reprodução de voz faça parte do fluxo de trabalho do operador ou usuário.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Persona de TTS`},help:{"v1-1r0opcb-29":`ID da persona de TTS padrão. As preferências locais de persona de TTS podem substituir esse valor em cada host.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Personas de TTS`},help:{"v1-19aybhl-2l":`Personas de TTS nomeadas que definem uma identidade vocal estável e associações de fala específicas de cada provedor.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Persona de TTS`},help:{"v1-10s52ah-2l":`Uma persona de TTS. Use associações específicas do provedor para definir vozes/modelos exatos e modelos de prompt.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Vínculos de provedores da persona de TTS`},help:{"v1-993jop-3e":`Vínculos da persona de TTS específicos de cada provedor, indexados pelo ID do provedor de fala. Eles são mesclados com tts.providers, com precedência para a persona ativa.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Configurações dos provedores de TTS`},help:{"v1-1k80nl4-4y":`Configurações de TTS específicas de cada provedor, indexadas pelo ID do provedor de fala. Use esta opção em vez das chaves de nível superior específicas dos provedores integrados para manter os plugins de fala desacoplados do esquema de configuração principal.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Configuração do provedor de TTS`},help:{"v1-dwapva-3d":`Configuração de TTS específica para um ID de provedor de fala. Mantenha os campos restritos ao plugin responsável por esse provedor.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Chave de API do provedor de TTS`},help:{"v1-1m2fj0i-2o":`Chave de API usada por esse provedor de fala quando seu plugin exige acesso autenticado ao TTS.`}},tui:{label:{"v1-c8hus1-b":`Interface do terminal`},help:{"v1-1fg9vw2-3s":`Configurações de exibição da interface do terminal. Use esta seção para preferências de apresentação exclusivas do terminal, sem alterar o comportamento do Gateway ou de outras interfaces.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Rodapé da interface do terminal`},help:{"v1-6e12l3-3k":`Configurações de exibição do rodapé da interface do terminal. Mantenha o contexto opcional compacto para que as informações de sessão, modelo, objetivo e tokens permaneçam legíveis.`}},ui:{label:{"v1-ye4dff-2":`Interface`},help:{"v1-dt1924-42":`Configurações de apresentação da interface para destaques e preferências de exibição do operador. Use esta opção para personalizar a legibilidade sem alterar o comportamento em tempo de execução.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Cor de destaque do usuário`},help:{"v1-16klzws-4z":`Cor de destaque da Control UI: #RRGGBB para uma cor personalizada ou 'theme' para a paleta do tema selecionado. Substitui ui.seamColor; limpe o valor para herdar a cor de junção configurada ou o padrão do tema.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Cor de destaque`},help:{"v1-14q3r4h-4g":`Cor de destaque principal usada nas superfícies da interface para dar ênfase, exibir indicadores e reforçar a identidade visual. Use valores de alto contraste que permaneçam legíveis nos temas claro e escuro.`}},update:{label:{"v1-k12u1x-7":`Atualizações`},help:{"v1-11c5k8v-5c":`Comportamento do canal de atualização e da verificação na inicialização para manter as versões do ambiente de execução do OpenClaw atualizadas. Use canais conservadores em produção e canais mais experimentais apenas em ambientes controlados.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Atualização automática ativada`},help:{"v1-49xs2h-3c":`Ativa a atualização automática em segundo plano para instalações por pacote dos canais stable e beta; no canal extended-stable, as atualizações nunca são aplicadas automaticamente (padrão: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Canal de atualização`},help:{"v1-lqtdvf-5b":`Canal de atualização para instalações via git + npm ("stable", "extended-stable", "beta" ou "dev"). O canal extended-stable é exclusivo para pacotes: a instalação ocorre apenas em primeiro plano, com avisos opcionais somente de leitura na inicialização.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Verificação de atualizações na inicialização`},help:{"v1-qy3q9g-5v":`Verifica se há atualizações quando o Gateway é iniciado, incluindo avisos de extended-stable somente para leitura (padrão: true). Defina como false para desativar as verificações e aplicações automáticas de atualizações do Gateway e de nós sem interface gráfica, bem como os pings anônimos de atualização.`}},voicewake:{label:{"v1-txt1wb-a":`Ativação por voz`}},web:{label:{"v1-1ae9z56-b":`Canal web`}},wizard:{label:{"v1-28jonk-h":`Preferências de configuração`},help:{"v1-14jh6rm-3b":`Preferências de configuração gerenciadas pelo usuário. O histórico do assistente e o estado de confirmação gerenciados pela máquina ficam no banco de dados de estado compartilhado.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Acesso à descoberta na configuração`},help:{"v1-1nqxt0w-38":`Consentimento de descoberta para a configuração guiada: "full" faz a varredura silenciosamente, enquanto "guarded" solicita permissão antes de inspecionar aplicativos locais.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Recomendações de aplicativos na configuração`},help:{"v1-ub8uoi-30":`Controla se a configuração guiada pode usar os nomes dos aplicativos instalados para recomendar plugins e habilidades relevantes.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Data e hora da última execução do assistente`},help:{"v1-1y0fbk-1k":`Data e hora da última execução do assistente salva com sucesso.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Comando da última execução do assistente`},help:{"v1-x2pfkk-15":`Comando que iniciou a última execução do assistente.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit da última execução do assistente`},help:{"v1-h0jkmt-1i":`Commit do código-fonte usado na última execução do assistente em desenvolvimento.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Modo da última execução do assistente`},help:{"v1-16508qy-1r":`Indica se a última execução do assistente foi destinada à configuração "local" ou "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Versão da última execução do assistente`},help:{"v1-1tr4z9d-19":`Versão do OpenClaw usada na última execução do assistente.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Data e hora da confirmação de segurança do assistente`},help:{"v1-86i182-2a":`Data e hora da confirmação de segurança da configuração, salvas junto com a configuração de destino.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Aceleração de worktrees`},help:{"v1-9es3gc-4r":`Use a aceleração do sistema de arquivos para novos worktrees gerenciados quando houver suporte (padrão: true). Defina como false para usar o checkout normal do Git e a cópia de arquivos. Aplica-se apenas a novos worktrees.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Diretório raiz das árvores de trabalho`},help:{"v1-1tgti9j-5d":`Diretório global para novas árvores de trabalho gerenciadas. Use um caminho absoluto ou ~ para seu diretório pessoal; o padrão é <state-dir>/worktrees. As árvores de trabalho existentes mantêm seus caminhos registrados quando esse valor é alterado.`}}}}})))()}export{t as n,n as t};